// ==========================================
// 🎨 VFX ASSET SCHEMA (Data-Driven)
// ==========================================

export type ParticleType = 'SPARK' | 'SMOKE' | 'SMOKE_PUFF' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'BLAST' | 'CHIP' | 'PILLAR' | 'HEX_GLOW' | 'GRID_FIELD' | 'DOMAIN' | 'SPRITE' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'STREAK' | 'RING' | 'CRACKS' | 'PEBBLE' | 'RUBBLE' | 'SPIKE' | 'DUST' | 'ATMOSPHERE' | 'MAGIC_CIRCLE' | 'GENERIC_DEBUG';
export type EmitterShape = 'POINT' | 'CIRCLE' | 'CONE' | 'BURST_DIR';
export type BlendMode = 'source-over' | 'lighter' | 'screen' | 'overlay' | 'multiply' | 'difference';

// Range Helper [min, max] or number
export type Range = [number, number]; 

export interface EmitterConfig {
    // Identity
    id?: string;
    particleType: ParticleType;
    textureId?: string; // Optional: If specific texture needed from VFXFactory

    // Visual Style Reference (New)
    // Points to entries in BEAM_VISUALS or PROCEDURAL_VISUALS
    visualStyle?: string; 

    // Spawning Logic
    count: number | Range; // How many particles
    delay: number | Range; // Start delay
    lifetime: Range;       // How long particles live

    // Physics
    speed: Range;
    gravity?: number;      // Override default gravity
    drag?: number;         // Air resistance (0-1)

    // Visuals
    size: Range;
    height?: number | Range; // Optional height override (e.g. for Pillars)
    colors: string[];      // Randomly picked from array
    blendMode?: BlendMode;

    // Transform
    shape: EmitterShape;
    shapeRadius?: number;  // For Circle/Cylinder

    // Advanced
    locked?: boolean;      // If true, moves with parent/source
    vRotation?: Range;     // Angular velocity
}

export interface VFXAsset {
    id: string;
    description?: string;
    emitters: EmitterConfig[];
    soundRef?: string;
}

export interface Particle {
    active: boolean; 

    // Position (World Space - Ground Plane)
    x: number;
    y: number;
    z: number; // Current visual Z (Absolute Altitude)

    // Physics
    vx: number;
    vy: number;
    vz: number;

    rotation: number;     
    vRotation: number;    

    life: number;
    maxLife: number;
    color: string;
    size: number;
    height?: number; // Optional visual height override

    // Added RUBBLE, SPIKE, DUST, ATMOSPHERE, GENERIC_DEBUG, MAGIC_CIRCLE
    type: 'SPARK' | 'SMOKE' | 'SMOKE_PUFF' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'HEX_GLOW' | 'STREAK' | 'RING' | 'CRACKS' | 'PEBBLE' | 'RUBBLE' | 'SPIKE' | 'DUST' | 'ATMOSPHERE' | 'MAGIC_CIRCLE' | 'GENERIC_DEBUG';

    // 🎯 BEAM TARGETING (Explicit 3D Anchors)
    sx?: number; sy?: number; sz?: number; 
    tx?: number; ty?: number; tz?: number; 

    targetX?: number; 
    targetY?: number; 
    targetZ?: number; 

    style?: string; 
    delay?: number;
    image?: HTMLCanvasElement; 
    locked?: boolean; 
    drag?: number;
    gravity?: number; // Override default gravity    
    killAtTarget?: number; 
    texture?: HTMLCanvasElement; 
    blendMode?: GlobalCompositeOperation; 
    sortBias?: number; 

    // Physics State Memory
    lastGroundHeight?: number; // Fix for gap clipping
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            // Reset Properties
            p.active = true;
            p.x = 0; p.y = 0; p.z = 0;
            p.vx = 0; p.vy = 0; p.vz = 0;
            p.rotation = 0; p.vRotation = 0;
            p.life = 0; p.maxLife = 0;
            p.color = '#ff00ff'; p.size = 0;
            p.height = undefined;
            p.type = 'GENERIC_DEBUG'; // Distinctive default

            p.sx = undefined; p.sy = undefined; p.sz = undefined;
            p.tx = undefined; p.ty = undefined; p.tz = undefined;

            p.targetX = undefined;
            p.targetY = undefined;
            p.targetZ = undefined;

            p.image = undefined; 
            p.texture = undefined;
            p.blendMode = undefined;
            p.style = undefined; 

            p.delay = 0; 
            p.locked = false; 
            p.sortBias = 0; 
            p.drag = undefined; 
            p.gravity = undefined;
            p.killAtTarget = undefined; 

            p.lastGroundHeight = undefined;

            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#ff00ff', size: 0, height: undefined, type: 'GENERIC_DEBUG',
            delay: 0,
            locked: false,
            sortBias: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        p.texture = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";
import { VFXFactory } from "../../graphics/VFXFactory";

// Helper: Get random number from Range [min, max] or number
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};

// Helper: Pick random color
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};

// List of particles that MUST snap to ground Z
const GROUND_PARTICLES = new Set([
    'SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE', 
    'HEX_GLOW', 'PILLAR', 'DOMAIN'
]);

export class VFXPlayer {

    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        const asset = VFX_REGISTRY[effectId];

        if (!asset) {
            return;
        }

        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride, groundZ);
        }
    }

    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string, groundZ?: number) {
        const count = Math.floor(rnd(config.count));

        // Determine effective Z for this emitter
        // If the particle type is a ground effect and we know where the ground is, snap it.
        // Otherwise use the target Z (which might be body height).
        const isGroundType = GROUND_PARTICLES.has(config.particleType);
        const effectiveZ = (isGroundType && groundZ !== undefined) ? groundZ : cz;

        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();

            // 1. Position & Velocity Calculation based on Shape
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = effectiveZ;
            const speed = rnd(config.speed);

            if (config.shape === 'POINT') {
                // No offset
            } 
            else if (config.shape === 'BURST_DIR') {
                // Omnidirectional Sphere Burst
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);

                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); // Bias upwards slightly
            }
            else if (config.shape === 'CIRCLE') {
                // Flat ring burst
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;

                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }

            // 2. Properties
            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;

            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);

            p.size = rnd(config.size);
            if (config.height !== undefined) p.height = rnd(config.height);

            // Color priority: Override > Config
            p.color = colorOverride || pickColor(config.colors);

            // Type Casting (Ensure string matches Particle internal type)
            p.type = config.particleType as any;

            // Apply Visual Style if defined
            if (config.visualStyle) p.style = config.visualStyle;

            // Optional Physics Overrides
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.vRotation) p.vRotation = rnd(config.vRotation);
            else p.vRotation = (Math.random() - 0.5) * 10; // Default gentle rotation

            if (config.blendMode) p.blendMode = config.blendMode;

            // --- CRITICAL FIX: HYDRATE TEXTURE ---
            // Force load the high-quality Hexagon texture immediately.
            if (!p.image && !['PILLAR', 'BEAM', 'HEX_BEAM', 'GRID_FIELD', 'DOMAIN'].includes(p.type)) {
                // We cast p.type to any because the Factory accepts specific string literals
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }

            // Push to System
            system.state.particles.push(p);
        }
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";

export const ProceduralPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number) {
        ctx.save();
        // NOTE: We assume context is already translated to (drawX, drawY) by the caller

        if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
             // Beams usually handle their own transform because they connect two points.
             // Skipped here as ProjectileRenderer or VFXSystem handles beams explicitly.
        }
        else if (p.type === 'HEX_BEAM' || p.type === 'GIANT_HEX') {
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            // KEY FIX: Use traceRotatedHex with applyIso=true to ensure
            // the spinning hexagon matches the floor perspective perfectly.

            if (p.type === 'GIANT_HEX') {
                ctx.globalCompositeOperation = 'source-over';

                // Solid Core
                ctx.fillStyle = p.color; 
                ctx.globalAlpha = 1.0;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true);
                ctx.fill();

                // Bright Rim
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 4;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true);
                ctx.stroke();

                // Inner Detail (Counter-rotating)
                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, -rot * 1.5, true);
                ctx.fill();

                // Black Hole Center (Optional style)
                if (p.color === '#000' || p.color === '#000000' || p.color === '#0f172a') {
                    ctx.save();
                    // Keep center circular as it's a singularity
                    ctx.scale(1, ISO_SCALE_Y); // Match ISO for the hole too
                    ctx.fillStyle = '#000';
                    ctx.shadowColor = '#8b5cf6'; 
                    ctx.shadowBlur = 20;
                    ctx.beginPath(); ctx.arc(0, 0, p.size * 0.4, 0, Math.PI * 2); ctx.fill();

                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    ctx.shadowBlur = 0;
                    ctx.beginPath(); ctx.arc(0, 0, p.size * 0.42, 0, Math.PI * 2); ctx.stroke();
                    ctx.restore();
                }

            } else {
                // HEX_BEAM (Energy / Wireframe style)
                ctx.globalCompositeOperation = 'screen';

                // Gradient for the "beam" look
                // Note: Radial gradient in 2D doesn't look ISO unless we scale it.
                ctx.save();
                ctx.scale(1, ISO_SCALE_Y);
                const grad = ctx.createRadialGradient(0,0,0,0,0,p.size);
                grad.addColorStop(0, p.color); 
                grad.addColorStop(0.8, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.restore();

                ctx.globalAlpha = (1 - progress) * 0.8;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true);
                ctx.fill();

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.9, rot, true);
                ctx.stroke();
            }
        }
        else if (p.type === 'PILLAR') {
            const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
            const def = rawDef as PillarVisualDef;
            const h = p.height || def.height || 1200; 
            const width = p.size * (1 - progress * 0.5) * (def.widthScale || 1.0);

            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            // Pillar Body (Vertical Rectangle)
            const cylinderGrad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
            cylinderGrad.addColorStop(0, p.color); 
            cylinderGrad.addColorStop(0.5, '#ffffff'); 
            cylinderGrad.addColorStop(1, p.color); 

            ctx.fillStyle = cylinderGrad;
            ctx.globalAlpha = (1 - progress) * 0.8;

            // Draw from base (0) upwards (-h)
            ctx.fillRect(-width/2, -h, width, h);

            // Base Ring (On Floor)
            if (def.hasBaseRing) {
                ctx.save();
                // Ensure ring is ISO
                ctx.scale(1, ISO_SCALE_Y);
                const ringGrad = ctx.createRadialGradient(0,0, width*0.5, 0,0, width*1.2);
                ringGrad.addColorStop(0, 'transparent');
                ringGrad.addColorStop(0.5, p.color);
                ringGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = ringGrad;
                ctx.beginPath(); ctx.arc(0, 0, width*1.5, 0, Math.PI*2); ctx.fill();
                ctx.restore();
            }
        }
        else if (p.type === 'DOMAIN') {
            // Domain is a 3D prism/cylinder area
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 
            const isShield = p.style === 'DOMAIN_SHIELD';
            const h = isShield ? 120 : 40;
            const opacity = 0.4 * (1 - progress);

            VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE');
        }

        ctx.restore();
    }
};

