import { OBSTACLE_STYLES, HEX_SIZE } from "../../constants";
import { createCanvas } from "./CanvasUtils";
import { HexGeometry } from "./utils/HexGeometry"; // The Law

// --- STRICT ALIGNMENT CONSTANTS ---
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  
export const ENV_ANCHOR_Y = 140; 

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // Setup Anchor: (0,0) is now the CENTER of the hexagonal SURFACE on the ground
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        this.drawHexShadow(ctx);

        // 2. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawIsoTree(ctx, style);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawIsoCrystal(ctx, style);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawIsoPillar(ctx, style);
        } else {
            this.drawIsoWall(ctx, style); 
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'];
        this.drawIsoCrystal(ctx, style, 0.7);
        return canvas;
    },

    // --- GEOMETRY PRIMITIVES (UPDATED) ---

    drawHexShadow(ctx: CanvasRenderingContext2D) {
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        const r = HEX_SIZE * 0.9;

        // Use Unified Math: applyIso=true because this is a projected shadow on the floor
        HexGeometry.traceHex(ctx, 0, 0, r, true);

        ctx.fill();
        ctx.restore();
    },

    drawIsoWall(ctx: CanvasRenderingContext2D, style: any) {
        const height = 55;
        const r = HEX_SIZE * 0.9; 

        // Vertices from Source of Truth
        const verts = HexGeometry.getVertices(r, true);

        // Indices for Flat Top Hex (0 deg start):
        // 3: Left, 2: Bottom-Left, 1: Bottom-Right, 0: Right
        const v3 = verts[3];
        const v2 = verts[2];
        const v1 = verts[1];
        const v0 = verts[0];

        // Draw Sides (Extrude Up)
        const topY = -height;

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y); ctx.lineTo(v2.x, v2.y);
        ctx.lineTo(v2.x, v2.y + topY); ctx.lineTo(v3.x, v3.y + topY);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = style.highlight; ctx.lineWidth = 1; ctx.stroke();

        // Front Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y); ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY); ctx.lineTo(v2.x, v2.y + topY);
        ctx.closePath(); ctx.fill(); ctx.stroke();

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y); ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY); ctx.lineTo(v1.x, v1.y + topY);
        ctx.closePath(); ctx.fill(); ctx.stroke();

        // Top Face (Full Hex)
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true);
        ctx.fill();

        // Inner Detail
        ctx.fillStyle = style.detail;
        ctx.beginPath(); ctx.arc(0, 0, r*0.4, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    drawIsoPillar(ctx: CanvasRenderingContext2D, style: any) {
        const height = 90;
        const r = HEX_SIZE * 0.7; 

        const verts = HexGeometry.getVertices(r, true);
        const v3 = verts[3]; const v2 = verts[2];
        const v1 = verts[1]; const v0 = verts[0];

        const topY = -height;

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y); ctx.lineTo(v2.x, v2.y); 
        ctx.lineTo(v2.x, v2.y + topY); ctx.lineTo(v3.x, v3.y + topY);
        ctx.fill();

        // Front Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y); ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY); ctx.lineTo(v2.x, v2.y + topY);
        ctx.fill();

        // Rune
        ctx.strokeStyle = style.detail;
        ctx.lineWidth = 2;
        ctx.shadowColor = style.detail;
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.moveTo(0, -30); ctx.lineTo(0, -60);
        ctx.moveTo(-5, -45); ctx.lineTo(5, -45);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y); ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY); ctx.lineTo(v1.x, v1.y + topY);
        ctx.fill();

        // Top
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = '#000';
        HexGeometry.traceHex(ctx, 0, 0, r, true);
        ctx.fill();
        ctx.restore();
    },

    drawIsoTree(ctx: CanvasRenderingContext2D, style: any) {
        // Trees are organic, but the base should ideally align.
        // For now, we keep the organic look but ensure it's centered.
        const trunkW = 14;
        const trunkH = 20;

        ctx.fillStyle = '#3f2e1e';
        ctx.beginPath();
        ctx.fillRect(-trunkW/2, -trunkH, trunkW, trunkH + 5); 

        const layers = 3;
        const baseWidth = 48;
        const layerHeight = 35;
        const overlap = 15;
        let currentY = -trunkH + 5;

        for (let i = 0; i < layers; i++) {
            const ratio = 1 - (i / layers);
            const width = baseWidth * (0.6 + ratio * 0.4);
            const height = layerHeight;

            ctx.beginPath();
            ctx.moveTo(0, currentY - height); 
            ctx.lineTo(width/2, currentY);    
            ctx.quadraticCurveTo(0, currentY + 10, -width/2, currentY); 
            ctx.closePath();

            const grad = ctx.createLinearGradient(0, currentY - height, 0, currentY);
            grad.addColorStop(0, style.highlight);
            grad.addColorStop(0.5, style.main);
            grad.addColorStop(1, style.dark);
            ctx.fillStyle = grad;
            ctx.fill();

            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 1;
            ctx.stroke();

            currentY -= (height - overlap);
        }
    },

    drawIsoCrystal(ctx: CanvasRenderingContext2D, style: any, alpha: number = 1.0) {
        const drawShard = (x: number, y: number, w: number, h: number, tilt: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(tilt);

            ctx.fillStyle = style.dark;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-w, -h * 0.2);
            ctx.lineTo(0, -h); 
            ctx.lineTo(w, -h * 0.3);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = style.light;
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(w, -h * 0.3);
            ctx.lineTo(0, -h);
            ctx.fill();

            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(0, -h);
            ctx.stroke();

            ctx.restore();
        };

        drawShard(-10, 5, 10, 50, -0.2);
        drawShard(10, 2, 12, 40, 0.2);
        drawShard(0, 8, 18, 70, 0); 
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

// High fidelity texture size for runtime scaling
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Clears the cache. Call this if High-DPI settings change or context is lost.
     */
    public reset() {
        this.cache.clear();
    }

    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Alias Normalization
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        // Create Canvas
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);

        // Standard Radius for tile-based effects
        const r = 40; 

        // --- GENERATION LOGIC ---
        // CRITICAL RULE: For Ground Effects (Grid, Shockwave, Zone), draw REGULAR geometry (applyIso = false).
        // The Runtime Painter (GroundPainter) applies the ISO scale (scale Y).

        switch (type) {
            // --- GROUND EFFECTS (REGULAR GEOMETRY) ---
            case 'ZONE_BASE':
            case 'HEX_GLOW':
                this.drawRegularHexFill(ctx, r, color, true); // Glow fill
                break;

            case 'GRID_FIELD':
                this.drawRegularHexGrid(ctx, r, color);
                break;

            case 'SHOCKWAVE':
                this.drawRegularHexRing(ctx, r, color, 4);
                break;

            case 'MAGIC_CIRCLE':
                // Note: ProceduralPainter usually handles rotation, but if used as texture:
                this.drawRegularHexRing(ctx, r, color, 2);
                this.drawRegularHexRing(ctx, r * 0.6, color, 1);
                break;

            case 'CRACKS':
                // Organic lines, drawn in regular space
                this.drawCracks(ctx, r, color);
                break;

            case 'SHADOW_BLOB':
                // Simple soft circle
                ctx.fillStyle = color;
                ctx.filter = 'blur(8px)';
                ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.fill();
                ctx.filter = 'none';
                break;

            // --- BILLBOARD SPRITES (FACE CAMERA) ---
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;

            case 'CLOUD': 
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;

            case 'SPIKE':
            case 'SPARK':
                // Spikes are "Star" shapes drawn flat
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;

            // --- PHYSICAL DEBRIS ---
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                // Debris is irregular. We use a small hex as a base for rocks.
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;

            // --- ICONS & SYMBOLS ---
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;

            case 'BEAM':
                // Generic Beam Segment
                const grad = ctx.createLinearGradient(-r, 0, r, 0);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.5, color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.fillRect(-r*2, -r, r*4, r*2);
                break;

            default:
                // Fallback Dot
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // =========================================================================================
    // 📐 GEOMETRY PRIMITIVES (STRICTLY USING HEXGEOMETRY)
    // =========================================================================================

    private drawRegularHexFill(ctx: CanvasRenderingContext2D, r: number, color: string, glow: boolean) {
        if (glow) {
            const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
        } else {
            ctx.fillStyle = color;
        }
        // applyIso = false
        HexGeometry.traceHex(ctx, 0, 0, r, false); 
        ctx.fill();
    }

    private drawRegularHexRing(ctx: CanvasRenderingContext2D, r: number, color: string, width: number) {
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        // applyIso = false
        HexGeometry.traceHex(ctx, 0, 0, r, false); 
        ctx.stroke();
    }

    private drawRegularHexGrid(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        // Outer
        HexGeometry.traceHex(ctx, 0, 0, r * 0.9, false);
        ctx.stroke();

        // Inner Cross (Manual is fine here for style, but keep it geometric)
        ctx.beginPath();
        ctx.moveTo(-r*0.5, 0); ctx.lineTo(r*0.5, 0);
        ctx.moveTo(0, -r*0.5); ctx.lineTo(0, r*0.5);
        ctx.stroke();
    }

    private drawCracks(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        // 3-point fracture
        for(let i=0; i<3; i++) {
            const a = (Math.PI*2/3)*i;
            ctx.moveTo(0,0);
            ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            // Branch
            ctx.moveTo(Math.cos(a)*r*0.5, Math.sin(a)*r*0.5);
            ctx.lineTo(Math.cos(a+0.5)*r*0.8, Math.sin(a+0.5)*r*0.8);
        }
        ctx.stroke();
    }

    // --- TERRAIN & PROJECTILES ---

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        // Terrain Details are drawn on the TOP FACE of the block.
        // The TerrainRenderer already handles the isometric top face projection manually (or via transform).
        // However, usually textures are applied flat. 
        // To match the aesthetic, we pre-squash these if they are meant to lie flat.

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        ctx.translate(size/2, size/2);

        // Apply ISO manually here because TerrainRenderer might draw this simply as an image on top
        ctx.scale(1, 0.58); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        for(let i=0; i<5; i++) {
            const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
            const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
            if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
            ctx.beginPath();
            ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
            ctx.fill();
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);

        // Projectiles are side-view billboards usually
        switch (visual) {
            case 'HEX_DART': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;

        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { OBSTACLE_STYLES, HEX_SIZE } from "../../constants";
import { createCanvas } from "./CanvasUtils";
import { HexGeometry } from "./utils/HexGeometry"; // The Source of Truth

// --- STRICT ALIGNMENT CONSTANTS ---
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  
export const ENV_ANCHOR_Y = 140; 

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // Setup Anchor: (0,0) is the CENTER of the hexagonal SURFACE on the ground
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        // applyIso = true (Because this is a static sprite drawn 1:1 in world space)
        this.drawHexShadow(ctx);

        // 2. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawIsoTree(ctx, style);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawIsoCrystal(ctx, style);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawIsoPillar(ctx, style);
        } else {
            this.drawIsoWall(ctx, style); // Default Wall/Sandstone
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        // Special case for Frozen Status Model
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'];

        this.drawIsoCrystal(ctx, style, 0.7);
        return canvas;
    },

    // =========================================================================================
    // 🏗️ GEOMETRY BUILDERS (STRICTLY USING HEXGEOMETRY)
    // =========================================================================================

    drawHexShadow(ctx: CanvasRenderingContext2D) {
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        const r = HEX_SIZE * 0.9;

        // Truth: Shadow is on the floor, so it must be ISO projected.
        HexGeometry.traceHex(ctx, 0, 0, r, true);

        ctx.fill();
        ctx.restore();
    },

    drawIsoWall(ctx: CanvasRenderingContext2D, style: any) {
        const height = 55;
        const r = HEX_SIZE * 0.9; // Slightly smaller than tile to show edges

        // Truth: Get vertices pre-squashed for ISO
        const verts = HexGeometry.getVertices(r, true);

        // Indices for Flat Top Hex (0 deg start):
        // 0: Right, 1: BotRight, 2: BotLeft, 3: Left, 4: TopLeft, 5: TopRight
        // Visible faces from South: Left(3-2), Front(2-1), Right(1-0)

        const v3 = verts[3];
        const v2 = verts[2];
        const v1 = verts[1];
        const v0 = verts[0];

        const topY = -height;

        // Left Face (v3 -> v2)
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y); ctx.lineTo(v2.x, v2.y);
        ctx.lineTo(v2.x, v2.y + topY); ctx.lineTo(v3.x, v3.y + topY);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = style.highlight; ctx.lineWidth = 1; ctx.stroke();

        // Front Face (v2 -> v1)
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y); ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY); ctx.lineTo(v2.x, v2.y + topY);
        ctx.closePath(); ctx.fill(); ctx.stroke();

        // Right Face (v1 -> v0)
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y); ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY); ctx.lineTo(v1.x, v1.y + topY);
        ctx.closePath(); ctx.fill(); ctx.stroke();

        // Top Face (Full Hex)
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.9;
        // Top face is same shape as base
        HexGeometry.traceHex(ctx, 0, 0, r, true);
        ctx.fill();

        // Inner Detail
        ctx.fillStyle = style.detail;
        ctx.beginPath(); ctx.arc(0, 0, r*0.4, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    drawIsoPillar(ctx: CanvasRenderingContext2D, style: any) {
        const height = 90;
        const r = HEX_SIZE * 0.7; // Thinner

        const verts = HexGeometry.getVertices(r, true);
        const v3 = verts[3]; const v2 = verts[2];
        const v1 = verts[1]; const v0 = verts[0];

        const topY = -height;

        // Left Face
        ctx.fillStyle = style.dark;
        ctx.beginPath();
        ctx.moveTo(v3.x, v3.y); ctx.lineTo(v2.x, v2.y); 
        ctx.lineTo(v2.x, v2.y + topY); ctx.lineTo(v3.x, v3.y + topY);
        ctx.fill();

        // Front Face
        ctx.fillStyle = style.main;
        ctx.beginPath();
        ctx.moveTo(v2.x, v2.y); ctx.lineTo(v1.x, v1.y);
        ctx.lineTo(v1.x, v1.y + topY); ctx.lineTo(v2.x, v2.y + topY);
        ctx.fill();

        // Rune
        ctx.strokeStyle = style.detail;
        ctx.lineWidth = 2;
        ctx.shadowColor = style.detail;
        ctx.shadowBlur = 5;
        ctx.beginPath();
        ctx.moveTo(0, -30); ctx.lineTo(0, -60);
        ctx.moveTo(-5, -45); ctx.lineTo(5, -45);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // Right Face
        ctx.fillStyle = style.light;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y); ctx.lineTo(v0.x, v0.y);
        ctx.lineTo(v0.x, v0.y + topY); ctx.lineTo(v1.x, v1.y + topY);
        ctx.fill();

        // Top
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = '#000';
        HexGeometry.traceHex(ctx, 0, 0, r, true);
        ctx.fill();
        ctx.restore();
    },

    drawIsoTree(ctx: CanvasRenderingContext2D, style: any) {
        // Trees are organic, but base should center.
        const trunkW = 14;
        const trunkH = 20;

        ctx.fillStyle = '#3f2e1e';
        ctx.beginPath();
        ctx.fillRect(-trunkW/2, -trunkH, trunkW, trunkH + 5); 

        const layers = 3;
        const baseWidth = 48;
        const layerHeight = 35;
        const overlap = 15;
        let currentY = -trunkH + 5;

        for (let i = 0; i < layers; i++) {
            const ratio = 1 - (i / layers);
            const width = baseWidth * (0.6 + ratio * 0.4);
            const height = layerHeight;

            // Stylized Cone
            ctx.beginPath();
            ctx.moveTo(0, currentY - height); // Top
            ctx.lineTo(width/2, currentY);    // Right
            ctx.quadraticCurveTo(0, currentY + 10, -width/2, currentY); // Curve
            ctx.closePath();

            const grad = ctx.createLinearGradient(0, currentY - height, 0, currentY);
            grad.addColorStop(0, style.highlight);
            grad.addColorStop(0.5, style.main);
            grad.addColorStop(1, style.dark);
            ctx.fillStyle = grad;
            ctx.fill();

            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 1;
            ctx.stroke();

            currentY -= (height - overlap);
        }
    },

    drawIsoCrystal(ctx: CanvasRenderingContext2D, style: any, alpha: number = 1.0) {
        // Crystals are jagged, but we align them roughly
        const drawShard = (x: number, y: number, w: number, h: number, tilt: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(tilt);

            ctx.fillStyle = style.dark;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-w, -h * 0.2);
            ctx.lineTo(0, -h); 
            ctx.lineTo(w, -h * 0.3);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = style.light;
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(w, -h * 0.3);
            ctx.lineTo(0, -h);
            ctx.fill();

            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(0, -h);
            ctx.stroke();

            ctx.restore();
        };

        drawShard(-10, 5, 10, 50, -0.2);
        drawShard(10, 2, 12, 40, 0.2);
        drawShard(0, 8, 18, 70, 0); 
    }
};

import { HexGeometry } from "../utils/HexGeometry";

export const GeometryPainter = {
    drawHex(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, style: 'FILL' | 'STROKE' | 'BOTH' = 'FILL', applyIso: boolean = true) {
        HexGeometry.traceHex(ctx, x, y, r, applyIso);

        if (style === 'FILL' || style === 'BOTH') ctx.fill();
        if (style === 'STROKE' || style === 'BOTH') ctx.stroke();
    },

    drawJaggedShape(ctx: CanvasRenderingContext2D, r: number) {
        // Jagged shapes (Fireballs) are usually chaotic and don't need strict ISO alignment,
        // but if used on ground, the caller should handle scale.
        ctx.beginPath();
        const spikes = 8;
        for(let i=0; i<spikes*2; i++) {
            const angle = (Math.PI * i) / spikes;
            const dist = (i % 2 === 0) ? r : r * 0.4;
            ctx.lineTo(Math.cos(angle)*dist, Math.sin(angle)*dist);
        }
        ctx.closePath();
        ctx.fill();
    }
};

import { GeometryPainter } from "./GeometryPainter";

export const ParticlePainter = {
    drawAtmosphere(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, '#ffffff'); 
        grad.addColorStop(0.2, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        // Soft Hex shape: Use Regular (applyIso=false) because this is a texture generator.
        // If it's a Billboard, it should be round. If Ground, GroundPainter scales it.
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'FILL', false);
    },

    drawSmoke(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color); 
        grad.addColorStop(0.6, 'transparent');
        ctx.fillStyle = grad;

        // Draw clusters (Organic shapes don't strictly need ISO logic)
        ctx.beginPath();
        ctx.arc(-r*0.3, -r*0.2, r*0.5, 0, Math.PI*2);
        ctx.arc(r*0.3, r*0.2, r*0.4, 0, Math.PI*2);
        ctx.arc(0, 0, r*0.4, 0, Math.PI*2);
        ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        // Shockwave texture MUST be Regular Hex. GroundPainter scales it.
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'STROKE', false);

        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.lineWidth = 1;
        ctx.shadowBlur = 0;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.6, 'STROKE', false);
    },

    drawSpike(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        ctx.beginPath();
        // Star shape (Regular geometry)
        for(let i=0; i<4; i++) {
            const angle = (i * Math.PI) / 2;
            ctx.moveTo(0,0);
            ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
            ctx.lineTo(Math.cos(angle+0.2)*r*0.2, Math.sin(angle+0.2)*r*0.2);
        }
        ctx.fill();

        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, 0, r*0.3, 0, Math.PI*2); ctx.fill();
    }
};

import { GeometryPainter } from "./GeometryPainter";
import { HexGeometry } from "../utils/HexGeometry";

export const IconPainter = {
    drawHexHalo(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        // 1. Draw Outer Hex (Regular, no ISO squash for texture generation)
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'STROKE', false);

        // 2. Draw Corner Dots (Aligned to Geometry)
        ctx.fillStyle = '#fff';
        ctx.shadowBlur = 0;

        // Use Source of Truth for vertices to ensure dots match the line exactly
        const verts = HexGeometry.getVertices(r * 0.8, false); // applyIso=false

        verts.forEach(v => {
            ctx.beginPath(); 
            ctx.arc(v.x, v.y, 2, 0, Math.PI*2); 
            ctx.fill();
        });
    },

    drawHexLock(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 5;
        // Regular Hex for texture
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'FILL', false);

        ctx.globalCompositeOperation = 'destination-out';
        ctx.lineWidth = 4;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(-6, -6); ctx.lineTo(6, 6);
        ctx.moveTo(6, -6); ctx.lineTo(-6, 6);
        ctx.stroke();
    }
};

import { createCanvas } from "./CanvasUtils";
import { STATUS_VISUALS } from "../../data/vfx/status_visuals";
import { HexGeometry } from "./utils/HexGeometry";

const ICON_SIZE = 32;
const STATUS_SIZE = 48;

export const UIFactory = {

    generateSkillIcon(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);

        // Background Frame
        ctx.fillStyle = '#1e293b'; 
        ctx.fillRect(0, 0, ICON_SIZE, ICON_SIZE);

        ctx.strokeStyle = '#334155'; 
        ctx.strokeRect(0, 0, ICON_SIZE, ICON_SIZE);

        // Symbol drawing
        ctx.translate(ICON_SIZE / 2, ICON_SIZE / 2);
        ctx.fillStyle = color;
        ctx.strokeStyle = color;
        ctx.shadowColor = color; 
        ctx.shadowBlur = 5;
        ctx.lineWidth = 2;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        ctx.beginPath();
        switch (visual) {
            case 'SLASH': 
                ctx.arc(0, 0, 8, -Math.PI/2, 0);
                ctx.stroke();
                ctx.beginPath(); ctx.moveTo(-8, 8); ctx.lineTo(8, -8); ctx.stroke();
                break;
            case 'ARROW': 
                ctx.moveTo(-6, 6); ctx.lineTo(6, -6);
                ctx.lineTo(2, -6); ctx.moveTo(6, -6); ctx.lineTo(6, -2);
                ctx.stroke();
                break;
            case 'FIREBALL': 
                ctx.arc(0, 2, 6, 0, Math.PI*2);
                ctx.moveTo(0, -8); ctx.lineTo(0, -4);
                ctx.stroke();
                break;
            case 'BOLT': 
                ctx.moveTo(2, -8); ctx.lineTo(-4, 0); ctx.lineTo(4, 0); ctx.lineTo(-2, 8);
                ctx.stroke();
                break;
            case 'BEAM': 
                ctx.moveTo(-8, -8); ctx.lineTo(8, 8);
                ctx.moveTo(8, -8); ctx.lineTo(-8, 8);
                ctx.stroke();
                ctx.beginPath(); ctx.arc(0,0,4,0,Math.PI*2); ctx.fill();
                break;
            case 'SMASH': 
                ctx.rect(-6, -8, 12, 8);
                ctx.moveTo(0, 0); ctx.lineTo(0, 10);
                ctx.stroke();
                break;
            case 'BOMB': 
                ctx.arc(0, 2, 6, 0, Math.PI*2);
                ctx.stroke();
                ctx.beginPath(); ctx.moveTo(4, -4); ctx.lineTo(8, -8); ctx.stroke();
                break;
            default:
                ctx.arc(0, 0, 6, 0, Math.PI*2);
                ctx.fill();
        }

        return canvas;
    },

    generateStatusIcon(statusId: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(STATUS_SIZE, STATUS_SIZE);
        const cx = STATUS_SIZE / 2;
        const cy = STATUS_SIZE / 2;

        const def = STATUS_VISUALS[statusId] || STATUS_VISUALS['DEFAULT'];

        ctx.translate(cx, cy);
        ctx.shadowBlur = 5;
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.strokeStyle = def.primaryColor;
        ctx.fillStyle = def.primaryColor;
        ctx.shadowColor = def.secondaryColor;

        // Unified Hex Shape Drawing
        const drawHex = (r: number, style: 'FILL' | 'STROKE') => {
            // UI Icons are flat (applyIso = false)
            HexGeometry.traceHex(ctx, 0, 0, r, false);
            if (style === 'FILL') ctx.fill(); else ctx.stroke();
        };

        switch (def.iconShape) {
            case 'HEX_HALO': // Stun
                // Outer Hex
                drawHex(16, 'STROKE');
                // Inner Stars
                ctx.beginPath();
                for(let i=0; i<10; i++) {
                    const angle = i * 0.5;
                    const r = 2 + i * 1.5;
                    const x = Math.cos(angle) * r;
                    const y = Math.sin(angle) * r;
                    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
                }
                ctx.stroke();
                break;
            case 'HEX_LOCK': // Silence
                ctx.strokeRect(-12, -10, 24, 16);
                ctx.beginPath();
                ctx.moveTo(-6, -2); ctx.lineTo(-6, -2);
                ctx.moveTo(0, -2); ctx.lineTo(0, -2);
                ctx.moveTo(6, -2); ctx.lineTo(6, -2);
                ctx.lineWidth = 4; 
                ctx.stroke();
                break;
            case 'HEX_PRISM': // Banish
                drawHex(14, 'FILL');
                break;
            case 'HEX_RUNE': // Poison/Regen
                if (statusId === 'POISON') {
                    drawHex(14, 'STROKE');
                    ctx.beginPath(); ctx.moveTo(-4, -4); ctx.lineTo(4, 4); ctx.stroke();
                    ctx.beginPath(); ctx.moveTo(4, -4); ctx.lineTo(-4, 4); ctx.stroke();
                } else if (statusId === 'REGEN') {
                    ctx.beginPath();
                    ctx.moveTo(0, -10); ctx.lineTo(0, 10);
                    ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
                    ctx.stroke();
                } else {
                    drawHex(14, 'STROKE');
                }
                break;
            case 'HEX_SKULL': // Fear
                ctx.beginPath();
                ctx.arc(0, -4, 8, 0, Math.PI*2); 
                ctx.rect(-6, 2, 12, 8); 
                ctx.fill();
                ctx.globalCompositeOperation = 'destination-out';
                ctx.beginPath(); ctx.arc(-3, -4, 2, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(3, -4, 2, 0, Math.PI*2); ctx.fill();
                ctx.globalCompositeOperation = 'source-over';
                break;
            case 'HEX_ANGRY': // Taunt
                ctx.lineWidth = 4;
                ctx.beginPath();
                ctx.moveTo(-10, -10); ctx.lineTo(-5, 0); ctx.lineTo(-10, 10);
                ctx.moveTo(0, -12); ctx.lineTo(0, 12);
                ctx.moveTo(10, -10); ctx.lineTo(5, 0); ctx.lineTo(10, 10);
                ctx.stroke();
                break;
            case 'HEX_EYE': // Blind
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.stroke();
                ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();
                ctx.lineWidth = 3;
                ctx.strokeStyle = '#ef4444';
                ctx.beginPath(); ctx.moveTo(-12, -12); ctx.lineTo(12, 12); ctx.stroke();
                break;
            case 'HEX_SHIELD': // Shield
                drawHex(16, 'STROKE');
                ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(0, 8); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(-8, 0); ctx.lineTo(8, 0); ctx.stroke();
                break;
            case 'NONE':
            default:
                if (statusId === 'POLYMORPH') {
                    ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.stroke();
                } else {
                    ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.stroke();
                }
                break;
        }

        return canvas;
    }
};

import { Agent } from "../../../game";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

// Constants for Visual Anchoring
const AURA_FLOOR_LIFT = -4; 
const HOVER_LIFT = 6; 

export const UnitAuraPainter = {

    /**
     * Draws the casting channel animation (Standard Skills).
     * Uses pure geometry for crisp lines at any zoom level.
     */
    drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        // 1. Setup Context at Unit Feet
        ctx.save();
        const footOffset = UNIT_BODY_OFFSET + HOVER_LIFT;
        ctx.translate(0, footOffset + AURA_FLOOR_LIFT); 

        // 2. Dynamic Pulse Size (Fixed max size relative to tile)
        // Standard cast is approx 1 tile wide max
        const baseSize = HEX_SIZE * 0.9;
        const currentSize = baseSize * (0.8 + Math.sin(t * 10) * 0.05);

        ctx.strokeStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        // A. Rotating Inner Hex (The Channel)
        const rot = t * 4;
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;
        // Truth: traceRotatedHex with applyIso=true guarantees perspective correctness
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize * 0.7, rot, true);
        ctx.stroke();

        // B. Counter-Rotating Outer Ring
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.4;
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize, -rot * 0.5, true);
        ctx.stroke();

        // C. Rising Particles (Procedural Dots)
        this.drawRisingParticles(ctx, color, progress, t);

        ctx.restore();

        // 3. AOE Ripple (If applicable)
        if (skill.type === 'AOE') {
            this.drawAoeExpansion(ctx, agent, color, progress, skill.aoeRadius || 1);
        }
    },

    /**
     * Draws the Ultimate Chanting Circle.
     * More complex geometry, larger scale, strict alignment.
     */
    drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        const footOffset = UNIT_BODY_OFFSET + HOVER_LIFT;
        ctx.translate(0, footOffset + AURA_FLOOR_LIFT);

        // Ult Radius is visual only, slightly larger than tile to look epic
        const ultSize = HEX_SIZE * 2.2; 
        const rot = t * 2;

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.strokeStyle = color;

        // Layer 1: Main Magic Circle
        ctx.lineWidth = 3;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize, rot, true);
        ctx.stroke();

        // Layer 2: Inner Geometry
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.6;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize * 0.6, -rot * 2, true);
        ctx.stroke();

        // Layer 3: Static Ground Seal
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.3;
        HexGeometry.traceHex(ctx, 0, 0, ultSize * 1.2, true);
        ctx.stroke();

        // Layer 4: Vertical Light Pillars (Energy gathering)
        const pillarH = 100 * progress;
        if (pillarH > 1) {
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.4;
            const points = HexGeometry.getVertices(ultSize * 0.8, true);
            points.forEach((p, i) => {
                if (i % 2 === 0) { // Only 3 pillars
                    ctx.fillRect(p.x - 2, p.y - pillarH, 4, pillarH);
                }
            });
        }

        ctx.restore();
    } as any, // Type cast to allow flexibility

    /**
     * Replaces the old texture-based expansion with a precise vector ripple.
     * The ripple expands exactly to the skill's radius.
     */
    drawAoeExpansion(ctx: CanvasRenderingContext2D, agent: Agent, color: string, progress: number, rangeInTiles: number) {
        const footOffset = UNIT_BODY_OFFSET + HOVER_LIFT;

        ctx.save();
        // Move to absolute ground level (feet + physics Z) to ensure ripple is on the floor
        // Note: We use physics.z to account for unit jumping height if we want it on the floor BELOW them.
        // But usually AOE warning originates from the unit's logic position.
        // Visual Logic: Draw at feet level relative to unit body context
        ctx.translate(0, footOffset + agent.physics.z + AURA_FLOOR_LIFT);

        // Calculate EXACT pixel radius based on map grid size
        const maxRadiusPx = rangeInTiles * HEX_SIZE;
        const currentRadius = maxRadiusPx * progress;

        // Use exponential ease-out for visual impact
        const easedRadius = maxRadiusPx * (1 - Math.pow(1 - progress, 3));

        ctx.strokeStyle = color;
        ctx.fillStyle = color;

        // 1. The Wave Front
        ctx.beginPath();
        ctx.lineWidth = 2;
        ctx.globalAlpha = (1 - progress) * 0.8;
        HexGeometry.traceHex(ctx, 0, 0, easedRadius, true);
        ctx.stroke();

        // 2. Inner Fill (Faint)
        ctx.globalAlpha = (1 - progress) * 0.1;
        ctx.fill();

        ctx.restore();
    },

    // Helper for particles
    drawRisingParticles(ctx: CanvasRenderingContext2D, color: string, progress: number, t: number) {
        ctx.fillStyle = color;
        const count = 3;
        for(let i=0; i<count; i++) {
            const offset = i * (Math.PI * 2 / count);
            const cycle = (t * 2 + offset) % 1; // 0 to 1

            // Spiral up
            const h = cycle * 60;
            const r = (1 - cycle) * 30;
            const angle = t * 3 + offset;

            const px = Math.cos(angle) * r;
            const py = (Math.sin(angle) * r * 0.58) - h; // ISO Y + Vertical Rise

            const alpha = Math.sin(cycle * Math.PI); // Fade in/out
            ctx.globalAlpha = alpha * 0.8;

            ctx.beginPath(); 
            ctx.arc(px, py, 2, 0, Math.PI*2); 
            ctx.fill();
        }
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../../constants";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

export const UnitIndicatorPainter = {

    drawSkillGroundIndicator(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number, 
        skillRadius: number, 
        type: string, 
        isAOE: boolean
    ) {
        // Strict Mathematical Radius
        const maxPixelRadius = Math.max(1, skillRadius) * HEX_SIZE;
        const currentRadius = maxPixelRadius * progress;

        // Alpha pulse
        const opacity = 0.3 + Math.sin(t * 8) * 0.1;

        // 1. Volumetric Glow (Floor lighting)
        VolumePainter.drawVolumetricHex(ctx, x, y, currentRadius, color, opacity);

        // 2. Vector Ring (Precision geometry)
        ctx.save();
        ctx.translate(x, y);

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = opacity * 1.5;

        // Draw expanding hex
        HexGeometry.traceHex(ctx, 0, 0, currentRadius, true);
        ctx.stroke();

        // Inner Echo
        ctx.lineWidth = 1;
        ctx.globalAlpha = opacity * 0.8;
        HexGeometry.traceHex(ctx, 0, 0, currentRadius * 0.8, true);
        ctx.stroke();

        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

// High fidelity texture size for runtime scaling
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() {
        this.cache.clear();
    }

    public getTexture(type: string, color: string): HTMLCanvasElement {
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);

        const r = 40; 

        switch (type) {
            // --- GROUND EFFECTS (REGULAR GEOMETRY) ---
            case 'ZONE_BASE':
            case 'HEX_GLOW':
                this.drawRegularHexFill(ctx, r, color, true); 
                break;

            case 'GRID_FIELD':
                this.drawRegularHexGrid(ctx, r, color);
                break;

            case 'SHOCKWAVE':
                this.drawRegularHexRing(ctx, r, color, 4);
                break;

            case 'MAGIC_CIRCLE':
                // Regular Hexagon Rings (Projection handled by Renderer)
                this.drawRegularHexRing(ctx, r, color, 3);
                this.drawRegularHexRing(ctx, r * 0.7, color, 1);
                // Inner rune hints
                ctx.beginPath();
                ctx.moveTo(-r*0.4, 0); ctx.lineTo(r*0.4, 0);
                ctx.moveTo(0, -r*0.4); ctx.lineTo(0, r*0.4);
                ctx.strokeStyle = color; ctx.stroke();
                break;

            case 'CRACKS':
                this.drawCracks(ctx, r, color);
                break;

            case 'SHADOW_BLOB':
                ctx.fillStyle = color;
                ctx.filter = 'blur(8px)';
                ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.fill();
                ctx.filter = 'none';
                break;

            // --- BILLBOARD SPRITES ---
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;

            case 'CLOUD': 
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;

            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;

            // --- DEBRIS ---
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;

            // --- ICONS ---
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;

            case 'BEAM':
                const grad = ctx.createLinearGradient(-r, 0, r, 0);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.5, color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.fillRect(-r*2, -r, r*4, r*2);
                break;

            default:
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // --- GEOMETRY PRIMITIVES ---

    private drawRegularHexFill(ctx: CanvasRenderingContext2D, r: number, color: string, glow: boolean) {
        if (glow) {
            const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
        } else {
            ctx.fillStyle = color;
        }
        HexGeometry.traceHex(ctx, 0, 0, r, false); 
        ctx.fill();
    }

    private drawRegularHexRing(ctx: CanvasRenderingContext2D, r: number, color: string, width: number) {
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        HexGeometry.traceHex(ctx, 0, 0, r, false); 
        ctx.stroke();
    }

    private drawRegularHexGrid(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        HexGeometry.traceHex(ctx, 0, 0, r * 0.9, false);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(-r*0.5, 0); ctx.lineTo(r*0.5, 0);
        ctx.moveTo(0, -r*0.5); ctx.lineTo(0, r*0.5);
        ctx.stroke();
    }

    private drawCracks(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        for(let i=0; i<3; i++) {
            const a = (Math.PI*2/3)*i;
            ctx.moveTo(0,0);
            ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            ctx.moveTo(Math.cos(a)*r*0.5, Math.sin(a)*r*0.5);
            ctx.lineTo(Math.cos(a+0.5)*r*0.8, Math.sin(a+0.5)*r*0.8);
        }
        ctx.stroke();
    }

    // --- UTILS ---
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        ctx.translate(size/2, size/2);
        ctx.scale(1, 0.58); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        for(let i=0; i<5; i++) {
            const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
            const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
            if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
            ctx.beginPath();
            ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
            ctx.fill();
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);

        switch (visual) {
            case 'HEX_DART': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

