import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const GroundPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number) {

        // --- 1. PROCEDURAL VECTOR RENDERING (CRISP LINES) ---
        // We handle geometric shapes strictly with math to avoid scaling artifacts.

        if (['SHOCKWAVE', 'RING', 'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'MAGIC_CIRCLE'].includes(p.type)) {
            this.drawVectorGeometry(ctx, p, progress, drawX, drawY);
            return;
        }

        // --- 2. TEXTURE FALLBACK (ORGANIC SPRITES) ---
        // For organic things like Cracks (complex) or specialized textures

        if (!p.image && !p.texture) {
            // CRACKS still use texture for organic look, but we might want to vectorise them later too
            if (p.type === 'CRACKS') {
                p.image = VFXFactory.getTexture(p.type, p.color);
            }
        }

        const img = p.image || p.texture;
        if (!img) return;

        let scale = 1.0;
        let alpha = 1.0 - progress;

        // Simple fade/scale for textures
        if (p.type === 'CRACKS') {
            scale = 1.0;
            alpha = 1.0 - Math.pow(progress, 4); 
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(1, ISO_SCALE_Y); // Project to floor

        if (p.rotation) ctx.rotate(p.rotation);

        ctx.globalCompositeOperation = p.blendMode || 'screen';
        ctx.globalAlpha = Math.min(1, alpha);

        const size = p.size * scale;
        ctx.drawImage(img, -size, -size, size * 2, size * 2);

        ctx.restore();
    },

    drawVectorGeometry(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number) {
        ctx.save();
        ctx.translate(drawX, drawY);

        // Setup Blend Mode
        if (p.blendMode) ctx.globalCompositeOperation = p.blendMode;
        else ctx.globalCompositeOperation = 'screen'; 

        // --- SHOCKWAVE / RING ---
        if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
            const alpha = 1.0 - Math.pow(progress, 2);
            if (alpha <= 0.01) { ctx.restore(); return; }

            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;

            // Expansion Logic
            const currentRadius = p.size * (0.2 + progress * 0.8);
            const lineWidth = Math.max(1, (1 - progress) * (p.type === 'SHOCKWAVE' ? 8 : 4));

            ctx.lineWidth = lineWidth;

            // Draw Main Ring (ISO Projected)
            HexGeometry.traceHex(ctx, 0, 0, currentRadius, true);
            ctx.stroke();

            // Draw Echo Ring
            if (p.type === 'SHOCKWAVE') {
                ctx.lineWidth = lineWidth * 0.5;
                HexGeometry.traceHex(ctx, 0, 0, currentRadius * 0.8, true);
                ctx.stroke();
            }
        }

        // --- GRID FIELD (Zone Areas) ---
        else if (p.type === 'GRID_FIELD') {
            const alpha = 1.0 - Math.pow(progress, 4);
            if (alpha <= 0.01) { ctx.restore(); return; }

            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.fillStyle = p.color;

            // Static Size
            const r = p.size;

            // Outer Border
            ctx.lineWidth = 2;
            HexGeometry.traceHex(ctx, 0, 0, r, true);
            ctx.stroke();

            // Inner Fill (Low Opacity)
            ctx.globalAlpha = alpha * 0.1;
            ctx.fill();

            // Inner Grid Detail (Cross)
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            // Manually draw ISO lines for the cross
            const half = r * 0.5;
            ctx.moveTo(-half, 0); ctx.lineTo(half, 0);
            ctx.moveTo(0, -half * ISO_SCALE_Y); ctx.lineTo(0, half * ISO_SCALE_Y);
            ctx.stroke();
        }

        // --- HEX GLOW (Soft Floor Light) ---
        else if (p.type === 'HEX_GLOW') {
            const alpha = 1.0 - Math.pow(progress, 2);
            if (alpha <= 0.01) { ctx.restore(); return; }

            // Radial Gradient simulation for ISO Hex
            // We draw multiple overlapping hexes with decreasing opacity to simulate a soft edge
            const layers = 5;
            for(let i=0; i<layers; i++) {
                const ratio = (i+1)/layers;
                ctx.fillStyle = p.color;
                ctx.globalAlpha = alpha * (1 - ratio) * 0.4;
                HexGeometry.traceHex(ctx, 0, 0, p.size * ratio, true);
                ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
