    offsetX: number;
    offsetY: number;
    layout: HexLayout;
}

const Q_STEP = 1 << 16;
const R_STEP = 1;

export const NEIGHBOR_HASH_OFFSETS = [
    Q_STEP,             // (1, 0)
    Q_STEP - R_STEP,    // (1, -1)
    -R_STEP,            // (0, -1)
    -Q_STEP,            // (-1, 0)
    -Q_STEP + R_STEP,   // (-1, 1)
    R_STEP              // (0, 1)
];

export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;
    const cx = mapConfig.offsetX;
    const cy = mapConfig.offsetY;
    const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
    const maxDist = 1000;
    const d = Math.min(1, dist / maxDist);
    const BASE_OFFSET = 1500; 

    if (phase === 'OUT') {
        const startT = d * 0.3;
        if (t < startT) return 0; 
        let localT = (t - startT) * 1.8; 
        localT = Math.max(0, Math.min(1, localT));
        const s = 0.5; 
        const eased = localT * localT * ((s + 1) * localT - s);
        return eased * BASE_OFFSET;
    } else if (phase === 'IN') {
        const startT = d * 0.2;
        if (t < startT) return BASE_OFFSET; 
        let localT = (t - startT) * 1.5;
        localT = Math.max(0, Math.min(1, localT));
        const eased = 1 - Math.pow(1 - localT, 4);
        return (1 - eased) * BASE_OFFSET;
    }
    return 0;
}

export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        if (config.layout === 'FLAT') {
            const q = col;
            const r = row - (col - (col & 1)) / 2;
            return { q, r };
        } else {
            const q = col - (row - (row & 1)) / 2;
            const r = row;
            return { q, r };
        }
    },

    toPx: (q: number, r: number, config: MapConfig): Point => {
        return HexMath.hexToPixel(q, r, config.offsetX, config.offsetY, config.layout);
    },

    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const frac = HexMath.pixelToHex(x, y, config.offsetX, config.offsetY, config.layout);
        return HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
    },

    round: (q: number, r: number): Hex => {
        const c = HexMath.cubeRound({x: q, z: r, y: -q-r});
        return { q: c.x, r: c.z };
    },

    dist: (a: Hex, b: Hex): number => {
        return HexMath.distance(a, b);
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    key: (h: Hex): string => `${h.q},${h.r}`,

    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        return HexMath.range(center, n);
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * 核心坐標投影邏輯
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        let x = 0;
        let y = 0;

        if (layout === 'FLAT') {
            x = (3 / 2 * q) * HEX_SIZE;
            y = (SQRT3 * (r + q / 2)) * HEX_SIZE;
        } else {
            x = (SQRT3 * (q + r / 2)) * HEX_SIZE;
            y = (3 / 2 * r) * HEX_SIZE;
        }

        return {
            x: x + offsetX,
            y: (y * ISO_SCALE_Y) + offsetY
        };
    },

    /**
     * 逆向投影邏輯
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y;

        let q = 0;
        let r = 0;

        if (layout === 'FLAT') {
            q = (2 / 3 * dx) / HEX_SIZE;
            r = (-1 / 3 * dx + SQRT3 / 3 * dy) / HEX_SIZE;
        } else {
            q = (SQRT3 / 3 * dx - 1 / 3 * dy) / HEX_SIZE;
            r = (2 / 3 * dy) / HEX_SIZE;
        }

        return { q, r };
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { HexLayout } from "../../../types";

// 1. Static Geometry Constants
const SQRT3 = Math.sqrt(3);

/**
 * 核心六邊形幾何真理 (The Single Source of Truth for Hex Geometry)
 */
export const HexGeometry = {

    /**
     * 計算六邊形頂點
     */
    getVertices(radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT'): {x: number, y: number}[] {
        const vertices = [];
        const isFlat = layout === 'FLAT';
        const startAngle = isFlat ? 0 : Math.PI / 6;
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = startAngle + i * Math.PI / 3;
            vertices.push({
                x: Math.cos(angle) * radius,
                y: Math.sin(angle) * radius * scaleY
            });
        }
        return vertices;
    },

    /**
     * [唯一路徑] 在 Context 上描繪六邊形路徑
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * 支援旋轉的向量描繪
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const isFlat = layout === 'FLAT';
        const baseAngle = isFlat ? 0 : Math.PI / 6;
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = baseAngle + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

