import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const SLAB_THICKNESS = 12; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const topOffset = -height;
        const bottomOffset = SLAB_THICKNESS;

        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // Indices for walls depend on layout
        // For FLAT, seen faces are 3-2, 2-1, 1-0
        // For POINTY, seen faces are 3-2, 2-1, 1-0 (roughly same projection logic)
        this.drawSideFace(ctx, vertices, 3, 2, topOffset, bottomOffset, theme.sideLight);
        this.drawSideFace(ctx, vertices, 2, 1, topOffset, bottomOffset, theme.sideDark);
        this.drawSideFace(ctx, vertices, 1, 0, topOffset, bottomOffset, theme.sideDark);

        ctx.translate(0, topOffset);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;

        ctx.beginPath();
        ctx.moveTo(vertices[3].x, vertices[3].y);
        ctx.lineTo(vertices[2].x, vertices[2].y);
        ctx.lineTo(vertices[1].x, vertices[1].y);
        ctx.lineTo(vertices[0].x, vertices[0].y);
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, bottomOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(verts[i1].x, verts[i1].y + bottomOffset);
        ctx.lineTo(verts[i2].x, verts[i2].y + bottomOffset);
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(verts[i1].x, verts[i1].y + bottomOffset);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { HEX_SIZE } from "../../../constants";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexMath } from "../../math/HexMath";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,

        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    

        lightColor: string | null,
        lightIntensity: number,

        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined,
        layout: HexLayout
    ) {
        if (hazard) {
            HazardPainter.draw(ctx, x, y, hazard, globalTime);
        }

        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, y);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        if (zoneInfo) {
            const dist = HexMath.distance({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, y, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy,
                layout
            );
        }

        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.6, lightIntensity * 0.5);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen';

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.15;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.fill();

                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();

                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.9;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }

            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../types";

export const ZoneRenderer = {

    drawTileZoneEffect(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,
        distToCenter: number, 
        zoneRadius: number,
        color: string,
        progress: number, 
        isEnemy: boolean,
        layout: HexLayout
    ) {
        ctx.save();
        ctx.translate(x, y);

        const currentWaveRadius = progress * (zoneRadius + 0.5);
        const distDiff = Math.abs(distToCenter - currentWaveRadius);
        const waveWidth = 1.5; 

        let waveIntensity = 0;
        if (distDiff < waveWidth) {
            waveIntensity = (Math.cos((distDiff / waveWidth) * Math.PI) + 1) * 0.5;
        }

        const isInside = distToCenter < currentWaveRadius;
        const drawColor = isEnemy ? '#ef4444' : color;

        let baseAlpha = 0;
        if (isEnemy) baseAlpha = 0.2; 
        if (isInside && !isEnemy) baseAlpha = 0.15; 

        if (baseAlpha > 0) {
            ctx.fillStyle = drawColor;
            ctx.globalAlpha = baseAlpha;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
            ctx.fill();
        }

        if (waveIntensity > 0.05) {
            ctx.strokeStyle = drawColor;
            ctx.lineWidth = 2 + waveIntensity * 2;
            ctx.globalAlpha = waveIntensity;
            const pulseSize = size * (0.9 + waveIntensity * 0.1);
            HexGeometry.traceHex(ctx, 0, 0, pulseSize, true, layout);
            ctx.stroke();

            ctx.lineWidth = 1;
            HexGeometry.traceHex(ctx, 0, 0, pulseSize * 0.7, true, layout);
            ctx.stroke();
        }

        if (isEnemy || isInside) {
            const isBorder = Math.abs(distToCenter - zoneRadius) < 0.5;
            if (isBorder) {
                ctx.strokeStyle = drawColor;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.5;
                if (isEnemy) ctx.setLineDash([4, 4]);
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
                ctx.setLineDash([]);
            }
        }

        ctx.restore();
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene;
        const layout = engine.mapConfig.layout;

        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, visualTopY, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    break;
                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    break;
                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos, layout);
                        ctx.restore();
                    }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase, layout);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        else if (engine.winningTeam !== null) blurAmount = 1.0;

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { Particle } from "../state";
import { BillboardPainter } from "./painters/BillboardPainter";
import { GroundPainter } from "./painters/GroundPainter";
import { ProceduralPainter } from "./painters/ProceduralPainter";
import { HexLayout } from "../../../../types";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean, layout: HexLayout = 'FLAT') {
        const now = Date.now() / 1000;

        // 1. Procedural Complex Shapes
        if (['PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'DOMAIN', 'DEATH_RAY', 'BEAM', 'MAGIC_CIRCLE'].includes(p.type)) {
            ctx.save();
            ctx.translate(drawX, drawY);
            ProceduralPainter.draw(ctx, p, progress, now, layout);
            ctx.restore();
            return;
        }

        // 2. Ground/Floor Effects
        if (['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'HEX_GLOW'].includes(p.type)) {
            GroundPainter.draw(ctx, p, progress, drawX, drawY, layout);
            return;
        }

        // 3. Billboard Sprites
        BillboardPainter.draw(ctx, p, drawX, drawY, progress);
    }
};

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 200;
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        vfx.state.decals.forEach(d => {
            if (d.x < cullMinX || d.x > cullMaxX || d.y < cullMinY || d.y > cullMaxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return;
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) {
                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (Math.abs(offset) > 800) return;
                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);
                const op = renderList.next();
                op.type = RenderOpType.VFX;
                op.y = p.y + offset; 
                op.z = 5;
                op.sortBias = p.sortBias || 0; 
                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaos;
                op.tx = p.x;
                op.ty = p.y + offset - p.z; 
                op.th = p.z; 
            }
        });

        ProjectileRenderer.submit(renderList, engine, getTerrainHeight, transitionT, transitionPhase);
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        layout: HexLayout
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return; 
            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);
            ParticleRenderer.drawSingleParticle(ctx, p, p.x, drawY, progress, isChaos, layout);
        });
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { VFXFactory } from "../../../../graphics/VFXFactory";
import { HexLayout } from "../../../../../types";

export const GroundPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number, layout: HexLayout = 'FLAT') {
        if (['SHOCKWAVE', 'RING', 'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'MAGIC_CIRCLE'].includes(p.type)) {
            this.drawVectorGeometry(ctx, p, progress, drawX, drawY, layout);
            return;
        }

        if (!p.image && !p.texture) {
            if (p.type === 'CRACKS') {
                p.image = VFXFactory.getTexture(p.type, p.color);
            }
        }

        const img = p.image || p.texture;
        if (!img) return;

        let scale = 1.0;
        let alpha = 1.0 - progress;

        if (p.type === 'CRACKS') {
            scale = 1.0;
            alpha = 1.0 - Math.pow(progress, 4); 
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(1, ISO_SCALE_Y); 

        if (p.rotation) ctx.rotate(p.rotation);

        ctx.globalCompositeOperation = p.blendMode || 'screen';
        ctx.globalAlpha = Math.min(1, alpha);

        const size = p.size * scale;
        ctx.drawImage(img, -size, -size, size * 2, size * 2);

        ctx.restore();
    },

    drawVectorGeometry(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number, layout: HexLayout) {
        ctx.save();
        ctx.translate(drawX, drawY);

        if (p.blendMode) ctx.globalCompositeOperation = p.blendMode;
        else ctx.globalCompositeOperation = 'screen'; 

        if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
            const alpha = 1.0 - Math.pow(progress, 2);
            if (alpha <= 0.01) { ctx.restore(); return; }

            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;

            const currentRadius = p.size * (0.2 + progress * 0.8);
            const lineWidth = Math.max(1, (1 - progress) * (p.type === 'SHOCKWAVE' ? 8 : 4));

            ctx.lineWidth = lineWidth;
            HexGeometry.traceHex(ctx, 0, 0, currentRadius, true, layout);
            ctx.stroke();

            if (p.type === 'SHOCKWAVE') {
                ctx.lineWidth = lineWidth * 0.5;
                HexGeometry.traceHex(ctx, 0, 0, currentRadius * 0.8, true, layout);
                ctx.stroke();
            }
        }
        else if (p.type === 'GRID_FIELD') {
            const alpha = 1.0 - Math.pow(progress, 4);
            if (alpha <= 0.01) { ctx.restore(); return; }

            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.fillStyle = p.color;

            const r = p.size;
            ctx.lineWidth = 2;
            HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
            ctx.stroke();

            ctx.globalAlpha = alpha * 0.1;
            ctx.fill();

            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const half = r * 0.5;
            // Cross lines adapted slightly for Pointy layout? 
            // Standard cross still works visually as center markers
            ctx.moveTo(-half, 0); ctx.lineTo(half, 0);
            ctx.moveTo(0, -half * ISO_SCALE_Y); ctx.lineTo(0, half * ISO_SCALE_Y);
            ctx.stroke();
        }
        else if (p.type === 'HEX_GLOW') {
            const alpha = 1.0 - Math.pow(progress, 2);
            if (alpha <= 0.01) { ctx.restore(); return; }

            const layers = 5;
            for(let i=0; i<layers; i++) {
                const ratio = (i+1)/layers;
                ctx.fillStyle = p.color;
                ctx.globalAlpha = alpha * (1 - ratio) * 0.4;
                HexGeometry.traceHex(ctx, 0, 0, p.size * ratio, true, layout);
                ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

export const ProceduralPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        if (p.type === 'HEX_BEAM' || p.type === 'GIANT_HEX' || p.type === 'MAGIC_CIRCLE') {
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
                ctx.globalAlpha = 1.0;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
                ctx.fill();

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 4;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
                ctx.stroke();

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, -rot * 1.5, true, layout);
                ctx.fill();

                if (p.color === '#000' || p.color === '#000000' || p.color === '#0f172a') {
                    ctx.save();
                    ctx.scale(1, ISO_SCALE_Y); 
                    ctx.fillStyle = '#000';
                    ctx.shadowColor = '#8b5cf6'; 
                    ctx.shadowBlur = 20;
                    ctx.beginPath(); ctx.arc(0, 0, p.size * 0.4, 0, Math.PI * 2); ctx.fill();
                    ctx.restore();
                }

            } else if (p.type === 'MAGIC_CIRCLE') {
                ctx.globalCompositeOperation = 'screen';
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 3;
                ctx.shadowColor = p.color;
                ctx.shadowBlur = 10;

                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
                ctx.stroke();

                ctx.lineWidth = 1;
                ctx.shadowBlur = 0;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.7, -rot * 2, true, layout);
                ctx.stroke();

                ctx.save();
                ctx.scale(1, ISO_SCALE_Y);
                ctx.beginPath(); ctx.arc(0, 0, p.size * 0.4, 0, Math.PI * 2); 
                ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
                ctx.restore();

            } else {
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = (1 - progress) * 0.8;
                ctx.fillStyle = p.color;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
                ctx.fill();

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.9, rot, true, layout);
                ctx.stroke();
            }
        }
        else if (p.type === 'PILLAR') {
            const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
            const def = rawDef as PillarVisualDef;
            const h = p.height || def.height || 1200; 
            const width = p.size * (1 - progress * 0.5) * (def.widthScale || 1.0);

            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            const cylinderGrad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
            cylinderGrad.addColorStop(0, p.color); 
            cylinderGrad.addColorStop(0.5, '#ffffff'); 
            cylinderGrad.addColorStop(1, p.color); 

            ctx.fillStyle = cylinderGrad;
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.fillRect(-width/2, -h, width, h);

            if (def.hasBaseRing) {
                ctx.save();
                ctx.scale(1, ISO_SCALE_Y);
                const ringGrad = ctx.createRadialGradient(0,0, width*0.5, 0,0, width*1.2);
                ringGrad.addColorStop(0, 'transparent');
                ringGrad.addColorStop(0.5, p.color);
                ringGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = ringGrad;
                ctx.beginPath(); ctx.arc(0, 0, width*1.5, 0, Math.PI*2); ctx.fill();
                ctx.restore();
            }
        }
        else if (p.type === 'DOMAIN') {
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 
            const isShield = p.style === 'DOMAIN_SHIELD';
            const h = isShield ? 120 : 40;
            const opacity = 0.4 * (1 - progress);
            VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
        }
        ctx.restore();
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../utils/HexGeometry";
import { VFXFactory } from "../VFXFactory";
import { HexLayout } from "../../../types";

export const VolumePainter = {

    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING',
        layout: HexLayout = 'FLAT'
    ) {
        const topY = y - height;

        ctx.save();
        ctx.translate(x, y); 

        const verts = HexGeometry.getVertices(radius, true, layout);
        const indices = [5, 0, 1]; 

        for (const i of indices) {
            const j = (i + 1) % 6;
            const v1 = verts[i];
            const v2 = verts[j];

            const grad = ctx.createLinearGradient(0, -height, 0, 0);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; 

            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y);           
            ctx.lineTo(v2.x, v2.y);           
            ctx.lineTo(v2.x, v2.y - height);  
            ctx.lineTo(v1.x, v1.y - height);  
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y);
            ctx.lineTo(v1.x, v1.y - height);
            ctx.stroke();

            if (i === 1) { 
                 ctx.beginPath(); ctx.moveTo(v2.x, v2.y); ctx.lineTo(v2.x, v2.y - height); ctx.stroke();
            }
        }

        ctx.translate(0, -height);
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.3;
        HexGeometry.traceHex(ctx, 0, 0, radius, true, layout);
        ctx.fill();

        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceHex(ctx, 0, 0, radius, true, layout);
        ctx.stroke();

        ctx.restore();
    },

    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; 

        ctx.save();
        ctx.translate(x, y);
        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number,
        layout: HexLayout = 'FLAT'
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';

        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        HexGeometry.traceHex(ctx, x, y, radius, true, layout);
        ctx.stroke();

        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        layout: HexLayout = 'FLAT'
    ) {
        const verts = HexGeometry.getVertices(radius, true, layout);
        const indices = [5, 0, 1];

        ctx.save();
        ctx.translate(x, y);
        ctx.globalAlpha = opacity;

        for (const i of indices) {
            const j = (i + 1) % 6;
            const v1 = verts[i];
            const v2 = verts[j];

            const grad = ctx.createLinearGradient(0, -height, 0, 0);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y - height);
            ctx.lineTo(v2.x, v2.y - height);
            ctx.lineTo(v2.x, v2.y);
            ctx.lineTo(v1.x, v1.y);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        HexGeometry.traceHex(ctx, 0, -height, radius, true, layout);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import { HexMath } from "../../math/HexMath";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y (Base of the tile unit is standing on)
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number; // New: Explicit sort key

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // 1. Interpolate Ground Position (Lerp if moving)
        let logicalX = 0;
        let logicalY = 0;
        let terrainH = 0;
        let sortY = 0;

        if (agent.isMoving && agent.path.length > 0) {
            // Fix: Added missing layout argument from mapConfig.layout to hexToPixel
            const startPx = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY, mapConfig.layout);
            const nextHex = agent.path[0];
            // Fix: Added missing layout argument from mapConfig.layout to hexToPixel
            const endPx = HexMath.hexToPixel(nextHex.q, nextHex.r, mapConfig.offsetX, mapConfig.offsetY, mapConfig.layout);

            // Re-calculate lerp to ensure it matches motion engine visual exactly
            logicalX = startPx.x + (endPx.x - startPx.x) * agent.moveProgress;
            logicalY = startPx.y + (endPx.y - startPx.y) * agent.moveProgress;

            const startH = getTerrainHeight(agent.q, agent.r);
            const endH = getTerrainHeight(nextHex.q, nextHex.r);

            // STEP LOGIC: Snap height at midpoint to assume "stepping up/down" the block
            // This prevents the unit from clipping through the wall of a higher block or floating diagonally.
            terrainH = agent.moveProgress < 0.5 ? startH : endH;

            // SORT LOGIC: When moving, always sort in front of BOTH the start and end tiles.
            // In isometric, larger Y = Front.
            // We set the sort key to the 'most front' tile involved in the move.
            sortY = Math.max(startPx.y, endPx.y);

        } else {
            // Fix: Added missing layout argument from mapConfig.layout to hexToPixel
            const pos = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY, mapConfig.layout);
            logicalX = pos.x;
            logicalY = pos.y;
            terrainH = getTerrainHeight(agent.q, agent.r);
            sortY = logicalY;
        }

        // Apply visual physics offsets
        const visualX = logicalX + agent.physics.x;
        // visualY corresponds to the Ground Base Y
        const visualY = logicalY + agent.physics.y; 
        const visualZ = terrainH + agent.physics.z; 

        // Apply physics to sort key too (e.g. knocked forward)
        sortY += agent.physics.y;

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";

export class GridSpatial {

    /**
     * Get valid map tiles within a certain radius of a center point.
     * Used for game logic (e.g. finding targets) to ensure we don't pick void tiles.
     */
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        const candidates = HexMath.range({q: centerQ, r: centerR}, radius);
        const valid: Hex[] = [];

        for (const hex of candidates) {
            if (engine.map.isValid(hex.q, hex.r)) {
                valid.push(hex);
            }
        }
        return valid;
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        const maxHeight = 200; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        // Raycast down from max possible height
        for (let h = 0; h <= maxHeight; h += step) {
            // "Unproject" the Y coordinate by adding height (since visual Y = ground Y - height)
            const testY = wy + h; 

            // Fix: Added missing layout argument from engine.mapConfig.layout to pixelToHex
            const frac = HexMath.pixelToHex(wx, testY, engine.mapConfig.offsetX, engine.mapConfig.offsetY, engine.mapConfig.layout);
            const rounded = HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
            const key = HexUtils.key(rounded);

            const tile = cache.tileMap.get(key);

            if (tile) {
                // Check if the click hits the top face or the slope
                // Visual Y of the tile top is (py - tile.h)
                const visualTopY = tile.py - tile.h;

                // Distance check in screen space roughly
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                // Tighter hit box for better precision
                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    // We found a candidate. The tile with the highest visual Z (closest to camera) should win.
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            // Visual Y of agent feet = uPx.y - terrainH
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);

            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const nTerrainH = engine.map.getTerrainHeight(n.q, n.r);

                    // Occlusion Check:
                    // If neighbor is "South" (Higher Y) and TALLER than agent's standing level
                    if (nPx.y > uPx.y) { 
                         if (nTerrainH > uTerrainH) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        }
        return occluded;
    }
}

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Standard Theater Size: 11x11 or 12x12
        engine.mapConfig.w = Math.floor(10 + Math.random() * 3); 
        engine.mapConfig.h = Math.floor(10 + Math.random() * 3); 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        // Theater Framing Logic
        // In Isometric view, (q=0, r=0) is the "Top/Back" corner.
        // We want higher tiers at low Q or low R (the back walls).
        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const hex = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                const k = HexUtils.key(hex);
                system.registerTile(hex.q, hex.r);

                // 1. "Stage Wall" Bias: High elevation towards the back (Backstage)
                // Normalize coordinates 0.0 to 1.0
                const qNorm = q / (W - 1);
                const rNorm = r / (H - 1);

                // Oblique Theater Formula: 
                // Front is (qNorm=1, rNorm=1). Back is (qNorm=0, rNorm=0).
                let theaterScore = (1 - qNorm) * 1.5 + (1 - rNorm) * 1.5;

                // 2. "Side Wings" Bias: Higher on the far left and far right
                const sideBias = Math.abs(qNorm - 0.5) * 2.0; 
                theaterScore += sideBias * 1.2;

                // 3. Noise for natural look
                const noise = (Math.sin(q * 0.8) * Math.cos(r * 0.8)) * 0.5;

                // Combine and Quantize
                let tier = Math.floor(theaterScore + noise);

                // Central "Pit" logic: Force the very center to be lower
                const distToCenter = Math.sqrt((qNorm-0.5)**2 + (rNorm-0.5)**2);
                if (distToCenter < 0.2) tier = Math.max(0, tier - 2);

                tempHeights.set(k, tier);
            }
        }

        // Smoothing pass to create "slopes"
        const smoothedHeights = new Map<string, number>();
        tempHeights.forEach((h, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = h;
            let count = 1;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tempHeights.has(nk)) {
                    sum += tempHeights.get(nk)!;
                    count++;
                }
            });
            smoothedHeights.set(key, Math.round(sum / count));
        });

        // Final Commit
        smoothedHeights.forEach((tier, key) => {
            let finalTier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));
            system.setHeight(key, finalTier * BLOCK_HEIGHT);
        });

        this.pruneDisconnected(system, engine);
        this.generateDecorations(system, engine);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            // Only place obstacles on high tiers or edges to keep center clean
            const tier = hPx / BLOCK_HEIGHT;
            if (tier >= 3 && Math.random() < 0.3) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }

    private static pruneDisconnected(system: MapSystem, engine: GameEngine) {
        // Find a ground tile as seed
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!system.isValidHash(seed)) {
            const firstKey = system.getMapKeys().values().next().value;
            if (!firstKey) return;
            const [q, r] = firstKey.split(',').map(Number);
            seed = HexUtils.hash(q, r);
        }

        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            const neighbors = HexUtils.neighbors(current);
            const curH = system.getTerrainHeight(current.q, current.r);
            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (system.isValidHash(nHash) && !reachable.has(nHash)) {
                    const nH = system.getTerrainHeight(n.q, n.r);
                    if (Math.abs(nH - curH) <= BLOCK_HEIGHT * 2) {
                        reachable.add(nHash);
                        queue.push(nHash);
                    }
                }
            }
        }
        const toRemove: number[] = [];
        system.getMapKeys().forEach(k => {
            const h = HexUtils.hash(...k.split(',').map(Number) as [number, number]);
            if (!reachable.has(h)) toRemove.push(h);
        });
        toRemove.forEach(h => {
            const hex = HexUtils.unhash(h);
            system.removeTile(hex.q, hex.r);
        });
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { PROJECTILE_VISUALS } from "../../../data/vfx/projectile_visuals";
import { VisualMath } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";

export class ProjectileSystem {
    public projectiles: Projectile[] = [];

    public reset() {
        this.projectiles = [];
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            // 1. Resolve Visual Definition
            const def = PROJECTILE_VISUALS[p.skill.visualProjectileEffect || p.skill.visual || 'BOLT'];
            const isInstant = def ? def.trajectory === 'INSTANT' : false;

            // 2. Update Target Position (Robust Resolution)
            const currentTargetPos = VisualMath.resolveTargetPoint(p.targetId, engine);

            // BUG FIX: If target is not found (returned 0,0,0), use the last valid targetPos
            // This prevents "fleeing to top-left corner" when units die mid-flight.
            if (currentTargetPos.x !== 0 || currentTargetPos.y !== 0) {
                p.targetPos = { x: currentTargetPos.x, y: currentTargetPos.y };
            }

            // 3. Movement Logic
            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const speed = isInstant ? 5000 : Math.max(250, p.speed); // Min speed floor
            const moveDist = speed * dt;

            // 4. Update Trail
            const lastTrail = p.trail.length > 0 ? p.trail[p.trail.length - 1] : null;
            if (!lastTrail || Vector.dist(lastTrail, {x: p.x, y: p.y}) > 15) {
                p.trail.push({x: p.x, y: p.y});
                if (p.trail.length > 20) p.trail.shift(); 
            }

            // 5. Hit Detection
            // We use a small buffer (15px) for high speed projectiles
            if (dist <= moveDist || dist < 15) {
                this.handleImpact(p, engine, skillExecutor);
                this.removeProjectile(i);
            } else {
                const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);

        if (p.skill.type === 'AOE') {
            const hitPos = p.targetPos; 
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);

            const targets = engine.agents.filter(e => 
                e.team !== p.team && e.hp > 0 && !e.banished && 
                HexUtils.dist(hitHex, e) <= radius
            );

            targets.forEach(t => { 
                if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine); 
            });

            if (source) {
                const centerHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                HazardManager.spawnHazards(source, HexUtils.range(centerHex, radius), p.skill, engine);
            }
            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: p.targetPos, skill: p.skill });
    }

    private removeProjectile(idx: number) {
        const lastIdx = this.projectiles.length - 1;
        if (idx !== lastIdx) this.projectiles[idx] = this.projectiles[lastIdx];
        this.projectiles.pop();
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let targetId = "";
        let targetPos = {x: 0, y: 0};

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 targetPos = p; 
                 targetId = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 targetPos = {x: source.target.px, y: source.target.py}; 
                 targetId = source.target.id;
             } else return;
        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                targetPos = {x: source.target.px, y: source.target.py};
                targetId = source.target.id;
            } else return;
        }

        const launchPoint = VisualMath.getUnitAnchor(source, engine);
        this.projectiles.push({
            id: Math.random().toString(36).substr(2, 6),
            x: source.px, y: source.py, 
            startX: source.px, startY: source.py, 
            startZ: launchPoint.z, 
            targetId, 
            targetPos,
            speed: skill.projectileSpeed || 600, 
            skill, 
            sourceId: source.id, 
            team: source.team, 
            trail: []
        });
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: targetId });
    }
}

import { UltContext, Point3D } from "./UltTypes";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

export class UltSequencer {
    private ctx: UltContext;

    constructor(ctx: UltContext) {
        this.ctx = ctx;
    }

    public get target(): Point3D { return this.ctx.target; }
    public get source(): Point3D | undefined { return this.ctx.sourcePos; }

    public wait(ms: number, fn: () => void) {
        setTimeout(() => fn(), ms);
    }

    public shake(amount: number, delay: number = 0) {
        this.wait(delay, () => {
            this.ctx.camera.addTrauma(amount);
        });
    }

    public effect(id: string, pos: Point3D, color?: string, delay: number = 0) {
        this.wait(delay, () => {
            this.ctx.vfx.playEffect(id, pos.x, pos.y, pos.z, color);
        });
    }

    public beam(style: string, start: Point3D, end: Point3D, color: string, duration: number = 0.5, delay: number = 0) {
        this.wait(delay, () => {
            this.ctx.vfx.playBeam(style, start, end, color, duration);
        });
    }

    public gridImpact(teamColor: string, delay: number = 0) {
        const id = teamColor === THEME_IMPERIAL.primary ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED';
        this.effect(id, this.target, teamColor, delay);
    }

    public heavenFall(height: number, color: string, style: 'GIANT_HEX' | 'ROCK' | 'METEOR', impactVfx: string, impactColor: string) {
        // 1. Projectile falls
        const p = this.ctx.vfx.state.getParticle();
        p.x = this.target.x;
        p.y = this.target.y;
        p.z = this.target.z + height;
        p.color = color;
        // INCREASED SIZE: Meteors need to be chunks
        p.size = style === 'GIANT_HEX' ? 120 : 60;

        const speed = 1800; // Slower speed = more visible flight
        const duration = height / speed;

        p.vz = -speed;
        p.life = duration;
        p.maxLife = duration;
        // METEOR style mapping
        p.type = style === 'METEOR' ? 'ROCK' : (style as any);
        p.vRotation = 8;

        // Add Fire Trail for meteors
        if (style === 'METEOR') {
            for(let i=0; i<5; i++) {
                const trail = this.ctx.vfx.state.getParticle();
                trail.x = p.x; trail.y = p.y; trail.z = p.z;
                trail.delay = (i * 0.05);
                trail.life = 0.5; trail.maxLife = 0.5;
                trail.type = 'SMOKE'; trail.color = '#f97316'; trail.size = 40;
                trail.locked = false;
                this.ctx.vfx.state.particles.push(trail);
            }
        }

        this.ctx.vfx.state.particles.push(p);

        // 2. Pre-impact Ground Ring
        const ring = this.ctx.vfx.state.getParticle();
        ring.x = this.target.x; ring.y = this.target.y; ring.z = this.target.z + 5;
        ring.life = duration; ring.maxLife = duration;
        ring.color = color; ring.size = p.size * 1.5;
        ring.type = 'RING';
        this.ctx.vfx.state.particles.push(ring);

        // 3. Impact
        this.wait(duration * 1000, () => {
            this.ctx.vfx.playEffect(impactVfx, this.target.x, this.target.y, this.target.z, impactColor);
            this.ctx.camera.addTrauma(0.5); // Stronger shake
        });
    }
}

import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {

    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);

        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.4) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;

        return { x: agent.px, y: agent.py, z: z };
    }

    public static getHexCenter(q: number, r: number, engine: GameEngine): Point3D {
        const p = HexUtils.toPx(q, r, engine.mapConfig);
        const h = engine.map.getTerrainHeight(q, r);
        return { x: p.x, y: p.y, z: h };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: 0 };

        // 1. Is it a Unit?
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) {
            // Even if dying, we track the body position
            return this.getUnitAnchor(agent, engine);
        }

        // 2. Is it a Ground Location?
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                const center = this.getHexCenter(q, r, engine);
                center.z += 10; 
                return center;
            }
        }

        // BUG FIX: Do NOT return 0,0,0 if the targetId is non-empty but agent is gone.
        // Returning 0,0,0 tells the projectile to fly to the top-left screen edge.
        return { x: 0, y: 0, z: 0 };
    }
}

