import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y, ISO_ANGLE } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * 核心坐標投影邏輯 - 加入旋轉矩陣以實現「斜向縱深」
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        let wx = 0;
        let wy = 0;

        // 1. Calculate basic World-Space coordinates (Un-projected)
        if (layout === 'FLAT') {
            wx = (3 / 2 * q) * HEX_SIZE;
            wy = (SQRT3 * (r + q / 2)) * HEX_SIZE;
        } else {
            wx = (SQRT3 * (q + r / 2)) * HEX_SIZE;
            wy = (3 / 2 * r) * HEX_SIZE;
        }

        // 2. Apply Rotation Matrix + Squashed Isometric Scale
        const cosA = Math.cos(ISO_ANGLE);
        const sinA = Math.sin(ISO_ANGLE);

        // ScreenX = wx*cos - wy*sin
        // ScreenY = (wx*sin + wy*cos) * ISO_SCALE_Y
        const rx = wx * cosA - wy * sinA;
        const ry = (wx * sinA + wy * cosA) * ISO_SCALE_Y;

        return {
            x: rx + offsetX,
            y: ry + offsetY
        };
    },

    /**
     * 逆向投影邏輯 - 使用逆矩陣還原座標
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y;

        const cosA = Math.cos(ISO_ANGLE);
        const sinA = Math.sin(ISO_ANGLE);

        // Inverse Rotation Matrix
        // WorldX = dx*cos + dy*sin
        // WorldY = -dx*sin + dy*cos
        const wx = dx * cosA + dy * sinA;
        const wy = -dx * sinA + dy * cosA;

        let q = 0;
        let r = 0;

        if (layout === 'FLAT') {
            q = (2 / 3 * wx) / HEX_SIZE;
            r = (-1 / 3 * wx + SQRT3 / 3 * wy) / HEX_SIZE;
        } else {
            q = (SQRT3 / 3 * wx - 1 / 3 * wy) / HEX_SIZE;
            r = (2 / 3 * wy) / HEX_SIZE;
        }

        return { q, r };
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    }
};

import { HEX_SIZE, ISO_SCALE_Y, ISO_ANGLE } from "../../../constants";
import { HexLayout } from "../../../types";

// 1. Static Geometry Constants
const SQRT3 = Math.sqrt(3);

/**
 * 核心六邊形幾何真理 (The Single Source of Truth for Hex Geometry)
 * 升級版：支援旋轉傾斜視角 (Tilted Iso)
 */
export const HexGeometry = {

    /**
     * 計算六邊形頂點 - 必須與 HexMath 的投影矩陣同步
     */
    getVertices(radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT'): {x: number, y: number}[] {
        const vertices = [];
        const isFlat = layout === 'FLAT';
        const baseStartAngle = isFlat ? 0 : Math.PI / 6;

        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;
        const tiltAngle = applyIso ? ISO_ANGLE : 0; // Rotate coordinates if iso

        for (let i = 0; i < 6; i++) {
            const angle = baseStartAngle + i * Math.PI / 3;

            // Un-rotated world vertex
            const wx = Math.cos(angle) * radius;
            const wy = Math.sin(angle) * radius;

            // Apply rotation matrix
            const cosA = Math.cos(tiltAngle);
            const sinA = Math.sin(tiltAngle);

            const rx = wx * cosA - wy * sinA;
            const ry = (wx * sinA + wy * cosA) * scaleY;

            vertices.push({ x: rx, y: ry });
        }
        return vertices;
    },

    /**
     * [唯一路徑] 在 Context 上描繪六邊形路徑
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * 支援旋轉的向量描繪 (用於技能冷卻、特效環)
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const isFlat = layout === 'FLAT';
        const baseStartAngle = isFlat ? 0 : Math.PI / 6;
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;
        const tiltAngle = applyIso ? ISO_ANGLE : 0;

        const cosA = Math.cos(tiltAngle);
        const sinA = Math.sin(tiltAngle);

        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = baseStartAngle + i * Math.PI / 3 + rotation;
            const wx = Math.cos(angle) * radius;
            const wy = Math.sin(angle) * radius;

            const rx = wx * cosA - wy * sinA;
            const ry = (wx * sinA + wy * cosA) * scaleY;

            if (i === 0) ctx.moveTo(x + rx, y + ry);
            else ctx.lineTo(x + rx, y + ry);
        }
        ctx.closePath();
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils, HexMath } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Standard Theater Size: 12x12
        engine.mapConfig.w = 12; 
        engine.mapConfig.h = 12; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        // Center calculation in logic space
        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const hex = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                const k = HexUtils.key(hex);
                system.registerTile(hex.q, hex.r);

                // --- THEATER FORMULA 4.0 (Visual Depth Aware) ---
                // Get Screen position (ignoring offset for normalized score)
                const screenPos = HexMath.hexToPixel(hex.q, hex.r, 0, 0, engine.mapConfig.layout);

                // Score based on Screen Y (Items at visual top should be high)
                // Normalize Screen Y between -600 and 600 roughly
                const yNorm = (screenPos.y + 300) / 600; 
                let theaterScore = Math.pow(1 - yNorm, 1.5) * 6; // Higher at top screen

                // Add side cliffs based on Screen X
                const xNorm = Math.abs(screenPos.x) / 400;
                theaterScore += xNorm * 2.5;

                // Steps logic: Clear tiers
                let tier = Math.floor(theaterScore);

                // Central Fighting Pit (Logic Space center)
                const distToCenter = Math.sqrt((q/W-0.5)**2 + (r/H-0.5)**2);
                if (distToCenter < 0.25) {
                    tier = Math.max(0, Math.floor(tier * 0.2));
                }

                tempHeights.set(k, tier);
            }
        }

        // Smoothing: Selective
        const finalHeights = new Map<string, number>();
        tempHeights.forEach((h, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = h;
            let count = 1;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tempHeights.has(nk)) {
                    const nh = tempHeights.get(nk)!;
                    if (Math.abs(nh - h) <= 1) {
                        sum += nh;
                        count++;
                    }
                }
            });
            finalHeights.set(key, Math.round(sum / count));
        });

        finalHeights.forEach((tier, key) => {
            let finalTier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));
            system.setHeight(key, finalTier * BLOCK_HEIGHT);
        });

        this.pruneDisconnected(system, engine);
        this.generateDecorations(system, engine);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = hPx / BLOCK_HEIGHT;
            if (tier >= 4 && Math.random() < 0.5) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }

    private static pruneDisconnected(system: MapSystem, engine: GameEngine) {
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!system.isValidHash(seed)) {
            const keys = Array.from(system.getMapKeys());
            if (keys.length === 0) return;
            const [q, r] = keys[0].split(',').map(Number);
            seed = HexUtils.hash(q, r);
        }

        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            const neighbors = HexUtils.neighbors(current);
            const curH = system.getTerrainHeight(current.q, current.r);
            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (system.isValidHash(nHash) && !reachable.has(nHash)) {
                    const nH = system.getTerrainHeight(n.q, n.r);
                    if (Math.abs(nH - curH) <= BLOCK_HEIGHT * 2) {
                        reachable.add(nHash);
                        queue.push(nHash);
                    }
                }
            }
        }
        const toRemove: string[] = [];
        system.getMapKeys().forEach(k => {
            const h = HexUtils.hash(...k.split(',').map(Number) as [number, number]);
            if (!reachable.has(h)) toRemove.push(k);
        });
        toRemove.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            system.removeTile(q, r);
        });
    }
}

