import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Standard Map Size
        engine.mapConfig.w = 12; 
        engine.mapConfig.h = 12; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        // Seed for this specific generation
        const seed = Math.random() * 1000;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const hex = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                const k = HexUtils.key(hex);
                system.registerTile(hex.q, hex.r);

                // --- THEATER FORMULA 5.0 (Organic & Varied) ---

                // 1. Coordinates logic
                const qn = q / (W - 1);
                const rn = r / (H - 1);

                // 2. Base Theater Gradient (Back-to-Front slope)
                // Use linear gradient to prevent extreme "wall" at edges
                let baseTier = ((1 - qn) * 3) + ((1 - rn) * 3);

                // 3. Multi-layer Noise (Sinusoidal approximation)
                const noise1 = Math.sin(q * 0.8 + r * 0.5 + seed) * 1.5;
                const noise2 = Math.cos(q * 0.4 - r * 0.9 + seed * 0.5) * 1.0;

                let combined = baseTier + noise1 + noise2;

                // 4. Central Fighting Area (Flattening)
                const distToCenter = Math.sqrt((qn-0.5)**2 + (rn-0.5)**2);
                if (distToCenter < 0.35) {
                    combined *= (distToCenter / 0.35); // Smoothly sink center
                }

                // Final clamp to 0-6 range
                let tier = Math.floor(Math.max(0, Math.min(MAX_TERRAIN_TIER, combined)));

                tempHeights.set(k, tier);
            }
        }

        // Smoothing: Moderate, preserve "Strategic Plateaus"
        const finalHeights = new Map<string, number>();
        tempHeights.forEach((h, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = h;
            let count = 1;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tempHeights.has(nk)) {
                    const nh = tempHeights.get(nk)!;
                    // Only blend if height difference is reasonable
                    if (Math.abs(nh - h) <= 2) {
                        sum += nh;
                        count++;
                    }
                }
            });
            finalHeights.set(key, Math.round(sum / count));
        });

        finalHeights.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.pruneDisconnected(system, engine);
        this.generateDecorations(system, engine);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = hPx / BLOCK_HEIGHT;
            // Strategic placement: Obstacles on edges of plateaus
            if (tier >= 3 && Math.random() < 0.2) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }

    private static pruneDisconnected(system: MapSystem, engine: GameEngine) {
        const keys = Array.from(system.getMapKeys());
        if (keys.length === 0) return;

        // Pick center-most tile that exists as seed
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!system.isValidHash(seed)) {
            const [q, r] = keys[0].split(',').map(Number);
            seed = HexUtils.hash(q, r);
        }

        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            const neighbors = HexUtils.neighbors(current);
            const curH = system.getTerrainHeight(current.q, current.r);
            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (system.isValidHash(nHash) && !reachable.has(nHash)) {
                    const nH = system.getTerrainHeight(n.q, n.r);
                    // Standard jump height limit for connectivity
                    if (Math.abs(nH - curH) <= BLOCK_HEIGHT * 2) {
                        reachable.add(nHash);
                        queue.push(nHash);
                    }
                }
            }
        }
        const toRemove: string[] = [];
        system.getMapKeys().forEach(k => {
            const h = HexUtils.hash(...k.split(',').map(Number) as [number, number]);
            if (!reachable.has(h)) toRemove.push(k);
        });
        toRemove.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            system.removeTile(q, r);
        });
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { HexLayout } from "../../../types";

/**
 * 核心六邊形幾何真理 (Single Source of Truth)
 * 重構版：確保六邊形本身不隨地圖坐標系旋轉，維持與螢幕平行
 */
export const HexGeometry = {

    /**
     * 計算六邊形頂點 - 形狀必須相對於螢幕端正
     */
    getVertices(radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT'): {x: number, y: number}[] {
        const vertices = [];

        /**
         * 方向定義標準化：
         * FLAT (平頂): 頂部和底部是水平邊。起始角 0 (點在右側) 產生水平邊在上下。
         * POINTY (尖頂): 頂部和底部是尖角。起始角 Math.PI / 6 (30度) 產生垂直邊在左右。
         */
        const baseStartAngle = layout === 'FLAT' ? 0 : Math.PI / 6;
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = baseStartAngle + i * Math.PI / 3;

            // 直接計算頂點，不應用坐標系旋轉 ISO_ANGLE
            const rx = Math.cos(angle) * radius;
            const ry = Math.sin(angle) * radius * scaleY;

            vertices.push({ x: rx, y: ry });
        }
        return vertices;
    },

    /**
     * [唯一路徑] 在 Context 上描繪六邊形路徑
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * 支援旋轉的向量描繪 (用於技能冷卻、特效環)
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        const cosR = Math.cos(rotation);
        const sinR = Math.sin(rotation);

        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            // 在壓扁後的座標系中進行視覺旋轉
            const vx = verts[i].x;
            const vy = verts[i].y;
            const rx = vx * cosR - vy * sinR;
            const ry = vx * sinR + vy * cosR;

            if (i === 0) ctx.moveTo(x + rx, y + ry);
            else ctx.lineTo(x + rx, y + ry);
        }
        ctx.closePath();
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const SLAB_THICKNESS = 12; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const topOffset = -height;
        const bottomOffset = SLAB_THICKNESS;

        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // 修正後的牆面渲染順序 (對應端正後的六邊形)
        // 在 Flat Top 下，面向螢幕的面是右下 (1-2), 中下 (2-3), 左下 (3-4)
        if (layout === 'FLAT') {
            this.drawSideFace(ctx, vertices, 3, 2, topOffset, bottomOffset, theme.sideLight);
            this.drawSideFace(ctx, vertices, 2, 1, topOffset, bottomOffset, theme.sideDark);
            this.drawSideFace(ctx, vertices, 4, 3, topOffset, bottomOffset, theme.sideDark);
        } else {
            // Pointy Top 面向螢幕的面不同
            this.drawSideFace(ctx, vertices, 3, 2, topOffset, bottomOffset, theme.sideLight);
            this.drawSideFace(ctx, vertices, 2, 1, topOffset, bottomOffset, theme.sideDark);
            this.drawSideFace(ctx, vertices, 1, 0, topOffset, bottomOffset, theme.sideDark);
        }

        ctx.translate(0, topOffset);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;

        ctx.beginPath();
        if (layout === 'FLAT') {
            // 只描繪頂部的前緣邊線
            ctx.moveTo(vertices[4].x, vertices[4].y);
            ctx.lineTo(vertices[3].x, vertices[3].y);
            ctx.lineTo(vertices[2].x, vertices[2].y);
            ctx.lineTo(vertices[1].x, vertices[1].y);
        } else {
            ctx.moveTo(vertices[3].x, vertices[3].y);
            ctx.lineTo(vertices[2].x, vertices[2].y);
            ctx.lineTo(vertices[1].x, vertices[1].y);
            ctx.lineTo(vertices[0].x, vertices[0].y);
        }
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, bottomOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(verts[i1].x, verts[i1].y + bottomOffset);
        ctx.lineTo(verts[i2].x, verts[i2].y + bottomOffset);
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(verts[i1].x, verts[i1].y + bottomOffset);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

