import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * Standard Hex to Pixel calculation.
     * Tiling for FLAT hexagons:
     * dx = 1.5 * radius
     * dy = sqrt(3) * radius (staggered)
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        let x = 0;
        let y = 0;

        if (layout === 'FLAT') {
            x = (3 / 2 * q) * HEX_SIZE;
            y = (SQRT3 * (r + q / 2)) * HEX_SIZE;
        } else {
            x = (SQRT3 * (q + r / 2)) * HEX_SIZE;
            y = (3 / 2 * r) * HEX_SIZE;
        }

        // Apply Isometric Squashing (2.5D perspective)
        return {
            x: x + offsetX,
            y: y * ISO_SCALE_Y + offsetY
        };
    },

    /**
     * Inverse Pixel to Hex calculation.
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y;

        let q = 0;
        let r = 0;

        if (layout === 'FLAT') {
            q = (2 / 3 * dx) / HEX_SIZE;
            r = (-1 / 3 * dx + SQRT3 / 3 * dy) / HEX_SIZE;
        } else {
            q = (SQRT3 / 3 * dx - 1 / 3 * dy) / HEX_SIZE;
            r = (2 / 3 * dy) / HEX_SIZE;
        }

        return { q, r };
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Dynamic map sizing for theater variety
        engine.mapConfig.w = 12 + Math.floor(Math.random() * 3); 
        engine.mapConfig.h = 8 + Math.floor(Math.random() * 4); 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        // High frequency noise seeds
        const seed1 = Math.random() * 100;
        const seed2 = Math.random() * 100;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const hex = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                const k = HexUtils.key(hex);
                system.registerTile(hex.q, hex.r);

                // --- THEATER FORMULA 6.0 (Continuous Tiers) ---

                // Coordinates normalized (0 to 1)
                const qn = q / (W - 1);
                const rn = r / (H - 1);

                // 1. Theater Bowl Base (Concave profile)
                // Back-to-Front gradient + Side walls
                const depthGrad = (1 - rn) * 3.5;
                const sideCliffs = Math.pow(Math.abs(qn - 0.5) * 2, 2) * 3;

                // 2. Multi-layer Sine Noise for organic variance
                // This ensures we get values across the full 0-6 range
                const n1 = Math.sin(q * 0.7 + seed1) * 1.5;
                const n2 = Math.cos(r * 0.9 + seed2) * 1.5;

                let rawHeight = depthGrad + sideCliffs + n1 + n2;

                // 3. Central Flat Area (Combat Pit)
                const distToCenter = Math.sqrt((qn - 0.5)**2 + (rn - 0.5)**2);
                if (distToCenter < 0.3) {
                    rawHeight = Math.min(rawHeight, 1 + distToCenter * 5);
                }

                // Final clamping to integer tiers 0-6
                let tier = Math.floor(Math.max(0, Math.min(MAX_TERRAIN_TIER, rawHeight)));
                tempHeights.set(k, tier);
            }
        }

        // Smoothing pass to ensure walls connect reasonably (max 2 tier difference)
        const finalHeights = new Map<string, number>();
        tempHeights.forEach((h, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = h;
            let count = 1;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tempHeights.has(nk)) {
                    const nh = tempHeights.get(nk)!;
                    // Strict connectivity: smooth out extreme spikes
                    if (Math.abs(nh - h) > 2) {
                        sum += (h + (nh > h ? 1 : -1));
                    } else {
                        sum += nh;
                    }
                    count++;
                }
            });
            finalHeights.set(key, Math.round(sum / count));
        });

        finalHeights.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.pruneDisconnected(system, engine);
        this.generateDecorations(system, engine);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = hPx / BLOCK_HEIGHT;
            // Place obstacles on high tiers or perimeter
            if (tier >= 4 && Math.random() < 0.25) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }

    private static pruneDisconnected(system: MapSystem, engine: GameEngine) {
        const keys = Array.from(system.getMapKeys());
        if (keys.length === 0) return;

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!system.isValidHash(seed)) {
            const [q, r] = keys[0].split(',').map(Number);
            seed = HexUtils.hash(q, r);
        }

        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            const neighbors = HexUtils.neighbors(current);
            const curH = system.getTerrainHeight(current.q, current.r);
            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (system.isValidHash(nHash) && !reachable.has(nHash)) {
                    const nH = system.getTerrainHeight(n.q, n.r);
                    if (Math.abs(nH - curH) <= BLOCK_HEIGHT * 2.5) {
                        reachable.add(nHash);
                        queue.push(nHash);
                    }
                }
            }
        }
        const toRemove: string[] = [];
        system.getMapKeys().forEach(k => {
            const h = HexUtils.hash(...k.split(',').map(Number) as [number, number]);
            if (!reachable.has(h)) toRemove.push(k);
        });
        toRemove.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            system.removeTile(q, r);
        });
    }
}

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 0.5; // Small overlap to prevent sub-pixel gaps

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // Transition: y is Visual Base (Ground level), height is the block height
        const visualTopY = -height;

        // Use precision vertices
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING (BOTTOM UP) ---
        // For a Flat Top hex viewed from the front, the visible faces are:
        // Index 0 to 1 (Bottom Right), Index 1 to 2 (Bottom), Index 2 to 3 (Bottom Left)

        if (layout === 'FLAT') {
            // Front-facing walls (Facing the camera/user)
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight); // Front
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);  // Front-Left
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);  // Front-Right
        } else {
            // Pointy Top Visible Walls
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // High-fidelity Rim Lighting
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.2;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        // Standard Terrain Specific FX
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    /**
     * Draws a strictly vertical wall face between two top-face vertices.
     * Dropping down from (v1.x, v1.y) to the ground level (v1.x, 0).
     */
    drawVerticalWall(ctx: CanvasRenderingContext2D, v1: {x:number, y:number}, v2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();

        // Start at top face edge
        ctx.moveTo(v1.x, v1.y + topY);
        ctx.lineTo(v2.x, v2.y + topY);

        // Drop down to ground level (y=0 in our translated context)
        // Add epsilon to ensure overlap with neighboring blocks
        ctx.lineTo(v2.x, v2.y + WALL_SLOP_EPSILON);
        ctx.lineTo(v1.x, v1.y + WALL_SLOP_EPSILON);

        ctx.closePath();
        ctx.fill();

        // Structural Line (Clean corner)
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y + topY);
        ctx.lineTo(v1.x, v1.y + WALL_SLOP_EPSILON);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);

export const HexMath = {

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * Diamond Hex Mapping (SRPG Standard)
     * This aligns the q and r axes to 45-degree diagonals.
     * It ensures hexes are parallel to screen but arranged in a 'theater' slant.
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        // Base dimensions for a flat-top hex
        const w = 2 * HEX_SIZE;
        const h = SQRT3 * HEX_SIZE;

        // Transform axial coordinates to a slanted 'Diamond' grid
        // This math guarantees adjacency without rotation gaps
        const x = (q - r) * (w * 0.75);
        const y = (q + r) * (h * 0.5);

        return {
            x: x + offsetX,
            y: y * ISO_SCALE_Y + offsetY
        };
    },

    /**
     * Inverse mapping for Diamond Grid
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y;

        const w = 2 * HEX_SIZE;
        const h = SQRT3 * HEX_SIZE;

        // Solve the system:
        // dx = (q - r) * 0.75w
        // dy = (q + r) * 0.5h
        const q_minus_r = dx / (w * 0.75);
        const q_plus_r = dy / (h * 0.5);

        const q = (q_minus_r + q_plus_r) / 2;
        const r = (q_plus_r - q_minus_r) / 2;

        return { q, r };
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Squared maps work best for diamond layouts
        engine.mapConfig.w = 10; 
        engine.mapConfig.h = 10; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        const seed = Math.random() * 100;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                // In diamond mapping, we iterate logic grid
                const k = `${q},${r}`;
                system.registerTile(q, r);

                // --- DIAMOND THEATER FORMULA ---
                // q+r is the diagonal depth in our new layout
                const depth = (q + r) / (W + H - 2); 
                const lateral = (q - r) / (W - 1); 

                // 1. Base Gradient: Back (low q,r) is HIGH, Front (high q,r) is LOW
                let rawHeight = (1 - depth) * 5;

                // 2. Side Walls (Amphitheater effect)
                rawHeight += Math.abs(lateral) * 2;

                // 3. Noise for organic steps
                const noise = Math.sin(q * 0.8 + seed) * 1.0 + Math.cos(r * 0.8 + seed) * 1.0;
                rawHeight += noise;

                // 4. Central Pit
                const distToCenter = Math.sqrt(lateral**2 + (depth-0.5)**2);
                if (distToCenter < 0.3) {
                    rawHeight = Math.min(rawHeight, 1);
                }

                let tier = Math.floor(Math.max(0, Math.min(MAX_TERRAIN_TIER, rawHeight)));
                tempHeights.set(k, tier);
            }
        }

        // Smoothing
        tempHeights.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = hPx / BLOCK_HEIGHT;
            if (tier >= 4 && Math.random() < 0.15) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

