import { ISO_SCALE_Y, BASE_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; // Slightly increased for better diamond-mapping coverage

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // height = Tier Height
        // visualTopY = Current vertical displacement from logical ground
        const visualTopY = -height;
        // Total wall drop = Height + Base thickness
        const wallDrop = height + BASE_HEIGHT;

        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING (BOTTOM UP) ---
        // We render walls from ground level up to the top face
        if (layout === 'FLAT') {
            // Flat Top South Faces
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, wallDrop, theme.sideLight); // South
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, wallDrop, theme.sideDark);  // South-West
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, wallDrop, theme.sideDark);  // South-East
        } else {
            // Pointy Top South Faces (V-Shape front)
            // Indices: 1 is bottom center, 0 is right-down, 2 is left-down
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, wallDrop, theme.sideDark);  // Front-Right Face
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, wallDrop, theme.sideLight); // Front-Left Face

            // Structural Line for the Pointy front edge to enhance depth
            ctx.strokeStyle = 'rgba(0,0,0,0.15)';
            ctx.lineWidth = 0.8;
            ctx.beginPath();
            ctx.moveTo(vertices[1].x, vertices[1].y + visualTopY);
            ctx.lineTo(vertices[1].x, vertices[1].y + BASE_HEIGHT + WALL_SLOP_EPSILON);
            ctx.stroke();
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.2;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    /**
     * Draws a vertical wall segment.
     * @param topY The displacement of the top face (negative)
     * @param wallDrop The total depth of the wall (positive, from top face down to base)
     */
    drawVerticalWall(ctx: CanvasRenderingContext2D, v1: {x:number, y:number}, v2: {x:number, y:number}, topY: number, wallDrop: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();

        // Start at top face edge
        ctx.moveTo(v1.x, v1.y + topY);
        ctx.lineTo(v2.x, v2.y + topY);

        // Drop down to the base height (includes BASE_HEIGHT)
        // Add WALL_SLOP_EPSILON to ensure the base overlaps slightly with anything behind it
        ctx.lineTo(v2.x, v2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(v1.x, v1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);

        ctx.closePath();
        ctx.fill();

        // Shadow line for the edge between faces
        ctx.strokeStyle = 'rgba(0,0,0,0.1)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(v1.x, v1.y + topY);
        ctx.lineTo(v1.x, v1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Squared maps work best for diamond layouts
        engine.mapConfig.w = 10; 
        engine.mapConfig.h = 10; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        const seed = Math.random() * 100;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = `${q},${r}`;
                system.registerTile(q, r);

                // --- ENHANCED VERTICALITY FORMULA ---
                const depth = (q + r) / (W + H - 2); 
                const lateral = (q - r) / (W - 1); 

                // 1. Steep Gradient (Tier 0 to 4 base)
                let rawHeight = (1 - depth) * 4.5;

                // 2. Side Cliffs (Amphitheater effect)
                rawHeight += Math.abs(lateral) * 2.5;

                // 3. High-freq Organic Noise for more tiered steps
                const n1 = Math.sin(q * 1.2 + seed) * 1.2;
                const n2 = Math.cos(r * 1.4 + seed) * 1.2;
                rawHeight += (n1 + n2);

                // 4. Combat Pit (Lower central area for battle)
                const distToCenter = Math.sqrt(lateral**2 + (depth-0.5)**2);
                if (distToCenter < 0.25) {
                    rawHeight = Math.min(rawHeight, 1);
                }

                // Final Clamp to full 0-6 range
                let tier = Math.floor(Math.max(0, Math.min(MAX_TERRAIN_TIER, rawHeight)));
                tempHeights.set(k, tier);
            }
        }

        // Apply heights to system
        tempHeights.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = hPx / BLOCK_HEIGHT;
            // Place obstacles primarily on high peaks (tiers 5-6)
            if (tier >= 5 && Math.random() < 0.2) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * High-Level Map Topology Generator
 * Guarantees a connected battleground using Basin-and-Step logic.
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        engine.mapConfig.w = 10; 
        engine.mapConfig.h = 10; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        // 1. Generate Base Basin Geometry
        // Center is lower (Combat Pit), edges are higher (Spectator tiers)
        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = `${q},${r}`;
                system.registerTile(q, r);

                const centerQ = (W - 1) / 2;
                const centerR = (H - 1) / 2;
                const distToCenter = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const normalizedDist = distToCenter / Math.sqrt(centerQ**2 + centerR**2);

                // Base height follows a parabolic basin curve
                let tier = Math.floor(normalizedDist * 4.5);

                // Add organic noise variation
                const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8) * 1.5;
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier + Math.round(noise)));

                tiers.set(k, tier);
            }
        }

        // 2. Connectivity Calibration (Gradient Smoothing)
        // Ensure neighbor height diff <= 2 (Standard unit jump)
        for (let i = 0; i < 3; i++) { // Run 3 passes of smoothing
            tiers.forEach((tier, key) => {
                const [q, r] = key.split(',').map(Number);
                const neighbors = HexUtils.neighbors({q, r});

                neighbors.forEach(n => {
                    const nk = HexUtils.key(n);
                    if (tiers.has(nk)) {
                        const nTier = tiers.get(nk)!;
                        // If difference is too steep (> 2 tiers), lower the high point
                        if (tier - nTier > 2) {
                            tiers.set(key, nTier + 2);
                        }
                    }
                });
            });
        }

        // 3. Apply to System
        tiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = hPx / BLOCK_HEIGHT;
            // Never place obstacles on the center floor (Tiers 0-1) to preserve combat space
            if (tier >= 4 && Math.random() < 0.25) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, MovementType } from "../../types";
import { HexUtils, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";
import { TargetingSystem } from "./TargetingSystem";

export class Pathfinder {
    private _pfQueue = new Int32Array(4096); 
    private _pfCameFrom = new Map<number, number>();
    private _pfBlockers = new Set<number>();

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine,
        targeting: TargetingSystem
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);
        const effRange = targeting.getEffectiveRange(startAgent, endQ, endR, range, engine);
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});

        if (startDist <= effRange) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Static & Dynamic Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    this._pfBlockers.add(HexUtils.hash(a.q, a.r));

                    // CRITICAL: Block cells currently reserved by moving units
                    if (a.isMoving && a.path.length > 0) {
                        this._pfBlockers.add(HexUtils.hash(a.path[0].q, a.path[0].r));
                    }
                }
            }
        }

        let head = 0, tail = 0;
        this._pfQueue[head++] = startH;
        this._pfCameFrom.set(startH, -1);

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > 2000) break;

            const currentH = this._pfQueue[tail++];
            const currentHex = HexUtils.unhash(currentH);

            if (HexUtils.dist(currentHex, targetHex) <= targeting.getEffectiveRange(currentHex, targetHex.q, targetHex.r, range, engine)) {
                foundHash = currentH;
                break;
            }

            for (let j = 0; j < 6; j++) {
                const nextH = currentH + NEIGHBOR_HASH_OFFSETS[j];
                if (this._pfCameFrom.has(nextH) || !engine.map.isValidHash(nextH)) continue;

                // Wall/Obstacle Check
                if (engine.map.hasObstacleHash(nextH)) {
                    const type = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(nextH)));
                    const def = OBSTACLE_DB[type || 'WALL'];
                    if (startAgent.movementType === MovementType.FLYING ? def?.blocksFlying : def?.blocksMovement) continue;
                }

                // Reservation Check
                if (!ignoreUnits && this._pfBlockers.has(nextH)) continue;

                // Verticality Check
                if (startAgent.movementType !== MovementType.FLYING) {
                    const cH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);
                    const nHex = HexUtils.unhash(nextH);
                    const nH = engine.map.getTerrainHeight(nHex.q, nHex.r);
                    if (Math.abs(nH - cH) > Math.max(1, startAgent.jump) * BLOCK_HEIGHT) continue;
                }

                this._pfCameFrom.set(nextH, currentH);
                if (head < 4096) this._pfQueue[head++] = nextH;
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;
            while (curr !== startH && path.length < 100) {
                path.push(HexUtils.unhash(curr));
                curr = this._pfCameFrom.get(curr) || -1;
                if (curr === -1) break;
            }
            return path.reverse();
        }
        return [];
    }
}

import { Agent, GameEngine } from "../../game";
import { HexUtils, Vector } from "../../utils";
import { MovementType } from "../../../types";
import { BLOCK_HEIGHT } from "../../../constants";

/**
 * Robust Anti-Stacking System
 * Resolves accidental overlaps (from skills/physics) by expelling units to valid neighbors.
 */
export class StackingResolver {

    public resolve(engine: GameEngine) {
        const cellMap = new Map<number, Agent[]>();

        // 1. Group by logical coordinates
        for (const a of engine.agents) {
            if (a.hp <= 0 || a.banished) continue;
            const h = HexUtils.hash(a.q, a.r);
            if (!cellMap.has(h)) cellMap.set(h, []);
            cellMap.get(h)!.push(a);
        }

        // 2. Resolve multi-unit cells
        cellMap.forEach((occupants, hash) => {
            if (occupants.length > 1) {
                this.expelExcess(occupants, hash, engine);
            }
        });
    }

    private expelExcess(list: Agent[], hash: number, engine: GameEngine) {
        // Sort: Stationary units are "owners", moving units are "guests"
        list.sort((a, b) => (a.isMoving ? 1 : 0) - (b.isMoving ? 0 : 1));

        const owner = list[0];
        const currentH = engine.map.getTerrainHeight(owner.q, owner.r);

        for (let i = 1; i < list.length; i++) {
            const guest = list[i];
            const found = this.findExpulsionSpot(guest, currentH, engine);

            if (found) {
                // Perform Logical Displacement
                engine.updateAgentPosition(guest, found.q, found.r);

                // Clear active move to prevent pathing glitches
                if (guest.isMoving) {
                    guest.isMoving = false;
                    guest.path = [];
                }

                // Add small physical impulse to separate visually
                const dir = Vector.normalize(Vector.sub(
                    HexUtils.toPx(found.q, found.r, engine.mapConfig), 
                    HexUtils.toPx(owner.q, owner.r, engine.mapConfig)
                ));
                guest.physics.vx += dir.x * 200;
                guest.physics.vy += dir.y * 200;

                engine.log(guest, 'SYSTEM', '擠出', `從 (${owner.q},${owner.r})`, '解決重疊狀態');
            }
        }
    }

    private findExpulsionSpot(agent: Agent, sourceH: number, engine: GameEngine) {
        // Spiral-like search: Check nearest neighbors first
        const neighbors = HexUtils.neighbors(agent);

        // Shuffle to avoid directional bias
        for (let i = neighbors.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
        }

        for (const n of neighbors) {
            // Check basic validity
            if (!engine.map.isValid(n.q, n.r)) continue;

            // Check if already blocked by static or dynamic
            if (engine.map.isBlocked(n.q, n.r, engine, agent.id)) continue;

            // Height Safety Check (Expulsion shouldn't throw units off un-jumpable cliffs)
            if (agent.movementType === MovementType.GROUND) {
                const nH = engine.map.getTerrainHeight(n.q, n.r);
                const jumpLimit = Math.max(1, agent.jump) * BLOCK_HEIGHT;
                if (Math.abs(nH - sourceH) > jumpLimit) continue;
            }

            return n;
        }
        return null;
    }
}

import { GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { MovementType } from "../../../types";
import { OBSTACLE_DB } from "../../../data/obstacles";
import { MapSystem } from "../map";

export class MapSpatial {

    public static isBlocked(
        system: MapSystem,
        q: number, 
        r: number, 
        engine: GameEngine, 
        ignoreId: string | null = null, 
        movementType: MovementType = MovementType.GROUND
    ): boolean {
        const h = HexUtils.hash(q, r);

        // 1. Static Obstacles
        if (system.obstaclesHash.has(h)) {
            const obsId = system.obstacles.get(HexUtils.key({q, r}));
            const def = obsId ? OBSTACLE_DB[obsId] : null;
            if (movementType === MovementType.FLYING ? def?.blocksFlying : def?.blocksMovement) return true;
        }

        // 2. Dynamic Units (Already Standing There)
        const occupant = engine.agentMap.get(h);
        if (occupant && occupant.id !== ignoreId && occupant.hp > 0 && !occupant.banished) return true;

        // 3. Movement Intent (Strict Reservation)
        // Check if any other agent is moving TO this cell
        for (const a of engine.agents) {
            if (a.id === ignoreId || a.hp <= 0 || !a.isMoving || a.path.length === 0) continue;
            const dest = a.path[0];
            if (dest.q === q && dest.r === r) return true;
        }

        return false;
    }

    public static hasObstacle(system: MapSystem, q: number, r: number): boolean {
        return system.obstaclesHash.has(HexUtils.hash(q, r));
    }
}

import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { FACTION_VISUALS } from "../../data/vfx/faction_visuals";
import { HexUtils } from "../utils";

export class AgentManager {
    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number): Agent | null {
        // Prevent spawning on blocked tiles or other units
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);
        const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        a.role = allRoles[Math.floor(Math.random() * allRoles.length)];

        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        const stats = UNIT_DB[a.role];
        a.maxHp = hpOverride || stats.maxHp;
        a.hp = a.maxHp;
        a.maxMp = stats.maxMp;
        a.moveSpeed = stats.moveSpeed; 
        a.movementType = stats.movementType;
        a.jump = stats.jump;
        a.weight = stats.weight;

        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rndS = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rndS(validSkills.filter(s => s.tag === 'ULT')),
            rndS(validSkills.filter(s => s.tag === 'ACTIVE')),
            rndS(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        const visual = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];
        a.spawnTimer = 0.5;
        engine.events.push({ type: 'SPAWN', pos: { x: a.px, y: a.py }, color: visual.primaryColor, sourceId: a.id });

        if (engine.isRunning) {
            a.skills = a.skillIds.map(id => engine.skillDB.find(s => s.id === id) || null);
            a.bt = engine.ai.buildAI(a, engine);
            a.animState = AnimState.IDLE;
        }

        engine.agents.push(a);
        engine.agentMap.set(HexUtils.hash(q, r), a);
        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;
        if (!a.deadLogged) {
            engine.log(a, 'DEATH', '死亡', null, '陣亡');
            engine.events.push({ type: 'DEATH', pos: {x: a.px, y: a.py}, sourceId: a.id, team: a.team });
            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);
            engine.agentMap.delete(HexUtils.hash(a.q, a.r));
            a.fullyDead = true; 
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { ISO_SCALE_Y } from "../../../constants";
import { HexLayout } from "../../../types";

/**
 * 核心六邊形幾何真理 (Single Source of Truth) - V3 TA Optimized
 * 確保所有視覺組件（地形、UI、VFX）共享同一套頂點邏輯
 */
export const HexGeometry = {

    /**
     * 獲取標準化頂點
     * @param radius 半徑
     * @param applyIso 是否應用 2.5D 壓扁
     * @param layout 佈局模式 (FLAT | POINTY)
     */
    getVertices(radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT'): {x: number, y: number}[] {
        const vertices = [];
        // FLAT: 頂部平坦, 起始 0 度 | POINTY: 頂部尖銳, 起始 30 度
        const baseStartAngle = layout === 'FLAT' ? 0 : Math.PI / 6;
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = baseStartAngle + i * Math.PI / 3;
            vertices.push({ 
                x: Math.cos(angle) * radius, 
                y: Math.sin(angle) * radius * scaleY 
            });
        }
        return vertices;
    },

    /**
     * 在 Context 上描繪標準路徑
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * 向量旋轉繪製 - 用於魔法陣與奧義效果
     * 確保旋轉是在投影後的視覺空間中正確進行
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        const cosR = Math.cos(rotation);
        const sinR = Math.sin(rotation);

        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const vx = verts[i].x;
            const vy = verts[i].y;
            // 視覺空間旋轉矩陣
            const rx = vx * cosR - vy * sinR;
            const ry = vx * sinR + vy * cosR;

            if (i === 0) ctx.moveTo(x + rx, y + ry);
            else ctx.lineTo(x + rx, y + ry);
        }
        ctx.closePath();
    }
};

import { Particle } from "./state";
import { PHYSICS } from "../../../constants";

const DEFAULT_GRAVITY = 2500; 

/**
 * 高階美術 TA 物理引擎 - 地形感應版
 * 解決粒子掉落「怪怪的」問題，確保與地圖標高完美互動
 */
export class VFXPhysics {

    public static update(p: Particle, dt: number, getTerrainHeight?: (x: number, y: number) => number) {
        // 1. 基本位移運算
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.rotation += p.vRotation * dt;

        // 2. 地形感應 logic
        const isPhysical = ['DEBRIS', 'SHARD', 'SPRITE', 'ROCK', 'CHIP', 'RUBBLE'].includes(p.type);

        // 獲取當前粒子下方的「邏輯地面高度」
        const currentGroundH = getTerrainHeight ? getTerrainHeight(p.x, p.y) : 0;

        if (isPhysical) {
            // 應用重力 (Z 軸下墜)
            const g = p.gravity !== undefined ? p.gravity : DEFAULT_GRAVITY;
            p.vz -= g * dt;
            p.z += p.vz * dt;

            // 3. 碰撞檢測 (精確到地塊表面)
            // 我們允許粒子稍微滲透 1-2px 以避免 z-fighting
            const floorLevel = currentGroundH + 2;

            if (p.z < floorLevel) {
                // 粒子撞擊地面
                p.z = floorLevel;

                // 彈跳係數
                if (Math.abs(p.vz) > 120) {
                    p.vz = -p.vz * 0.45; // 吸收一半能量反彈
                    p.vx *= 0.7;         // 水平摩擦
                    p.vy *= 0.7;
                    p.vRotation *= 0.6;
                } else {
                    // 停止狀態 (Resting)
                    p.vz = 0;
                    p.vx *= 0.2;
                    p.vy *= 0.2;
                    p.vRotation = 0;
                }
            }
        } else {
            // 大氣粒子 (煙霧、火花、光塵)
            p.z += p.vz * dt;

            // 阻力與隨機漂浮感
            if (p.drag !== undefined) {
                const f = 1 - p.drag;
                p.vx *= f; p.vy *= f; p.vz *= f;
            } else {
                // 預設漂浮阻力
                p.vx *= 0.94;
                p.vy *= 0.94;
                p.vz *= 0.94;
            }

            // 非物理粒子不需要嚴格碰撞，但在地面下時應緩緩浮起
            if (p.z < currentGroundH) {
                p.z += (currentGroundH - p.z) * 0.1;
            }
        }

        // 4. 更新歷史標高，防止跨越邊緣時產生瞬間位移抖動
        p.lastGroundHeight = currentGroundH;
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

export const ProceduralPainter = {

    /**
     * 核心繪製分流
     */
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        // 1. 基於幾何真理的形狀 (奧義、光束、魔法陣)
        if (['HEX_BEAM', 'GIANT_HEX', 'MAGIC_CIRCLE'].includes(p.type)) {
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                this.drawGiantHex(ctx, p, rot, layout);
            } else if (p.type === 'MAGIC_CIRCLE') {
                this.drawMagicCircle(ctx, p, rot, layout);
            } else {
                this.drawStandardHexVfx(ctx, p, rot, progress, layout);
            }
        }
        // 2. 3D 體積投影 (光柱、領域、護盾)
        else if (p.type === 'PILLAR') {
            this.drawVolumetricPillar(ctx, p, progress);
        }
        else if (p.type === 'DOMAIN') {
            this.drawDomainField(ctx, p, progress, layout);
        }

        ctx.restore();
    },

    drawGiantHex(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = p.color; 
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 4;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        ctx.fillStyle = 'rgba(255,255,255,0.2)';
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, -rot * 1.5, true, layout);
        ctx.fill();
    },

    drawMagicCircle(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 10;

        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        ctx.lineWidth = 1;
        ctx.shadowBlur = 0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.7, -rot * 2, true, layout);
        ctx.stroke();
    },

    drawStandardHexVfx(ctx: CanvasRenderingContext2D, p: Particle, rot: number, progress: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.fillStyle = p.color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.globalAlpha = 1 - progress;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.9, rot, true, layout);
        ctx.stroke();
    },

    drawVolumetricPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
        const def = rawDef as PillarVisualDef;
        const h = p.height || def.height || 1200; 
        const width = p.size * (1 - progress * 0.5) * (def.widthScale || 1.0);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        const grad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
        grad.addColorStop(0, p.color); 
        grad.addColorStop(0.5, '#ffffff'); 
        grad.addColorStop(1, p.color); 

        ctx.fillStyle = grad;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.fillRect(-width/2, -h, width, h);
    },

    drawDomainField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, layout: HexLayout) {
        const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 
        const h = p.style === 'DOMAIN_SHIELD' ? 120 : 40;
        const opacity = 0.4 * (1 - progress);
        VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
    }
};

import { GameEvent } from "../../../../types";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../camera/CameraSystem";
import { Point3D } from "../EventVFXMapper";
import { VFX_REGISTRY } from "../../../../data/vfx/VFXRegistry";

/**
 * 戰鬥視覺處理器 (TA 優化版)
 * 確保所有擊中特效的「地面座標」解析正確，以支持物理碰撞
 */
export class CombatVFXHandler {

    public static handle(event: GameEvent, vfx: VFXSystem, camera: CameraSystem, target: Point3D, groundZ: number) {

        // 1. 直接傷害特效 (無投射物)
        if (event.type === 'DAMAGE') {
            if (!event.skill?.projectileSpeed) {
                this.playImpact(event, vfx, target, groundZ);
            }
            return;
        }

        // 2. 投射物命中心
        if (event.type === 'PROJECTILE_HIT') {
            if (event.skill?.type !== 'AOE') {
                this.playImpact(event, vfx, target, groundZ);
                camera.addTrauma(0.08); // 輕微震動
            } else {
                // AOE 接觸點僅播放火花
                vfx.playEffect('FX_HIT_GENERIC', event.pos.x, event.pos.y, groundZ + 5, event.skill?.color, groundZ);
            }
            return;
        }

        // 3. AOE 範圍爆發
        if (event.type === 'IMPACT_AOE') {
            // 確保 AOE 的地面基準點是絕對的
            this.playImpact(event, vfx, {x: event.pos.x, y: event.pos.y, z: groundZ}, groundZ);
            camera.addTrauma(0.25);
            return;
        }
    }

    private static playImpact(event: GameEvent, vfx: VFXSystem, target: Point3D, groundZ: number) {
        const skill = event.skill;
        const color = event.color || '#fff';

        let effectId = 'FX_HIT_GENERIC';
        if (skill && skill.visualHitEffect && VFX_REGISTRY[skill.visualHitEffect]) {
            effectId = skill.visualHitEffect;
        }

        // 重要：傳入精確的 groundZ，讓粒子引擎知道何時觸發彈跳
        vfx.playEffect(effectId, target.x, target.y, target.z, color, groundZ);
    }
}

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    // Stats
    public hp: number = 100;
    public maxHp: number = 100;
    public shield: number = 0; 
    public maxShield: number = 0; 
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0; 
    public moveSpeedMult: number = 1.0; 
    public jump: number = 1; 
    public weight: number = 1; 
    public movementType: MovementType = MovementType.GROUND;

    // Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0; 
    public curCDs: number[] = [0, 0, 0];

    // State / AI
    public isMoving: boolean = false;
    public path: Hex[] = []; 
    public trajectory: Hex[] = []; 
    public moveProgress: number = 0;
    public facing: number = 1; 
    public target: Agent | null = null;
    public targetHex: Hex | null = null; 
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    // Visual History (For Flight Trails)
    // Stores {x, y, z} tuples of the last N frames
    public trailHistory: {x: number, y: number, z: number}[] = [];

    // Status Effects
    public stunTimer: number = 0;
    public stunMax: number = 0; 

    public banishTimer: number = 0;
    public banishMax: number = 0; 

    public silenceTimer: number = 0;
    public silenceMax: number = 0; 

    public banished: boolean = false;

    // NEW STATUSES
    public rootTimer: number = 0;
    public fearTimer: number = 0;
    public tauntTimer: number = 0;
    public blindTimer: number = 0;
    public tauntTargetId: string | null = null; 

    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    // Diminishing Returns (DR) System
    public drStacks: Record<string, number> = {}; 
    public drTimers: Record<string, number> = {}; 

    // Visual State
    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    // Lifecycle
    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public hitFlashTimer: number = 0;

    // Physics
    public physics = { 
        x: 0, y: 0, z: 0,          
        vx: 0, vy: 0, vz: 0,       
        angle: 0, vAngle: 0   
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR; 
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    setAnim(state: AnimState) {
        if (this.animState !== state && this.animState !== AnimState.DEAD) {
            this.animState = state;
        }
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.shield = 0;
        this.maxShield = 0;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0; 
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.stunMax = 0;
        this.banishTimer = 0;
        this.banishMax = 0;
        this.silenceTimer = 0;
        this.silenceMax = 0;
        this.rootTimer = 0;
        this.fearTimer = 0;
        this.tauntTimer = 0;
        this.blindTimer = 0;
        this.tauntTargetId = null;

        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        // Reset DR
        this.drStacks = {};
        this.drTimers = {};

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5; 

        this.target = null;
        this.targetHex = null;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
        this.trailHistory = [];
    }
}

import { Agent, GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { MovementType } from "../../../types";

const STACKING_RESOLUTION_FORCE = 5;
const TRAIL_HISTORY_LENGTH = 15;

export class MotionEngine {

    public static updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // 1. Progress Calculation
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        // Clamp
        if (a.moveProgress > 1) a.moveProgress = 1;

        // 2. Coordinate Interpolation
        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        // 3. Facing Logic
        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        // 4. Easing Function (Sine In-Out for smooth motion)
        // t goes from 0 to 1.
        // -0.5 * (Math.cos(Math.PI * t) - 1)
        const t = a.moveProgress;
        const easedT = -0.5 * (Math.cos(Math.PI * t) - 1);

        // 5. Apply Position
        a.px = HexUtils.lerp(c.x, n.x, easedT);
        a.py = HexUtils.lerp(c.y, n.y, easedT);

        // 6. Record Trail History (For VFX)
        // We record PHYSICAL WORLD POSITION (including Z)
        // Only if flying or explicitly requested
        if (a.movementType === MovementType.FLYING && a.hp > 0) {
            // Push current state
            a.trailHistory.push({
                x: a.px,
                y: a.py,
                z: a.physics.z
            });
            // Trim
            if (a.trailHistory.length > TRAIL_HISTORY_LENGTH) {
                a.trailHistory.shift();
            }
        } else {
            // Clear history if not flying to save memory/prevent glitches
            if (a.trailHistory.length > 0) a.trailHistory = [];
        }

        // 7. Completion Check
        if (a.moveProgress >= 1) {
            this.commitMove(a, nextHex.q, nextHex.r, engine);
        }
    }

    private static commitMove(a: Agent, q: number, r: number, engine: GameEngine) {
        // Update Grid Registration
        engine.updateAgentPosition(a, q, r);

        // If it's a long distance move, log it, otherwise it's just spam
        // engine.log(a, 'MOVE', '移動', `(${q},${r})`, '抵達目的地');

        a.isMoving = false;
        a.moveSpeedMult = 1.0; // Reset speed after step completes
        a.moveProgress = 0;

        // Physics Stabilization: 
        if (a.movementType === MovementType.GROUND) {
            a.physics.vx *= 0.1;
            a.physics.vy *= 0.1;
        }

        // Visual Nudge
        a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
    }
}

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * High-Level Map Topology Generator
 * Guarantees a connected battleground using Basin-and-Step logic.
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        engine.mapConfig.w = 10; 
        engine.mapConfig.h = 10; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        // 1. Generate Base Basin Geometry
        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = `${q},${r}`;
                system.registerTile(q, r);

                const distToCenter = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const normalizedDist = distToCenter / Math.sqrt(centerQ**2 + centerR**2);

                // Base height follows a parabolic basin curve
                let tier = Math.floor(normalizedDist * 4.5);

                // Add organic noise variation
                const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8) * 1.5;
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier + Math.round(noise)));

                tiers.set(k, tier);
            }
        }

        // 2. Connectivity Calibration (Gradient Smoothing)
        for (let i = 0; i < 3; i++) { 
            tiers.forEach((tier, key) => {
                const [q, r] = key.split(',').map(Number);
                const neighbors = HexUtils.neighbors({q, r});
                neighbors.forEach(n => {
                    const nk = HexUtils.key(n);
                    if (tiers.has(nk)) {
                        const nTier = tiers.get(nk)!;
                        if (tier - nTier > 2) {
                            tiers.set(key, nTier + 2);
                        }
                    }
                });
            });
        }

        // 3. Apply to System
        tiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, centerQ, centerR);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, cq: number, cr: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';

        system.getMapKeys().forEach((key) => {
            const hPx = system.getHeightByKey(key);
            const tier = hPx / BLOCK_HEIGHT;
            const [q, r] = key.split(',').map(Number);

            // Check existing units
            if (engine.getAgentAt(q, r)) return;

            // Distance from center
            const dist = Math.sqrt((q - cq)**2 + (r - cr)**2);

            // --- TACTICAL PLACEMENT LOGIC ---
            // 1. Center Pit (Dist < 2.5): CLEAR. No obstacles in the death pit.
            if (dist < 2.5) return;

            // 2. Outer Rim (Tier >= 5): CLEAR. High ground should be walkable for range units, not blocked.
            if (tier >= 5) return;

            // 3. Mid Field (Tier 1-4): HIGH DENSITY. This is where cover matters.
            // Chance increases if it's "low ground cover" (Tier 1-2)
            let chance = 0.0;
            if (tier >= 1 && tier <= 3) chance = 0.35; // Prime obstruction zone
            if (tier === 4) chance = 0.15; // Sparse cover near top

            if (Math.random() < chance) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { Agent } from "../../../game";
import { Team } from "../../../../types";
import { UNIT_SCALE, UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET } from "../../../../constants";
import { FACTION_VISUALS } from "../../../../data/vfx/faction_visuals";

// How high the trail connects to the unit (Engines)
const ENGINE_HEIGHT_OFFSET = 30; 

export const UnitFlightPainter = {

    // NO LONGER USED: The old anchor line is replaced by the ribbon
    drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
        // Deprecated visual style. Kept empty to satisfy interface if needed, or just removed.
    },

    drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        // This is called within the UnitBodyPainter's transformed context (Body Center)
        // We don't want to draw world-space trails here.
        // We only draw local engine glows.

        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;

        ctx.save();
        ctx.translate(0, 15); // Below body

        // Engine Glows (Oscillating)
        const pulse = 0.8 + Math.sin(t * 20) * 0.2;

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        // Left Engine
        ctx.beginPath(); ctx.arc(-12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();
        // Right Engine
        ctx.beginPath(); ctx.arc(12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    /**
     * Called from UnitShadowPainter or a dedicated pass to draw World Space trails.
     * Uses the agent's trailHistory.
     */
    drawRibbonTrail(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.trailHistory.length < 2) return;

        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;

        // Visual Offset Calculation
        // The trail needs to align with the "Engines" visually.
        // Agent.px/py is Ground. 
        // Visual Y = GroundY - TerrainH - PhysZ - BodyOffset.
        // We stored {x, y, z} in history. x,y are Ground Px. z is PhysZ.
        // But we don't know terrain height at historical points easily without querying grid...
        // APPROXIMATION: Assume terrain doesn't change wildly under a flying unit or just use absolute Z if we tracked it.
        // For now, let's render the ribbon relative to the unit's current ground-plane projection to minimize jitter.

        ctx.save();

        // Ribbon Settings
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        // We define the path points in Screen Space (relative to canvas origin, assuming ctx is translated to 0,0 or handling offsets)
        // Actually, ShadowPainter calls this with context translated to (px, surfaceY). That's bad for trails.
        // We need this to be called in World Space. 
        // For this specific implementation, we assume the caller (UnitShadowPainter) resets transform or passes us the context in a way we can draw world coords.
        // BUT, UnitShadowPainter translates to `px, surfaceY`.
        // Let's invert that translation to get back to World 0,0 roughly, or ask the caller to handle it.
        // Hack: The trail is short. We can draw it relative to current pos.

        // Better: We just draw line segments.

        // Let's create a local path from the history points relative to CURRENT position.
        const currentPx = agent.px;
        const currentPy = agent.py; // Ground Y

        // We need to construct the visual path.
        // Visual Y for a point = p.y - p.z (Simulated Visual Height) - BodyOffset
        // Note: This ignores terrain height changes under the trail, making it look like it flies "flat" relative to ground plane.
        // This is acceptable for a "Hover" tank.

        // Build vertices
        const points: {x: number, y: number}[] = [];

        // Add history
        for (const p of agent.trailHistory) {
            // Visual Y = GroundY - JumpHeight - Offset
            const vy = p.y - p.z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET + 15; // +15 to lower it to engine level
            // We need coordinates relative to CURRENT (px, surfaceY) if we are inside a translated context.
            // However, `UnitShadowPainter` translates to (px, surfaceY). 
            // So relative X = p.x - currentPx.
            // Relative Y = vy - surfaceY.

            // Wait, surfaceY includes terrain height.
            // Let's just assume we draw in World Space and the caller resets transform.
            // If the caller (ShadowPainter) is translated, we must Untranslate.

            points.push({ x: p.x, y: vy });
        }

        // Add current pos
        const currVy = currentPy - agent.physics.z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET + 15;
        points.push({ x: currentPx, y: currVy });

        // Draw The Ribbon
        // To handle the context transform, we rely on the fact that we subtract the current position
        // so we are drawing offsets relative to the agent.

        if (points.length < 2) { ctx.restore(); return; }

        ctx.beginPath();

        // Start from oldest (tail)
        const tail = points[0];
        const relTailX = tail.x - currentPx;
        // Ideally we'd need the terrain height at tail to be perfect, but let's ignore terrain delta for the trail for now.
        // It produces a smooth "air" trail.
        // The Y coordinate in points[] is already "Visual Y ignoring terrain".
        // The Context is at "Visual Surface Y".
        // This is tricky.
        // Let's Just Draw simple lines relative to screen X/Y.

        // Correct Approach:
        // Pass a flag to ShadowPainter to NOT translate for this call, or use setTransform.
        // But ShadowPainter is complex.
        // Let's calculate relative offsets.

        // We will assume the trail exists in a "flat plane" relative to the unit's current ground.

        for (let i = 0; i < points.length; i++) {
            const p = points[i];
            const dx = p.x - currentPx;
            const dy = p.y - currVy; // Relative to current visual engine height

            // The context is at (px, surfaceY).
            // We want to draw at (px + dx, currVy + dy).
            // currVy is roughly (surfaceY - bodyOffset - hover).
            // So visual Y offset = (currVy + dy) - surfaceY.

            // Simplification: just draw dx, dy relative to a calculated anchor.
            // Anchor = (0, currVy - surfaceY) inside the translated context.

            if (i === 0) ctx.moveTo(dx, dy + (currVy - arguments[3])); // arguments[3] is hacky.
            // Let's just use the passed in agent data.
            // Current visual Y in context 0,0 is "Surface".
            // Engine is at: -agent.physics.z - BODY_OFFSET - HOVER + 15.

            const localEngineY = -agent.physics.z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET + 15;

            if (i === 0) ctx.moveTo(dx, localEngineY + dy);
            else ctx.lineTo(dx, localEngineY + dy);
        }

        ctx.strokeStyle = color;
        ctx.lineWidth = 4 * UNIT_SCALE;
        ctx.globalAlpha = 0.4;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.stroke();

        // Inner Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1 * UNIT_SCALE;
        ctx.globalAlpha = 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    }
};

import { UltContext, Point3D } from "./UltTypes";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

export class UltSequencer {
    private ctx: UltContext;

    constructor(ctx: UltContext) {
        this.ctx = ctx;
    }

    public get target(): Point3D { return this.ctx.target; }
    public get source(): Point3D | undefined { return this.ctx.sourcePos; }

    public wait(ms: number, fn: () => void) {
        setTimeout(() => fn(), ms);
    }

    public shake(amount: number, delay: number = 0) {
        this.wait(delay, () => {
            this.ctx.camera.addTrauma(amount);
        });
    }

    public effect(id: string, pos: Point3D, color?: string, delay: number = 0) {
        this.wait(delay, () => {
            // Passthrough to VFX System which handles the 3D-to-2D projection internally
            this.ctx.vfx.playEffect(id, pos.x, pos.y, pos.z, color);
        });
    }

    public beam(style: string, start: Point3D, end: Point3D, color: string, duration: number = 0.5, delay: number = 0) {
        this.wait(delay, () => {
            this.ctx.vfx.playBeam(style, start, end, color, duration);
        });
    }

    public gridImpact(teamColor: string, delay: number = 0) {
        const id = teamColor === THEME_IMPERIAL.primary ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED';
        // Impact is always at ground level of the target
        this.effect(id, this.target, teamColor, delay);
    }

    public heavenFall(height: number, color: string, style: 'GIANT_HEX' | 'ROCK' | 'METEOR', impactVfx: string, impactColor: string) {
        // 1. Falling Object (Standardized Logic)
        const p = this.ctx.vfx.state.getParticle();

        // Start high up (z + height)
        p.x = this.target.x; 
        p.y = this.target.y; 
        p.z = this.target.z + height;

        p.color = color;
        p.size = style === 'GIANT_HEX' ? 180 : (style === 'METEOR' ? 120 : 80);

        // Calculate physics to hit exactly at target Z
        const speed = 1600; 
        const duration = height / speed;

        p.vz = -speed;
        p.life = duration; 
        p.maxLife = duration;
        p.type = (style === 'METEOR' ? 'ROCK' : style) as any;
        p.vRotation = 15;
        p.killAtTarget = 100; // Kill when close to target (sq dist)
        p.targetX = this.target.x;
        p.targetY = this.target.y;

        this.ctx.vfx.state.particles.push(p);

        // 2. Ground Indicator (Projected Ring)
        const ring = this.ctx.vfx.state.getParticle();
        ring.x = this.target.x; ring.y = this.target.y; ring.z = this.target.z + 5;
        ring.life = duration; ring.maxLife = duration;
        ring.color = color; ring.size = p.size * 2.5;
        ring.type = 'RING';
        this.ctx.vfx.state.particles.push(ring);

        // 3. Impact Trigger
        this.wait(duration * 1000, () => {
            this.ctx.camera.addTrauma(1.0); 
            this.ctx.vfx.playEffect(impactVfx, this.target.x, this.target.y, this.target.z, impactColor);

            // Debris
            const cracks = this.ctx.vfx.state.getParticle();
            cracks.x = this.target.x; cracks.y = this.target.y; cracks.z = this.target.z + 2;
            cracks.life = 3.0; cracks.maxLife = 3.0;
            cracks.color = impactColor; cracks.size = p.size * 2.0;
            cracks.type = 'CRACKS';
            this.ctx.vfx.state.particles.push(cracks);
        });
    }
}

