export const COVENANT_VFX: Record<string, VFXAsset> = {

    // --- ULTIMATES (RED / CHAOS / FIRE) ---

    'FX_ULT_RED_GUILLOTINE_IMPACT': {
        id: 'FX_ULT_RED_GUILLOTINE_IMPACT',
