import { UltContext, Point3D } from "./UltTypes";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

export class UltSequencer {
    private ctx: UltContext;

    constructor(ctx: UltContext) {
        this.ctx = ctx;
    }

    public get target(): Point3D { return this.ctx.target; }
    public get source(): Point3D | undefined { return this.ctx.sourcePos; }

    public wait(ms: number, fn: () => void) {
        setTimeout(() => fn(), ms);
    }

    public shake(amount: number, delay: number = 0) {
        this.wait(delay, () => {
            this.ctx.camera.addTrauma(amount);
        });
    }

    public effect(id: string, pos: Point3D, color?: string, delay: number = 0) {
        this.wait(delay, () => {
            // Passthrough to VFX System which handles the 3D-to-2D projection internally
            this.ctx.vfx.playEffect(id, pos.x, pos.y, pos.z, color);
        });
    }

    public beam(style: string, start: Point3D, end: Point3D, color: string, duration: number = 0.5, delay: number = 0) {
        this.wait(delay, () => {
            this.ctx.vfx.playBeam(style, start, end, color, duration);
        });
    }

    public gridImpact(teamColor: string, delay: number = 0) {
        const id = teamColor === THEME_IMPERIAL.primary ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED';
        // Impact is always at ground level of the target
        this.effect(id, this.target, teamColor, delay);
    }

    public heavenFall(height: number, color: string, style: 'GIANT_HEX' | 'ROCK' | 'METEOR', impactVfx: string, impactColor: string) {
        // 1. Falling Object (Standardized Logic)
        const p = this.ctx.vfx.state.getParticle();

        // Start high up (z + height)
        p.x = this.target.x; 
        p.y = this.target.y; 
        p.z = this.target.z + height;

        p.color = color;
        // Meteor (ROCK) needs to be huge
        p.size = style === 'METEOR' ? 150 : (style === 'GIANT_HEX' ? 180 : 80);

        // Calculate physics to hit exactly at target Z
        const speed = 1600; 
        const duration = height / speed;

        p.vz = -speed;
        p.life = duration; 
        p.maxLife = duration;

        // Map abstract style to concrete particle type
        p.type = style === 'METEOR' ? 'ROCK' : (style === 'GIANT_HEX' ? 'GIANT_HEX' : 'SHARD');

        p.vRotation = 15;
        p.killAtTarget = 100; // Kill when close to target (sq dist)
        p.targetX = this.target.x;
        p.targetY = this.target.y;

        this.ctx.vfx.state.particles.push(p);

        // 2. Ground Indicator (Projected Ring)
        const ring = this.ctx.vfx.state.getParticle();
        ring.x = this.target.x; ring.y = this.target.y; ring.z = this.target.z + 5;
        ring.life = duration; ring.maxLife = duration;
        ring.color = color; ring.size = p.size * 2.0; // Slightly smaller ring for impact focus
        ring.type = 'RING';
        this.ctx.vfx.state.particles.push(ring);

        // 3. Impact Trigger
        this.wait(duration * 1000, () => {
            this.ctx.camera.addTrauma(1.0); 
            this.ctx.vfx.playEffect(impactVfx, this.target.x, this.target.y, this.target.z, impactColor);

            // Debris
            const cracks = this.ctx.vfx.state.getParticle();
            cracks.x = this.target.x; cracks.y = this.target.y; cracks.z = this.target.z + 2;
            cracks.life = 3.0; cracks.maxLife = 3.0;
            cracks.color = impactColor; cracks.size = p.size * 2.0;
            cracks.type = 'CRACKS';
            this.ctx.vfx.state.particles.push(cracks);
        });
    }
}

import { useRef, useCallback } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT, HEX_SIZE } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = useCallback((width: number, height: number) => {
        if (!width || !height || width <= 0 || height <= 0) return;

        const mapConfig = engine.mapConfig;

        // 1. Calculate the Centroid of the PLAYABLE SURFACE
        // We iterate through all tiles to find the average X and Y of the *Top Face*.
        // This ignores the massive "pedestal" depth below the tile.
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let validTiles = 0;

        engine.map.getMapKeys().forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            // Visual Y of the top face is (GroundY - Height)
            const topY = p.y - h;

            if (p.x < minX) minX = p.x;
            if (p.x > maxX) maxX = p.x;
            if (topY < minY) minY = topY;
            if (topY > maxY) maxY = topY;

            validTiles++;
        });

        if (validTiles === 0) return;

        // Visual Center of the bounding box
        const visualCenterX = (minX + maxX) / 2;
        const visualCenterY = (minY + maxY) / 2;

        // 2. Layout Specific Adjustments
        // FLAT layout tends to have very tall pedestals at the bottom.
        // We shift the camera center DOWN (positive Y) to push the world UP on screen,
        // effectively cropping the bottom "void" space.
        let offsetY = 0;

        if (mapConfig.layout === 'FLAT') {
            // Shift target down by ~1.5 blocks to hide the base pillars
            offsetY = BLOCK_HEIGHT * 1.5; 
        } else {
            // Pointy layout is usually more centered, slight adjustment
            offsetY = BLOCK_HEIGHT * 0.5;
        }

        // 3. Cinematic Zoom Calculation
        // Fit the width of the content with some padding
        const mapWidth = maxX - minX;
        const mapHeight = maxY - minY; // Use visual top-face height

        // Add padding (approx 1 hex on sides)
        const paddedW = mapWidth + HEX_SIZE * 3;
        const paddedH = mapHeight + HEX_SIZE * 3;

        const zoomX = width / paddedW;
        const zoomY = height / paddedH;

        // Choose the tighter zoom, but clamp for sanity
        let targetZoom = Math.min(zoomX, zoomY);

        // Zoom Limits:
        // Min 0.7: Don't show too much void on huge maps
        // Max 1.3: Don't get too pixelated on small maps
        targetZoom = Math.max(0.7, Math.min(1.3, targetZoom));

        // 4. Apply
        camera.current.x = visualCenterX;
        camera.current.y = visualCenterY + offsetY;
        camera.current.zoom = targetZoom;

        engine.renderer?.camera.snapTo(camera.current.x, camera.current.y, camera.current.zoom);

    }, [engine.mapConfig, engine.mapVersion]);

    const pan = useCallback((dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;
        camera.current.x -= dx / camera.current.zoom;
        camera.current.y -= dy / camera.current.zoom;
    }, []);

    const zoom = useCallback((delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.4, Math.min(3.0, camera.current.zoom + delta));
        camera.current.zoom = newZoom;
    }, []);

    const getScreenCoords = useCallback((clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    }, []);

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom, 
        getScreenCoords
    };
};

