export const ImperialSupportUlts: Record<string, UltScriptFn> = {
    // 神聖干涉 (Intervention)
    'sb_u1': (ctx) => {
        const seq = new UltSequencer(ctx);
        // Instant massive shield pillar
        const p = ctx.vfx.state.getParticle();
        p.x = ctx.target.x; p.y = ctx.target.y; p.z = ctx.target.z;
        p.life = 4.0; p.maxLife = 4.0;
        p.color = '#fef3c7'; p.size = 180;
        p.type = 'PILLAR'; p.style = 'PILLAR_HOLY';
        ctx.vfx.state.particles.push(p);

        // Ground Seal
        const seal = ctx.vfx.state.getParticle();
        seal.x = ctx.target.x; seal.y = ctx.target.y; seal.z = ctx.target.z;
        seal.life = 4.0; seal.maxLife = 4.0;
        seal.color = '#fbbf24'; seal.size = 200;
        seal.type = 'MAGIC_CIRCLE';
        ctx.vfx.state.particles.push(seal);
    },

    // 復活之光 (Resurrection)
    'sb_u2': (ctx) => {
        const seq = new UltSequencer(ctx);

        // 1. Central Beam
        seq.beam('TELEPORT_PILLAR', 
            {x: ctx.target.x, y: ctx.target.y, z: ctx.target.z + 1200},
            ctx.target,
            '#86efac', 1.0, 0
        );

        // 2. Rising Spirits (Procedural)
        for(let i=0; i<15; i++) {
            const p = ctx.vfx.state.getParticle();
            const angle = Math.random() * Math.PI * 2;
            const r = Math.random() * 300;
            p.x = ctx.target.x + Math.cos(angle)*r; 
            p.y = ctx.target.y + Math.sin(angle)*r; 
            p.z = ctx.target.z;
            p.vz = 150 + Math.random() * 200; 
            p.life = 2.5; p.maxLife = 2.5; 
            p.color = '#bbf7d0'; p.size = 12; p.type = 'GLOW';
            p.delay = i * 0.1;
            ctx.vfx.state.particles.push(p);
        }

        seq.effect('FX_ULT_BLUE_RESURRECTION', ctx.target, '#86efac', 0);
        seq.shake(0.2, 0);
    },

    // 英勇讚美詩 (Hymn)
    'sb_u3': (ctx) => {
        const seq = new UltSequencer(ctx);
        // Expanding rings
        for(let i=0; i<3; i++) {
            const p = ctx.vfx.state.getParticle();
            p.x = ctx.target.x; p.y = ctx.target.y; p.z = ctx.target.z + 10;
            p.life = 2.0; p.maxLife = 2.0;
            p.color = '#60a5fa'; p.size = 200 + i*150;
            p.type = 'RING';
            p.delay = i * 0.4;
            ctx.vfx.state.particles.push(p);
        }
        // Buff Particles
        seq.effect('FX_HIT_BLUE_HOLY', ctx.target, '#fff', 0);
    },

    // 神之怒 (Wrath)
    'sb_u4': (ctx) => {
        const seq = new UltSequencer(ctx);
        seq.heavenFall(1200, '#fcd34d', 'METEOR', 'FX_HIT_BLUE_HOLY', '#f59e0b');
    },

    // 寧靜之雨 (Rain)
    'sb_u5': (ctx) => {
        const seq = new UltSequencer(ctx);

        // 1. Grid Overlay (Zone)
        const grid = ctx.vfx.state.getParticle();
        grid.x = ctx.target.x; grid.y = ctx.target.y; grid.z = ctx.target.z;
        grid.life = 5.0; grid.maxLife = 5.0;
        grid.color = '#86efac'; grid.size = 450;
        grid.type = 'GRID_FIELD'; grid.style = 'GRID_TECH_BLUE';
        ctx.vfx.state.particles.push(grid);

        // 2. Rain Drops (Beams falling)
        for(let i=0; i<40; i++) {
            const r = Math.random() * 400;
            const a = Math.random() * Math.PI * 2;
            const px = ctx.target.x + Math.cos(a)*r;
            const py = ctx.target.y + Math.sin(a)*r;

            // Random start time
            const delay = i * 0.1;

            // Drop logic handled by particle type if we had 'RAIN', but here we use manual beams
            // Since beams are instant, we use a timeout or delay
            seq.wait(delay * 1000, () => {
                const dropH = 800;
                seq.beam('GENERIC_BEAM', 
                    { x: px, y: py, z: ctx.target.z + dropH },
                    { x: px, y: py, z: ctx.target.z },
                    '#dcfce7', 0.15
                );
                // Splash
                seq.effect('FX_HIT_BLUE_ARCANE', {x:px, y:py, z:ctx.target.z}, '#86efac');
            });
        }
    }
};

