import { Role, Team, HexLayout } from "../types";
import { PALETTE } from "../constants";
import { UnitFactory } from "./graphics/UnitFactory";
import { EnvironmentFactory } from "./graphics/EnvironmentFactory";

const cache: Map<string, any> = new Map();

export interface UnitAssets {
    base: HTMLCanvasElement; // Pre-rendered base
    icon: HTMLCanvasElement;   // Pre-rendered class icon
    color: string;           // Glow color
}

// ==========================================
// Sprite Manager (Cache & Facade)
// ==========================================
export const SpriteManager = {
    getUnitImages(role: Role, team: Team): UnitAssets {
        // Updated keys to force refresh with new designs
        const keyBase = `TOKEN_BASE_${team}_V3`; 
        let base = cache.get(keyBase);
        if (!base) {
            base = UnitFactory.generateTokenBase(team);
            cache.set(keyBase, base);
        }

        const keyIcon = `ROLE_ICON_${role}_${team}_V3`;
        let icon = cache.get(keyIcon);
        if (!icon) {
            icon = UnitFactory.generateRoleIcon(role, team);
            cache.set(keyIcon, icon);
        }

        return {
            base: base,
            icon: icon,
            color: PALETTE.TEAMS[team].glow
        };
    },

    getObstacleSprite(styleKey: string, layout: HexLayout): HTMLCanvasElement {
        // Cache Key now includes Layout to support switching modes
        const key = `OBSTACLE_${styleKey}_${layout}`;
        if (cache.has(key)) return cache.get(key)!;

        const canvas = EnvironmentFactory.generateObstacle(styleKey, layout);
        cache.set(key, canvas);
        return canvas;
    },

    getSpecialModel(type: 'SHEEP' | 'ICE'): HTMLCanvasElement {
        const key = `MODEL_${type}`;
        if (cache.has(key)) return cache.get(key)!;

        let canvas;
        if (type === 'SHEEP') {
            canvas = UnitFactory.generateSheep();
        } else {
            // Ice block assumes default layout for simplicity, or we could update this too
            canvas = EnvironmentFactory.generateIceBlock('FLAT');
        }

        cache.set(key, canvas);
        return canvas;
    }
};

import { OBSTACLE_STYLES, HEX_SIZE, BASE_HEIGHT } from "../../constants";
import { createCanvas } from "./CanvasUtils";
import { HexGeometry } from "./utils/HexGeometry"; 
import { HexLayout } from "../../types";

// --- STRICT ALIGNMENT CONSTANTS ---
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  
export const ENV_ANCHOR_Y = 140; 

export const EnvironmentFactory = {

    generateObstacle(styleKey: string, layout: HexLayout): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // Setup Anchor: (0,0) is the CENTER of the hexagonal SURFACE on the ground
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        this.drawHexShadow(ctx, layout);

        // 2. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawIsoTree(ctx, style, layout);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawIsoCrystal(ctx, style, layout);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawIsoPillar(ctx, style, layout);
        } else {
            this.drawIsoWall(ctx, style, layout); // Default Wall/Sandstone
        }

        return canvas;
    },

    generateIceBlock(layout: HexLayout): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'];
        this.drawIsoCrystal(ctx, style, layout, 0.7);
        return canvas;
    },

    // =========================================================================================
    // 🏗️ GEOMETRY BUILDERS (Layout Aware)
    // =========================================================================================

    drawHexShadow(ctx: CanvasRenderingContext2D, layout: HexLayout) {
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        const r = HEX_SIZE * 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();
        ctx.restore();
    },

    drawIsoWall(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        const height = 55;
        const r = HEX_SIZE * 0.9; 
        const topY = -height;

        const verts = HexGeometry.getVertices(r, true, layout);

        // --- WALL FACES ---
        // Render faces based on visibility from "South" camera
        if (layout === 'FLAT') {
            // Flat Top: Visible faces are Bottom-Left(2-3), Bottom(1-2), Bottom-Right(0-1)
            // Indices: 0=Right, 1=BotRight, 2=BotLeft, 3=Left, 4=TopLeft, 5=TopRight
            // We draw from back to front or just the front ones.

            // Left Face (v3 -> v2)
            this.drawQuad(ctx, verts[3], verts[2], topY, style.dark);
            this.drawEdge(ctx, verts[3], verts[2], topY, style.highlight);

            // Front Face (v2 -> v1)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.main);

            // Right Face (v1 -> v0)
            this.drawQuad(ctx, verts[1], verts[0], topY, style.light);
            this.drawEdge(ctx, verts[1], verts[0], topY, style.highlight);

        } else {
            // Pointy Top: Visible faces are Bottom-Left(1-2) and Bottom-Right(0-1)
            // Indices: 0=BotRight, 1=BotTip, 2=BotLeft, 3=TopLeft, 4=TopTip, 5=TopRight

            // Left Face (v2 -> v1)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.sideDark || style.dark); // Use darker for side
            this.drawEdge(ctx, verts[2], verts[1], topY, style.highlight);

            // Right Face (v1 -> v0)
            this.drawQuad(ctx, verts[1], verts[0], topY, style.sideLight || style.main);
            this.drawEdge(ctx, verts[1], verts[0], topY, style.highlight);

            // Center Seam Highlight
            ctx.beginPath();
            ctx.moveTo(verts[1].x, verts[1].y);
            ctx.lineTo(verts[1].x, verts[1].y + topY);
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            ctx.stroke();
        }

        // --- TOP CAP ---
        ctx.save();
        ctx.translate(0, topY);

        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();

        // Inner Detail
        ctx.fillStyle = style.detail;
        ctx.beginPath(); ctx.arc(0, 0, r*0.4, 0, Math.PI*2); ctx.fill();

        // Rim
        ctx.strokeStyle = style.highlight;
        ctx.lineWidth = 1;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.stroke();

        ctx.restore();
    },

    drawIsoPillar(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        const height = 90;
        const r = HEX_SIZE * 0.7; // Thinner than tile
        const topY = -height;

        const verts = HexGeometry.getVertices(r, true, layout);

        if (layout === 'FLAT') {
            this.drawQuad(ctx, verts[3], verts[2], topY, style.dark);  // Left
            this.drawQuad(ctx, verts[2], verts[1], topY, style.main);  // Front
            this.drawQuad(ctx, verts[1], verts[0], topY, style.light); // Right
        } else {
            // Pointy Pillar (Diamond facing front)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.dark); // Left Face
            this.drawQuad(ctx, verts[1], verts[0], topY, style.main); // Right Face
        }

        // Rune / Sigil
        ctx.save();
        ctx.translate(0, topY / 2); // Center of pillar height
        ctx.strokeStyle = style.detail;
        ctx.lineWidth = 2;
        ctx.shadowColor = style.detail;
        ctx.shadowBlur = 5;

        if (layout === 'FLAT') {
            ctx.beginPath();
            ctx.moveTo(0, -15); ctx.lineTo(0, 15);
            ctx.moveTo(-5, 0); ctx.lineTo(5, 0);
            ctx.stroke();
        } else {
            // Draw on the corner spine
            ctx.beginPath();
            ctx.moveTo(0, -20); ctx.lineTo(0, 20);
            ctx.moveTo(0, -10); ctx.lineTo(verts[0].x * 0.3, -5); // Angled rune
            ctx.stroke();
        }
        ctx.restore();

        // Top Cap
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = '#000';
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();
        ctx.restore();
    },

    drawIsoTree(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        // Organic shape, but grounded in geometry
        const trunkW = 14;
        const trunkH = 20;

        ctx.fillStyle = '#3f2e1e';
        ctx.beginPath();
        // Simple trunk
        ctx.fillRect(-trunkW/2, -trunkH, trunkW, trunkH + 5); 

        const layers = 3;
        const baseWidth = layout === 'FLAT' ? 48 : 42; // Pointy trees slightly narrower?
        const layerHeight = 35;
        let currentY = -trunkH + 5;

        for (let i = 0; i < layers; i++) {
            const ratio = 1 - (i / layers);
            const width = baseWidth * (0.6 + ratio * 0.4);
            const height = layerHeight;

            ctx.beginPath();
            ctx.moveTo(0, currentY - height); // Top tip

            if (layout === 'FLAT') {
                // Wide Triangle
                ctx.lineTo(width/2, currentY);
                ctx.quadraticCurveTo(0, currentY + 8, -width/2, currentY);
            } else {
                // Sharper Triangle
                ctx.lineTo(width/2, currentY);
                ctx.lineTo(0, currentY + 5); // Pointy dip
                ctx.lineTo(-width/2, currentY);
            }

            ctx.closePath();

            const grad = ctx.createLinearGradient(0, currentY - height, 0, currentY);
            grad.addColorStop(0, style.highlight);
            grad.addColorStop(0.5, style.main);
            grad.addColorStop(1, style.dark);
            ctx.fillStyle = grad;
            ctx.fill();

            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 1;
            ctx.stroke();

            currentY -= (height * 0.7); // Overlap
        }
    },

    drawIsoCrystal(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout, alpha: number = 1.0) {
        const drawShard = (x: number, y: number, w: number, h: number, tilt: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(tilt);

            ctx.fillStyle = style.dark;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-w, -h * 0.2);
            ctx.lineTo(0, -h); 
            ctx.lineTo(w, -h * 0.3);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = style.light;
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(w, -h * 0.3);
            ctx.lineTo(0, -h);
            ctx.fill();

            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(0, -h);
            ctx.stroke();

            ctx.restore();
        };

        // Randomize slightly but keep centered
        if (layout === 'FLAT') {
            drawShard(-10, 5, 10, 50, -0.2);
            drawShard(10, 2, 12, 40, 0.2);
            drawShard(0, 8, 18, 70, 0); 
        } else {
            // Tighter cluster for pointy
            drawShard(0, 5, 15, 65, 0); 
            drawShard(-8, 0, 8, 40, -0.15);
            drawShard(8, 0, 8, 40, 0.15);
        }
    },

    // --- Helpers ---
    drawQuad(ctx: CanvasRenderingContext2D, vBottom: {x:number, y:number}, vNextBottom: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom.x, vBottom.y);
        ctx.lineTo(vNextBottom.x, vNextBottom.y);
        ctx.lineTo(vNextBottom.x, vNextBottom.y + topY);
        ctx.lineTo(vBottom.x, vBottom.y + topY);
        ctx.closePath();
        ctx.fill();
    },

    drawEdge(ctx: CanvasRenderingContext2D, vBottom: {x:number, y:number}, vNextBottom: {x:number, y:number}, topY: number, color: string) {
        ctx.strokeStyle = 'rgba(255,255,255,0.1)'; // Subtle edge
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(vBottom.x, vBottom.y);
        ctx.lineTo(vBottom.x, vBottom.y + topY);
        ctx.stroke();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // visualTopY = Vertical displacement (negative)
        const visualTopY = -height;

        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING (GEOMETRY AWARE) ---
        if (layout === 'FLAT') {
            // Flat Top Hexagon (0 deg start)
            // Visible faces from standard isometric angle: 
            // Bottom-Right (1-0), Bottom (2-1), Bottom-Left (3-2)
            // Indices: 0=Right, 1=BotRight, 2=BotLeft, 3=Left...

            // Draw order: Side to Front to Side (Back-to-Front painter's algo is handled by GridRenderStrategy sorting tiles)
            // Within a single tile, we just draw the visible faces.

            // South-East Face (1 -> 0)
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);

            // South Face (2 -> 1)
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);

            // South-West Face (3 -> 2)
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);

        } else {
            // Pointy Top Hexagon (30 deg start)
            // Visible faces: Bottom-Right (1-0), Bottom-Left (2-1)
            // Indices: 0=BotRight, 1=BotTip, 2=BotLeft, 3=TopLeft...

            // Right-Front Face (1 -> 0)
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);

            // Left-Front Face (2 -> 1)
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);

            // Front Corner Highlight (The "V" tip)
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(vertices[1].x, vertices[1].y);
            ctx.lineTo(vertices[1].x, vertices[1].y + visualTopY);
            ctx.stroke();
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.2;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    /**
     * Draws a vertical wall segment connecting a bottom edge to the top face.
     */
    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();

        // Start at bottom edge
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);

        // Go UP to top edge
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);

        // Base extension (The "Pedestal" depth below z=0)
        // We actually draw *down* from the "Base Y" (which is y) into the "Base Height"
        // But the arguments passed are (x, y) = Logic Ground.
        // topY is negative. 
        // We need to fill the BASE_HEIGHT area below the logical ground to prevent gaps.
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); // Close loop back to start

        ctx.closePath();
        ctx.fill();

        // Edge Definition
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y + topY); // Top corner
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT); // Bottom corner
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { SpriteManager } from "../../sprites";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 0; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            // Visual Ground Top Y = (BaseY - Height + Transition)
            const visualTopY = py - h + offset;
            const visualBaseY = py + offset;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Obstacles anchor to the visual top of the block
                op.ty = visualTopY - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            const zoneInfo = engine.zones.getZoneAt(q, r);

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene;
        const layout = engine.mapConfig.layout;

        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, visualTopY, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    break;
                case RenderOpType.OBSTACLE:
                    // Use the engine's current layout to fetch appropriate sprite
                    const sprite = SpriteManager.getObstacleSprite(op.ttype, layout);
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    break;
                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos, layout);
                        ctx.restore();
                    }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase, layout);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        else if (engine.winningTeam !== null) blurAmount = 1.0;

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { Role, Team, HexLayout } from "../types";
import { PALETTE } from "../constants";
import { UnitFactory } from "./graphics/UnitFactory";
import { EnvironmentFactory } from "./graphics/EnvironmentFactory";

const cache: Map<string, any> = new Map();

export interface UnitAssets {
    base: HTMLCanvasElement; // Pre-rendered base
    icon: HTMLCanvasElement;   // Pre-rendered class icon
    color: string;           // Glow color
}

// ==========================================
// Sprite Manager (Cache & Facade)
// ==========================================
export const SpriteManager = {
    getUnitImages(role: Role, team: Team): UnitAssets {
        // Updated keys to force refresh with new designs
        const keyBase = `TOKEN_BASE_${team}_V3`; 
        let base = cache.get(keyBase);
        if (!base) {
            base = UnitFactory.generateTokenBase(team);
            cache.set(keyBase, base);
        }

        const keyIcon = `ROLE_ICON_${role}_${team}_V3`;
        let icon = cache.get(keyIcon);
        if (!icon) {
            icon = UnitFactory.generateRoleIcon(role, team);
            cache.set(keyIcon, icon);
        }

        return {
            base: base,
            icon: icon,
            color: PALETTE.TEAMS[team].glow
        };
    },

    getObstacleSprite(styleKey: string, layout: HexLayout): HTMLCanvasElement {
        // Cache Key now includes Layout to support switching modes
        const key = `OBSTACLE_${styleKey}_${layout}`;
        if (cache.has(key)) return cache.get(key)!;

        const canvas = EnvironmentFactory.generateObstacle(styleKey, layout);
        cache.set(key, canvas);
        return canvas;
    },

    getSpecialModel(type: 'SHEEP' | 'ICE'): HTMLCanvasElement {
        const key = `MODEL_${type}`;
        if (cache.has(key)) return cache.get(key)!;

        let canvas;
        if (type === 'SHEEP') {
            canvas = UnitFactory.generateSheep();
        } else {
            // Ice block assumes default layout for simplicity, or we could update this too
            // For special models, we default to FLAT as they are organic shapes usually
            canvas = EnvironmentFactory.generateIceBlock('FLAT');
        }

        cache.set(key, canvas);
        return canvas;
    }
};

import { OBSTACLE_STYLES, HEX_SIZE, BASE_HEIGHT } from "../../constants";
import { createCanvas } from "./CanvasUtils";
import { HexGeometry } from "./utils/HexGeometry"; 
import { HexLayout } from "../../types";

// --- STRICT ALIGNMENT CONSTANTS ---
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  
export const ENV_ANCHOR_Y = 140; 

export const EnvironmentFactory = {

    generateObstacle(styleKey: string, layout: HexLayout): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // Setup Anchor: (0,0) is the CENTER of the hexagonal SURFACE on the ground
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        this.drawHexShadow(ctx, layout);

        // 2. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawIsoTree(ctx, style, layout);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawIsoCrystal(ctx, style, layout);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawIsoPillar(ctx, style, layout);
        } else {
            this.drawIsoWall(ctx, style, layout); // Default Wall/Sandstone
        }

        return canvas;
    },

    generateIceBlock(layout: HexLayout): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'];
        this.drawIsoCrystal(ctx, style, layout, 0.7);
        return canvas;
    },

    // =========================================================================================
    // 🏗️ GEOMETRY BUILDERS (Layout Aware)
    // =========================================================================================

    drawHexShadow(ctx: CanvasRenderingContext2D, layout: HexLayout) {
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        const r = HEX_SIZE * 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();
        ctx.restore();
    },

    drawIsoWall(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        const height = 55;
        const r = HEX_SIZE * 0.9; 
        const topY = -height;

        const verts = HexGeometry.getVertices(r, true, layout);

        // --- WALL FACES ---
        // Render faces based on visibility from "South" camera
        if (layout === 'FLAT') {
            // Flat Top: Visible faces are Bottom-Left(2-3), Bottom(1-2), Bottom-Right(0-1)
            // Indices: 0=Right, 1=BotRight, 2=BotLeft, 3=Left, 4=TopLeft, 5=TopRight
            // We draw from back to front or just the front ones.

            // Left Face (v3 -> v2)
            this.drawQuad(ctx, verts[3], verts[2], topY, style.dark);
            this.drawEdge(ctx, verts[3], verts[2], topY, style.highlight);

            // Front Face (v2 -> v1)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.main);

            // Right Face (v1 -> v0)
            this.drawQuad(ctx, verts[1], verts[0], topY, style.light);
            this.drawEdge(ctx, verts[1], verts[0], topY, style.highlight);

        } else {
            // Pointy Top: Visible faces are Bottom-Left(1-2) and Bottom-Right(0-1)
            // Indices: 0=BotRight, 1=BotTip, 2=BotLeft, 3=TopLeft, 4=TopTip, 5=TopRight

            // Left Face (v2 -> v1)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.sideDark || style.dark); // Use darker for side
            this.drawEdge(ctx, verts[2], verts[1], topY, style.highlight);

            // Right Face (v1 -> v0)
            this.drawQuad(ctx, verts[1], verts[0], topY, style.sideLight || style.main);
            this.drawEdge(ctx, verts[1], verts[0], topY, style.highlight);

            // Center Seam Highlight
            ctx.beginPath();
            ctx.moveTo(verts[1].x, verts[1].y);
            ctx.lineTo(verts[1].x, verts[1].y + topY);
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            ctx.stroke();
        }

        // --- TOP CAP ---
        ctx.save();
        ctx.translate(0, topY);

        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();

        // Inner Detail
        ctx.fillStyle = style.detail;
        ctx.beginPath(); ctx.arc(0, 0, r*0.4, 0, Math.PI*2); ctx.fill();

        // Rim
        ctx.strokeStyle = style.highlight;
        ctx.lineWidth = 1;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.stroke();

        ctx.restore();
    },

    drawIsoPillar(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        const height = 90;
        const r = HEX_SIZE * 0.7; // Thinner than tile
        const topY = -height;

        const verts = HexGeometry.getVertices(r, true, layout);

        if (layout === 'FLAT') {
            this.drawQuad(ctx, verts[3], verts[2], topY, style.dark);  // Left
            this.drawQuad(ctx, verts[2], verts[1], topY, style.main);  // Front
            this.drawQuad(ctx, verts[1], verts[0], topY, style.light); // Right
        } else {
            // Pointy Pillar (Diamond facing front)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.dark); // Left Face
            this.drawQuad(ctx, verts[1], verts[0], topY, style.main); // Right Face
        }

        // Rune / Sigil
        ctx.save();
        ctx.translate(0, topY / 2); // Center of pillar height
        ctx.strokeStyle = style.detail;
        ctx.lineWidth = 2;
        ctx.shadowColor = style.detail;
        ctx.shadowBlur = 5;

        if (layout === 'FLAT') {
            ctx.beginPath();
            ctx.moveTo(0, -15); ctx.lineTo(0, 15);
            ctx.moveTo(-5, 0); ctx.lineTo(5, 0);
            ctx.stroke();
        } else {
            // Draw on the corner spine
            ctx.beginPath();
            ctx.moveTo(0, -20); ctx.lineTo(0, 20);
            ctx.moveTo(0, -10); ctx.lineTo(verts[0].x * 0.3, -5); // Angled rune
            ctx.stroke();
        }
        ctx.restore();

        // Top Cap
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = '#000';
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();
        ctx.restore();
    },

    drawIsoTree(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        // Organic shape, but grounded in geometry
        const trunkW = 14;
        const trunkH = 20;

        ctx.fillStyle = '#3f2e1e';
        ctx.beginPath();
        // Simple trunk
        ctx.fillRect(-trunkW/2, -trunkH, trunkW, trunkH + 5); 

        const layers = 3;
        const baseWidth = layout === 'FLAT' ? 48 : 42; // Pointy trees slightly narrower?
        const layerHeight = 35;
        let currentY = -trunkH + 5;

        for (let i = 0; i < layers; i++) {
            const ratio = 1 - (i / layers);
            const width = baseWidth * (0.6 + ratio * 0.4);
            const height = layerHeight;

            ctx.beginPath();
            ctx.moveTo(0, currentY - height); // Top tip

            if (layout === 'FLAT') {
                // Wide Triangle
                ctx.lineTo(width/2, currentY);
                ctx.quadraticCurveTo(0, currentY + 8, -width/2, currentY);
            } else {
                // Sharper Triangle
                ctx.lineTo(width/2, currentY);
                ctx.lineTo(0, currentY + 5); // Pointy dip
                ctx.lineTo(-width/2, currentY);
            }

            ctx.closePath();

            const grad = ctx.createLinearGradient(0, currentY - height, 0, currentY);
            grad.addColorStop(0, style.highlight);
            grad.addColorStop(0.5, style.main);
            grad.addColorStop(1, style.dark);
            ctx.fillStyle = grad;
            ctx.fill();

            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 1;
            ctx.stroke();

            currentY -= (height * 0.7); // Overlap
        }
    },

    drawIsoCrystal(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout, alpha: number = 1.0) {
        const drawShard = (x: number, y: number, w: number, h: number, tilt: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(tilt);

            ctx.fillStyle = style.dark;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-w, -h * 0.2);
            ctx.lineTo(0, -h); 
            ctx.lineTo(w, -h * 0.3);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = style.light;
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(w, -h * 0.3);
            ctx.lineTo(0, -h);
            ctx.fill();

            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(0, -h);
            ctx.stroke();

            ctx.restore();
        };

        // Randomize slightly but keep centered
        if (layout === 'FLAT') {
            drawShard(-10, 5, 10, 50, -0.2);
            drawShard(10, 2, 12, 40, 0.2);
            drawShard(0, 8, 18, 70, 0); 
        } else {
            // Tighter cluster for pointy
            drawShard(0, 5, 15, 65, 0); 
            drawShard(-8, 0, 8, 40, -0.15);
            drawShard(8, 0, 8, 40, 0.15);
        }
    },

    // --- Helpers ---
    drawQuad(ctx: CanvasRenderingContext2D, vBottom: {x:number, y:number}, vNextBottom: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom.x, vBottom.y);
        ctx.lineTo(vNextBottom.x, vNextBottom.y);
        ctx.lineTo(vNextBottom.x, vNextBottom.y + topY);
        ctx.lineTo(vBottom.x, vBottom.y + topY);
        ctx.closePath();
        ctx.fill();
    },

    drawEdge(ctx: CanvasRenderingContext2D, vBottom: {x:number, y:number}, vNextBottom: {x:number, y:number}, topY: number, color: string) {
        ctx.strokeStyle = 'rgba(255,255,255,0.1)'; // Subtle edge
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(vBottom.x, vBottom.y);
        ctx.lineTo(vBottom.x, vBottom.y + topY);
        ctx.stroke();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // visualTopY = Vertical displacement (negative)
        const visualTopY = -height;

        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING (GEOMETRY AWARE) ---
        if (layout === 'FLAT') {
            // Flat Top Hexagon (0 deg start)
            // Visible faces from standard isometric angle: 
            // Bottom-Right (1-0), Bottom (2-1), Bottom-Left (3-2)
            // Indices: 0=Right, 1=BotRight, 2=BotLeft, 3=Left...

            // Draw order: Side to Front to Side (Back-to-Front painter's algo is handled by GridRenderStrategy sorting tiles)
            // Within a single tile, we just draw the visible faces.

            // South-East Face (1 -> 0)
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);

            // South Face (2 -> 1)
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);

            // South-West Face (3 -> 2)
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);

        } else {
            // Pointy Top Hexagon (30 deg start)
            // Visible faces: Bottom-Right (1-0), Bottom-Left (2-1)
            // Indices: 0=BotRight, 1=BotTip, 2=BotLeft, 3=TopLeft...

            // Right-Front Face (1 -> 0)
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);

            // Left-Front Face (2 -> 1)
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);

            // Front Corner Highlight (The "V" tip)
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(vertices[1].x, vertices[1].y);
            ctx.lineTo(vertices[1].x, vertices[1].y + visualTopY);
            ctx.stroke();
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.2;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    /**
     * Draws a vertical wall segment connecting a bottom edge to the top face.
     */
    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();

        // Start at bottom edge
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);

        // Go UP to top edge
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);

        // Base extension (The "Pedestal" depth below z=0)
        // We actually draw *down* from the "Base Y" (which is y) into the "Base Height"
        // But the arguments passed are (x, y) = Logic Ground.
        // topY is negative. 
        // We need to fill the BASE_HEIGHT area below the logical ground to prevent gaps.
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); // Close loop back to start

        ctx.closePath();
        ctx.fill();

        // Edge Definition
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y + topY); // Top corner
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT); // Bottom corner
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { SpriteManager } from "../../sprites";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 0; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            // Visual Ground Top Y = (BaseY - Height + Transition)
            const visualTopY = py - h + offset;
            const visualBaseY = py + offset;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Obstacles anchor to the visual top of the block
                op.ty = visualTopY - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            const zoneInfo = engine.zones.getZoneAt(q, r);

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene;
        const layout = engine.mapConfig.layout;

        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, visualTopY, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    break;
                case RenderOpType.OBSTACLE:
                    // Use the engine's current layout to fetch appropriate sprite
                    const sprite = SpriteManager.getObstacleSprite(op.ttype, layout);
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    break;
                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos, layout);
                        ctx.restore();
                    }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase, layout);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        else if (engine.winningTeam !== null) blurAmount = 1.0;

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    // onWin removed - handled by EventBus in parent
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void; // New Prop
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
    onOpenLogs: () => void; // New Prop
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase, onOpenLogs 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE using Lazy Initialization.
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        // Link renderer to engine for camera control
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Render Handler (Memoized)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        // Increment progress if we are in a transition
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; // Assume 60fps delta for smoothness or use real dt
            // SPEED ADJUSTED: 0.8 multiplier = ~1.25s duration.
            // Very slow, deliberate movement to allow the Blur to sync perfectly.
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.8);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;

        // Access fresh hover state directly from ref during render loop
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr); // Apply High-DPI scale

            // Camera Transform
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); // Use simpler translation matching CameraSystem

            const sprite = SpriteManager.getObstacleSprite(type, engine.mapConfig.layout);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - God View Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">

                        {/* Winner Label */}
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>

                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>

                        {/* Actions */}
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>

                            <button 
                                onClick={onOpenLogs} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-slate-800/50 hover:bg-slate-700/50 border-white/10 text-cyan-400 shadow-md w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Log className="w-4 h-4 opacity-80 group-hover:scale-110 transition-transform" />
                                <span>戰鬥記錄 (Battle Logs)</span>
                            </button>

                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-white/5 hover:bg-white/10 border-white/10 text-slate-300 shadow-lg w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Restart className="w-4 h-4 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

