import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * 🗺️ TACTICAL MAP GENERATOR v2.0
 * Philosophy: "The Amphitheater"
 * 
 * Instead of a simple noise map, we generate terrain designed for an Isometric Camera.
 * 1. North (Top) is High Ground (The Stage Backdrop).
 * 2. Center is the Arena (Low Ground).
 * 3. South (Bottom) is the Audience View (Forced Low Ground to prevent occlusion).
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Slightly larger map to allow for the stage effect
        engine.mapConfig.w = 10; 
        engine.mapConfig.h = 10; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        // Center point for the "Arena"
        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        // Calculate max possible distance for normalization
        // In visual space, row index roughly correlates to Y.

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                // --- 1. VISUAL COORDINATE CALCULATION ---
                // Calculate a normalized "Screen Y" factor (0.0 = Top, 1.0 = Bottom)
                // This is an approximation based on the grid index sum, which works for Iso sorting.
                const visualRowIndex = r + (q * 0.5); // Skew slightly for Hex grid
                const maxVisualRow = H + (W * 0.5);
                const screenY = Math.min(1.0, Math.max(0.0, visualRowIndex / maxVisualRow));

                // --- 2. THE AMPHITHEATER SHAPE ---

                // Distance from center (The Pit)
                const dx = q - centerQ;
                const dy = r - centerR;
                const distSq = dx*dx + dy*dy;
                const dist = Math.sqrt(distSq);

                // Base Height: Increases as we go away from center (The Bowl)
                let rawHeight = dist * 1.2;

                // --- 3. THE FRUSTUM MASK (No High Ground at Bottom) ---
                // If screenY > 0.5 (Bottom half), apply heavy penalty.
                // At screenY = 1.0, penalty is max (height forced to 0).

                let visibilityMask = 1.0;
                if (screenY > 0.4) {
                    // Dramatic falloff curve
                    const t = (screenY - 0.4) / 0.6;
                    visibilityMask = 1.0 - Math.pow(t, 2); 
                }

                // Apply Mask
                let tier = rawHeight * visibilityMask;

                // --- 4. ORGANIC NOISE ---
                // Add Perlin-ish noise, but dampen it at the bottom to ensure clean sightlines
                const noise = (Math.sin(q * 0.7) + Math.cos(r * 0.6)) * 1.5;
                tier += noise * visibilityMask; // Only apply noise where height is allowed

                // --- 5. QUANTIZE ---
                // Clamp and floor to get integer tiers
                let finalTier = Math.floor(tier);

                // Safety clamp
                finalTier = Math.max(0, Math.min(MAX_TERRAIN_TIER, finalTier));

                // Special Rule: Center must be flat
                if (dist < 2.0) finalTier = 0;

                tiers.set(k, finalTier);
            }
        }

        // --- 6. SMOOTHING PASS ---
        // Smooth out spikes, but preserve the "Stage" structure
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = tier;
            let count = 1;

            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) {
                    sum += tiers.get(nk)!;
                    count++;
                }
            });

            const avg = Math.round(sum / count);
            smoothedTiers.set(key, avg);
        });

        // Write to System
        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';

        system.getMapKeys().forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const hPx = system.getHeightByKey(key);
            const tier = hPx / BLOCK_HEIGHT;

            // Check existing units
            if (engine.getAgentAt(q, r)) return;

            // --- VISUAL SAFETY CHECK ---
            // Calculate Screen Y again
            const visualRowIndex = r + (q * 0.5);
            const maxVisualRow = H + (W * 0.5);
            const screenY = visualRowIndex / maxVisualRow;

            // RULE 1: STRICTLY NO OBSTACLES IN FOREGROUND (Bottom 30%)
            // This ensures nothing blocks the view of the units.
            if (screenY > 0.7) return;

            // RULE 2: Obstacles prefer High Ground (The Backdrop)
            // Or "Mid-range" cover.

            let chance = 0.05; // Base low chance

            if (tier >= 3) {
                // High ground back-line cover
                chance = 0.4;
            } else if (tier >= 1 && screenY < 0.5) {
                // Mid-field cover, but only in the top half of the screen
                chance = 0.2;
            }

            if (Math.random() < chance) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

