import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * 🗺️ TACTICAL MAP GENERATOR v2.1 (Sparse & Clean)
 * Philosophy: "The Open Amphitheater"
 * 
 * Improvements:
 * 1. Foreground Clearance: No obstacles in the bottom 40% of the view.
 * 2. Center Arena: Strict "No-Build Zone" in the map center for combat.
 * 3. Clumping: Obstacles spawn in noise-based clusters, leaving clear lanes between them.
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Standard 10x10 map for balanced gameplay
        engine.mapConfig.w = 10; 
        engine.mapConfig.h = 10; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        // Center point for the "Arena"
        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                // --- 1. VISUAL COORDINATE CALCULATION ---
                // 0.0 = Top (North), 1.0 = Bottom (South)
                // Used for Frustum Culling height logic
                const visualRowIndex = r + (q * 0.5); 
                const maxVisualRow = H + (W * 0.5);
                const screenY = Math.min(1.0, Math.max(0.0, visualRowIndex / maxVisualRow));

                // --- 2. AMPHITHEATER SHAPE ---
                const dx = q - centerQ;
                const dy = r - centerR;
                const distSq = dx*dx + dy*dy;
                const dist = Math.sqrt(distSq);

                // Base Height: Bowl shape (higher at edges)
                let rawHeight = dist * 1.3;

                // --- 3. THE STAGE MASK (Visual Clarity) ---
                // Heavily penalize height at the bottom to ensure the player can see "into" the arena
                let visibilityMask = 1.0;
                if (screenY > 0.5) {
                    const t = (screenY - 0.5) / 0.5;
                    visibilityMask = 1.0 - (t * t); // Quadratic falloff
                }

                // Apply Noise & Mask
                const noise = (Math.sin(q * 0.8) + Math.cos(r * 0.7)) * 1.5;
                let finalTier = Math.floor((rawHeight + noise) * visibilityMask);

                // Clamp
                finalTier = Math.max(0, Math.min(MAX_TERRAIN_TIER, finalTier));

                // Force Flatten Center
                if (dist < 2.5) finalTier = 0;

                tiers.set(k, finalTier);
            }
        }

        // --- 4. SMOOTHING PASS ---
        // Creates more natural, walkable hills instead of random spikes
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = tier;
            let count = 1;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) {
                    sum += tiers.get(nk)!;
                    count++;
                }
            });
            smoothedTiers.set(key, Math.round(sum / count));
        });

        // Write Heights
        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        // --- 5. OBSTACLES (SPARSE) ---
        this.generateDecorations(system, engine, W, H, smoothedTiers);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(
        system: MapSystem, 
        engine: GameEngine, 
        W: number, 
        H: number, 
        tiers: Map<string, number>
    ) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        system.getMapKeys().forEach((key) => {
            const [q, r] = key.split(',').map(Number);

            // Safety: Existing units check
            if (engine.getAgentAt(q, r)) return;

            // Metrics
            const tier = tiers.get(key) || 0;
            const visualRowIndex = r + (q * 0.5);
            const maxVisualRow = H + (W * 0.5);
            const screenY = visualRowIndex / maxVisualRow;

            const dx = q - centerQ;
            const dy = r - centerR;
            const distFromCenter = Math.sqrt(dx*dx + dy*dy);

            // --- RULE 1: FOREGROUND CLEARANCE ---
            // Absolutely NO obstacles in the bottom 40% of the screen.
            // This prevents "pillars in your face".
            if (screenY > 0.6) return;

            // --- RULE 2: ARENA OPENING ---
            // Keep the center fighting pit strictly clear.
            if (distFromCenter < 2.5) return;

            // --- RULE 3: DENSITY CONTROL ---
            // Much lower base probabilities to avoid locking the map.
            let probability = 0.0;

            if (tier >= 4) {
                // High Ground (Backdrop): Moderate density to form a "wall"
                probability = 0.30; 
            } else if (tier >= 2) {
                // Mid Ground: Sparse tactical cover
                probability = 0.10;
            } else {
                // Low Ground: Almost empty
                probability = 0.02;
            }

            // --- RULE 4: NATURAL CLUMPING ---
            // Instead of white noise, use a wave function to create "groves".
            // If the noise value is low, we force probability to 0.
            // This creates natural "lanes" between obstacles.
            const clumpNoise = Math.sin(q * 1.2) * Math.cos(r * 1.2);

            // Only spawn if we are in a "positive noise" area
            if (clumpNoise > 0.2) {
                if (Math.random() < probability) {
                    system.setObstacle(q, r, obstacleType);
                }
            }
        });
    }
}

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * 🗺️ TACTICAL MAP GENERATOR v3.0 (Heart Arena)
 * Philosophy: "The Open Heart"
 * 
 * Changes:
 * 1. Topology: Terrain height follows a modified heart-shape function to create a natural arena.
 * 2. Obstacles: DRASTICALLY reduced count. Only spawns in small clusters on high ground.
 * 3. Flow: Guaranteed clear paths in the center and foreground.
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Use an odd number for perfect centering
        engine.mapConfig.w = 11; 
        engine.mapConfig.h = 11; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                // --- 1. NORMALIZED COORDINATES ---
                // Map q,r to -1..1 space for shape functions
                const nx = (q - centerQ) / (centerQ + 1);
                const ny = (r - centerR) / (centerR + 1);

                // Visual Y (Screen depth) for foreground culling
                // In diamond grid, 'Down' is roughly q+r direction
                const screenY = (q + r) / (W + H);

                // --- 2. HEART SHAPE TOPOLOGY ---
                // Math: (x^2 + y^2 - 1)^3 - x^2 * y^3 = 0
                // We adjust coordinate space to fit the grid
                const hx = nx * 1.2; 
                const hy = ny * 1.2 + 0.2; // Shift up slightly to fit tip

                const a = hx*hx + hy*hy - 1;
                const heartVal = a*a*a - hx*hx*hy*hy*hy;

                let rawTier = 0;

                if (heartVal <= 0) {
                    // Inside Heart -> Arena Floor
                    rawTier = 0;

                    // Add slight noise to floor for texture, but keep it walkable (Tier 0 or 1)
                    if (Math.random() > 0.7 && Math.abs(hx) > 0.3) rawTier = 1;
                } else {
                    // Outside Heart -> Walls/High Ground
                    // Gradient height based on distance from heart boundary
                    rawTier = 2 + Math.min(4, Math.floor(heartVal * 20));
                }

                // --- 3. FOREGROUND CUT ---
                // Force the bottom of the screen (closest to camera) to be low ground
                // This prevents "High Walls" blocking the view
                if (screenY > 0.6) {
                    rawTier = 0;
                }

                // Clamp
                rawTier = Math.max(0, Math.min(MAX_TERRAIN_TIER, rawTier));
                tiers.set(k, rawTier);
            }
        }

        // --- 4. SMOOTHING ---
        // Soften the jagged edges of the generated shape
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = tier;
            let count = 1;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) {
                    sum += tiers.get(nk)!;
                    count++;
                }
            });
            smoothedTiers.set(key, Math.round(sum / count));
        });

        // Apply Height
        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        // --- 5. DECORATION (Sparse) ---
        this.generateDecorations(system, engine, W, H, smoothedTiers);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(
        system: MapSystem, 
        engine: GameEngine, 
        W: number, 
        H: number, 
        tiers: Map<string, number>
    ) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';

        system.getMapKeys().forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = tiers.get(key) || 0;
            const screenY = (q + r) / (W + H);

            // RULE 1: ABSOLUTE CLEARANCE ZONES
            // - Center of map (Arena)
            // - Bottom of map (Foreground)
            // - Ramps (Tier 1) to ensure walkability
            const distFromCenter = Math.sqrt((q - (W-1)/2)**2 + (r - (H-1)/2)**2);

            if (screenY > 0.55) return; // Foreground clear
            if (distFromCenter < 3.5) return; // Arena clear
            if (tier === 1) return; // Ramps clear

            // RULE 2: VERY LOW DENSITY
            let chance = 0.0;

            if (tier >= 3) {
                // High Ground: Occasional pillars (Backdrop)
                chance = 0.15; 
            } else if (tier === 0 || tier === 2) {
                // Ground/Mid: Very sparse cover
                chance = 0.03;
            }

            // RULE 3: STRICT CLUMPING
            // Only spawn if noise is HIGH. This creates "Groves" rather than "Noise".
            const clump = Math.sin(q * 0.9) * Math.cos(r * 0.9);

            if (clump > 0.6) { 
                if (Math.random() < chance) {
                    system.setObstacle(q, r, obstacleType);
                }
            }
        });
    }
}

