                system.registerTile(q, r);

                // --- 1. VISUAL COORDINATE MAPPING ---
                // visualY: 0.0 (Top/Back) -> 1.0 (Bottom/Front)
                // visualX: -1.0 (Left) -> 1.0 (Right)
                // In Isometric Diamond grid, 'Down' on screen is roughly direction of (q + r)
                const visualRowIndex = r + q * 0.6; // Skewed slightly
                const maxVisualRow = H + W * 0.6;
                const screenY = visualRowIndex / maxVisualRow;

                const visualX = (q - centerQ) / (W * 0.6);

                // --- 2. THE AMPHITHEATER RAMPS ---
                // Base Height increases as we go UP screen (screenY -> 0)
                // And increases as we go to SIDES (abs(visualX) -> 1)

                let rawHeight = (1.0 - screenY) * 5.0; // Back is high (up to 5 tiers)
                rawHeight += Math.abs(visualX) * 2.5;  // Sides add height (up to 2.5 tiers)

                // --- 3. FRACTAL NOISE ---
                // Add roughness so it looks like terrain, not a perfect bowl
                const noise1 = Math.sin(q * 0.7) * Math.cos(r * 0.6) * 1.5;
                const noise2 = Math.cos(q * 1.3 + r * 0.2) * 1.0;

                let tier = rawHeight + noise1 + noise2;

                // --- 4. THE FOREGROUND COLLAPSE (The "Cut") ---
                // We want the front to be absolutely clear.
                // If ScreenY > 0.6 (Bottom 40%), force height down rapidly.

                if (screenY > 0.65) {
                    // Force flat ground at very front
                    tier = 0; 
                } else if (screenY > 0.45) {
                    // Transition zone: Dampen height significantly
                    tier *= 0.3; 
                }

                // --- 5. CENTER ARENA FLATTENING ---
                // Create a fighting pit in the middle so units aren't fighting on a slope
                const distFromCenter = Math.sqrt(Math.pow(q - centerQ, 2) + Math.pow(r - centerR, 2));
                if (distFromCenter < 2.0) {
                    tier = Math.min(1, tier); // Force center to be max Tier 1
                }

                // --- 6. QUANTIZE (Make Steps) ---
                // Use Math.floor to create flat walkable terraces instead of slopes
                let finalTier = Math.floor(Math.max(0, tier));

                // Cap at Max
                finalTier = Math.min(MAX_TERRAIN_TIER, finalTier);

                tiers.set(k, finalTier);
            }
        }

        // --- 7. LOGICAL SMOOTHING ---
        // Ensure no single-tile holes (unwalkable pits)
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((val, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = val, maxN = val;
            let sum = val;
            let count = 1;

            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) {
                    const nt = tiers.get(nk)!;
                    minN = Math.min(minN, nt);
                    maxN = Math.max(maxN, nt);
                    sum += nt;
                    count++;
                }
            });

            // If this tile is a deep pit (much lower than all neighbors), raise it
            if (val < minN - 1) {
                smoothedTiers.set(key, minN);
            } 
            // If strictly a spike, lower it slightly
            else if (val > maxN + 1) {
                smoothedTiers.set(key, maxN);
            }
            else {
                smoothedTiers.set(key, val);
            }
        });

        // Apply
        smoothedTiers.forEach((t, k) => {
            system.setHeight(k, t * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H, smoothedTiers);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(
        system: MapSystem, 
        engine: GameEngine, 
        W: number, 
        H: number, 
        tiers: Map<string, number>
    ) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';

        system.getMapKeys().forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            const tier = tiers.get(key) || 0;
            const screenY = (r + q * 0.6) / (H + W * 0.6);

            // 1. ABSOLUTE CLEARANCE: Foreground
            if (screenY > 0.6) return; 

            // 2. HIGH GROUND BIAS
            // Obstacles spawn mostly on high ground (Ridges) to accentuate the height
            // Low ground (Arena) is mostly clear for combat.

            let chance = 0.02; // Base very low

            if (tier >= 4) {
                chance = 0.25; // High cliffs have cover
            } else if (tier >= 2) {
                chance = 0.10; // Mid terraces have sparse cover
            } else {
                chance = 0.01; // Low ground is almost empty
            }

            // 3. NOISE CLUMPING
            const noise = Math.sin(q * 1.1) * Math.cos(r * 1.1);
            if (noise > 0.5) {
                if (Math.random() < chance) {
                    system.setObstacle(q, r, obstacleType);
                }
            }
        });
    }
}

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * 🗺️ TACTICAL MAP GENERATOR v5.0 (Heart Platform)
 * Philosophy: "Shaped Battlefield, Open Flow"
 * 
 * Changes:
 * 1. Topology: Grid is culled to a Heart Shape function.
 * 2. Verticality: Flatter, playable platform (Tier 2 base) instead of steep pyramid.
 * 3. Obstacles: Minimal density to prevent locking.
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Slightly larger bounds to fit the shape
        engine.mapConfig.w = 12; 
        engine.mapConfig.h = 12; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        // SCALE: Controls how big the heart is relative to the grid
        const scale = 3.5; 

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {

                // --- 1. COORDINATE MAPPING (Grid -> Cartesian) ---
                // We map the Diamond Grid (q,r) to Cartesian (x,y) for the shape function.
                // Screen X ~ (q - r)
                // Screen Y ~ (q + r)

                // We want the Heart to be upright on the screen.
                // Up/Down on screen is (q+r).
                // Left/Right on screen is (q-r).

                const u = (q - centerQ - (r - centerR)) / scale;      // X-axis (Width)
                const v = -1 * (q - centerQ + (r - centerR)) / scale; // Y-axis (Height, inverted so -Y is Down)

                // Shift V slightly up so the heart is centered
                const vOffset = v + 0.3;

                // --- 2. HEART SHAPE FORMULA ---
                // (x^2 + y^2 - 1)^3 - x^2 * y^3 = 0
                const a = u*u + vOffset*vOffset - 1;
                const heartVal = a*a*a - u*u * vOffset*vOffset*vOffset;

                // --- 3. TILE CULLING ---
                // If outside heart, skip registration (Void)
                if (heartVal > 0) continue;

                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                // --- 4. TERRAIN HEIGHT ---
                // Base platform height
                let tier = 2; 

                // Slight elevation at the back (Lobes) for visibility
                // vOffset > 0 is the top (lobes), vOffset < 0 is the tip
                if (vOffset > 0.5) tier += 1;

                // Add mild noise for texture, but keep it walkable
                // Avoid the "Pointy Pyramid" look by using low frequency noise
                const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
                if (noise > 0.7) tier += 1;
                if (noise < -0.7) tier -= 1;

                // Clamp
                tier = Math.max(1, Math.min(MAX_TERRAIN_TIER, tier));
                tiers.set(k, tier);
            }
        }

        // Apply Heights
        tiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        // --- 5. DECORATION (Minimalist) ---
        this.generateDecorations(system, engine, W, H, tiers);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(
        system: MapSystem, 
        engine: GameEngine, 
        W: number, 
        H: number, 
        tiers: Map<string, number>
    ) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';

        system.getMapKeys().forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            // --- OBSTACLE RESTRAINT ---
            // Only 5% base chance (very sparse)
            // Restricted to specific noise bands to create "clumps" rather than noise

            const noise = Math.sin(q * 0.5) * Math.cos(r * 0.5);

            // Only spawn in "dense" noise pockets, leaving wide open paths elsewhere
            if (noise > 0.8) {
                if (Math.random() < 0.3) {
                    system.setObstacle(q, r, obstacleType);
                }
            }
        });
    }
}

