import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);
// Rotation Constants (45 degrees)
const COS_45 = 0.70710678; // Math.cos(Math.PI / 4)
const SIN_45 = 0.70710678; // Math.sin(Math.PI / 4)

export const HexMath = {

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * FFT Style Isometric Mapping
     * Steps:
     * 1. Convert to Standard Cartesian (Pointy Top Basis)
     * 2. Rotate World 45 Degrees
     * 3. Apply Y-Squash
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        // Note: layout is ignored for coordinate calculation to enforce FFT style, 
        // but can still be used for shape drawing later.

        // 1. Raw Cartesian (Standard Pointy Top)
        const size = HEX_SIZE;
        const x_raw = (SQRT3 * q + SQRT3 / 2.0 * r) * size;
        const y_raw = (1.5 * r) * size;

        // 2. Rotate 45 Degrees
        // Matrix: [ cos -sin ]
        //         [ sin  cos ]
        const rx = x_raw * COS_45 - y_raw * SIN_45;
        const ry = x_raw * SIN_45 + y_raw * COS_45;

        // 3. Isometric Projection (Squash Y) + Offset
        return {
            x: offsetX + rx,
            y: offsetY + ry * ISO_SCALE_Y
        };
    },

    /**
     * Inverse Mapping (Screen -> Hex)
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const size = HEX_SIZE;

        // 1. Remove Offset
        const dx = x - offsetX;
        const dy = y - offsetY;

        // 2. Un-squash Y
        const ry = dy / ISO_SCALE_Y;
        const rx = dx; // X is not squashed

        // 3. Inverse Rotate (-45 Degrees)
        // Matrix: [  cos  sin ]
        //         [ -sin  cos ]
        const x_raw = rx * COS_45 + ry * SIN_45;
        const y_raw = -rx * SIN_45 + ry * COS_45;

        // 4. Cartesian to Hex (Pointy Top Inverse)
        // x = size * (sqrt(3)q + sqrt(3)/2 r)
        // y = size * (3/2 r)
        // -> r = y / 1.5 / size
        // -> q = (x/size - sqrt(3)/2 * r) / sqrt(3)
        const q = ( (SQRT3 / 3.0) * x_raw - (1.0 / 3.0) * y_raw ) / size;
        const r = ( (2.0 / 3.0) * y_raw ) / size;

        return { q, r };
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexLayout } from "../../../types";

/**
 * 核心六邊形幾何真理 (Single Source of Truth) - V4.0 Rotated (FFT)
 * 修正了旋轉物體在 ISO 視角下變形的問題，並應用了全域 45 度旋轉。
 */
export const HexGeometry = {

    /**
     * 獲取標準化頂點
     * @param radius 半徑
     * @param applyIso 是否應用 2.5D 壓扁
     * @param layout 佈局模式 (FLAT | POINTY)
     */
    getVertices(radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT'): {x: number, y: number}[] {
        const vertices = [];
        // FLAT: 頂部平坦 (0 deg) | POINTY: 頂部尖銳 (30 deg)
        // GLOBAL ROTATION: +45 deg (PI/4)
        const baseStartAngle = layout === 'FLAT' ? 0 : Math.PI / 6;
        const rotationOffset = Math.PI / 4; 

        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = baseStartAngle + i * Math.PI / 3 + rotationOffset;
            vertices.push({ 
                x: Math.cos(angle) * radius, 
                y: Math.sin(angle) * radius * scaleY 
            });
        }
        return vertices;
    },

    /**
     * 在 Context 上描繪標準路徑
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * 向量旋轉繪製 - 物理正確版
     * 先在邏輯平面 (Top Down) 旋轉，再進行 ISO 投影。
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        // 1. Get RAW vertices (No ISO scale yet, but WITH 45 deg base rotation)
        const verts = this.getVertices(radius, false, layout);

        const cosR = Math.cos(rotation);
        const sinR = Math.sin(rotation);
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const vx = verts[i].x;
            const vy = verts[i].y;

            // 2. Rotate on 2D Plane (XZ Logic)
            const rx = vx * cosR - vy * sinR;
            const ry = vx * sinR + vy * cosR;

            // 3. Apply ISO Projection (Squash Y)
            const projectedX = rx;
            const projectedY = ry * scaleY;

            if (i === 0) ctx.moveTo(x + projectedX, y + projectedY);
            else ctx.lineTo(x + projectedX, y + projectedY);
        }
        ctx.closePath();
    }
};

