import { Hex, Point, Cube, HexLayout } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

export { Cube };

const SQRT3 = Math.sqrt(3);
// Rotation Constants (45 degrees)
const COS_45 = 0.70710678; // Math.cos(Math.PI / 4)
const SIN_45 = 0.70710678; // Math.sin(Math.PI / 4)

export const HexMath = {

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    /**
     * FFT Style Isometric Mapping (Rotated 45°)
     * Supports both FLAT and POINTY layouts.
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number, layout: HexLayout): Point {
        const size = HEX_SIZE;
        let x_raw = 0;
        let y_raw = 0;

        // 1. Convert Axial to Cartesian (2D Plane)
        if (layout === 'FLAT') {
            // Flat Topped: q axis is horizontal-ish
            x_raw = size * (3.0 / 2.0 * q);
            y_raw = size * (SQRT3 / 2.0 * q + SQRT3 * r);
        } else {
            // Pointy Topped: r axis is vertical-ish (Default)
            x_raw = size * (SQRT3 * q + SQRT3 / 2.0 * r);
            y_raw = size * (1.5 * r);
        }

        // 2. Rotate 45 Degrees (World Rotation)
        // Matrix: [ cos -sin ]
        //         [ sin  cos ]
        const rx = x_raw * COS_45 - y_raw * SIN_45;
        const ry = x_raw * SIN_45 + y_raw * COS_45;

        // 3. Isometric Projection (Squash Y) + Offset
        return {
            x: offsetX + rx,
            y: offsetY + ry * ISO_SCALE_Y
        };
    },

    /**
     * Inverse Mapping (Screen -> Hex)
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number, layout: HexLayout): Hex {
        const size = HEX_SIZE;

        // 1. Remove Offset
        const dx = x - offsetX;
        const dy = y - offsetY;

        // 2. Un-squash Y
        const ry = dy / ISO_SCALE_Y;
        const rx = dx; // X is not squashed

        // 3. Inverse Rotate (-45 Degrees)
        // Matrix: [  cos  sin ]
        //         [ -sin  cos ]
        const x_raw = rx * COS_45 + ry * SIN_45;
        const y_raw = -rx * SIN_45 + ry * COS_45;

        // 4. Cartesian to Hex (Layout Specific Inverse)
        let q, r;

        if (layout === 'FLAT') {
            // Inverse Flat
            // x = size * 1.5 * q  => q = x / 1.5 / size
            q = x_raw / (1.5 * size);

            // y = size * sqrt(3) * (q/2 + r) => r = y / size / sqrt(3) - q/2
            r = (y_raw / (size * SQRT3)) - (q / 2.0);
        } else {
            // Inverse Pointy
            // y = size * 1.5 * r => r = y / 1.5 / size
            r = y_raw / (1.5 * size);

            // x = size * sqrt(3) * (q + r/2) => q = x / size / sqrt(3) - r/2
            q = (x_raw / (size * SQRT3)) - (r / 2.0);
        }

        return { q, r };
    },

    distance(a: Hex, b: Hex): number {
        const ac = this.axialToCube(a);
        const bc = this.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = this.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(this.cubeToAxial(this.cubeRound(cubeLerp)));
        }
        return results;
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * 🗺️ TACTICAL MAP GENERATOR v5.1 (Heart Platform - Compact)
 * Philosophy: "Shaped Battlefield, Open Flow, 10x10 Limit"
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        // Enforce 10x10 Map Size
        engine.mapConfig.w = 10; 
        engine.mapConfig.h = 10; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;

        // SCALE: Adjusted for 10x10 grid to ensure full heart shape is visible
        const scale = 3.0; 

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {

                // --- 1. COORDINATE MAPPING (Grid -> Cartesian) ---
                const u = (q - centerQ - (r - centerR)) / scale;      // X-axis
                const v = -1 * (q - centerQ + (r - centerR)) / scale; // Y-axis

                // Shift V slightly up so the heart is centered
                const vOffset = v + 0.3;

                // --- 2. HEART SHAPE FORMULA ---
                // (x^2 + y^2 - 1)^3 - x^2 * y^3 = 0
                const a = u*u + vOffset*vOffset - 1;
                const heartVal = a*a*a - u*u * vOffset*vOffset*vOffset;

                // --- 3. TILE CULLING ---
                // If outside heart, skip registration (Void)
                if (heartVal > 0) continue;

                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                // --- 4. TERRAIN HEIGHT ---
                // Base platform height
                let tier = 2; 

                // Slight elevation at the back (Lobes) for visibility
                if (vOffset > 0.5) tier += 1;

                // Add mild noise for texture
                const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
                if (noise > 0.7) tier += 1;
                if (noise < -0.7) tier -= 1;

                // Clamp
                tier = Math.max(1, Math.min(MAX_TERRAIN_TIER, tier));
                tiers.set(k, tier);
            }
        }

        // Apply Heights
        tiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        // --- 5. DECORATION ---
        this.generateDecorations(system, engine, W, H, tiers);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(
        system: MapSystem, 
        engine: GameEngine, 
        W: number, 
        H: number, 
        tiers: Map<string, number>
    ) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';

        system.getMapKeys().forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;

            // --- OBSTACLE RESTRAINT ---
            const noise = Math.sin(q * 0.5) * Math.cos(r * 0.5);

            // Only spawn in "dense" noise pockets
            if (noise > 0.8) {
                if (Math.random() < 0.3) {
                    system.setObstacle(q, r, obstacleType);
                }
            }
        });
    }
}

