        let cx, cy; // 平面直角座標 (Cartesian)

        // 1. 根據網格類型 (Flat/Pointy) 取得基礎平面座標
        // 預設為 POINTY，若 config.orientation 存在且為 FLAT 則切換
        if (config.layout === 'FLAT') {
            cx = size * (3/2 * q);
            cy = size * (Math.sqrt(3)/2 * q + Math.sqrt(3) * r);
        } else {
            cx = size * (Math.sqrt(3) * q + Math.sqrt(3)/2 * r);
            cy = size * (3/2 * r);
        }

        // 2. 執行世界旋轉 (45度)
        // x' = x*cos - y*sin
        // y' = x*sin + y*cos
        const rx = cx * COS_R - cy * SIN_R;
        const ry = cx * SIN_R + cy * COS_R;

        // 3. 執行視角壓縮與位移
        return {
            x: config.offsetX + rx,
            y: config.offsetY + ry * ISO_SCALE_Y
        };
    },

    /**
     * Inverse Projection (Mouse Picking)
     * Logic: Un-squash -> Rotate -45 -> Cartesian -> Hex
     */
    fromPx: (screenX: number, screenY: number, config: MapConfig): Hex => {
        const size = HEX_SIZE;

        // 1. 移除位移
        const dx = screenX - config.offsetX;
        const dy = screenY - config.offsetY;

        // 2. 還原 Y 軸壓縮
        const ry = dy / ISO_SCALE_Y;
        const rx = dx;

        // 3. 反向旋轉 (-45度)
        // Inverse Matrix: sin 變號
        const cx = rx * COS_R + ry * SIN_R;
        const cy = -rx * SIN_R + ry * COS_R;

        // 4. 還原 Hex 座標
        let q, r;
        if (config.layout === 'FLAT') {
            q = (2/3 * cx) / size;
            r = (-1/3 * cx + Math.sqrt(3)/3 * cy) / size;
        } else {
            q = (Math.sqrt(3)/3 * cx - 1/3 * cy) / size;
            r = (2/3 * cy) / size;
        }

        return HexUtils.round(q, r);
    },

    round: (q: number, r: number): Hex => {
        const c = HexMath.cubeRound({x: q, z: r, y: -q-r});
        return { q: c.x, r: c.z };
    },

    dist: (a: Hex, b: Hex): number => {
        return HexMath.distance(a, b);
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    key: (h: Hex): string => `${h.q},${h.r}`,

    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        return HexMath.range(center, n);
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { HexLayout } from "../../../types";

const Y_SCALE = 0.57735; // Standard ISO scale matching utils.ts

/**
 * 核心六邊形幾何真理 (Single Source of Truth) - V5.0 Math Reset
 * Aligned with Utils.ts 45-degree World Rotation
 */
export const HexGeometry = {

    /**
     * 獲取標準化頂點
     * @param radius 半徑
     * @param applyIso 是否應用 2.5D 壓扁
     * @param layout 佈局模式 (FLAT | POINTY)
     */
    getVertices(radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT'): {x: number, y: number}[] {
        const vertices = [];

        // 1. 確保壓縮比與 Utils 一致
        const scaleY = applyIso ? Y_SCALE : 1.0;

        // 2. 計算起始角度
        // Pointy (尖頂) 預設 30度 (PI/6)
        // Flat (平頂) 預設 0度
        // 必須加上 45度 (PI/4) 的世界旋轉
        const baseAngle = layout === 'FLAT' ? 0 : Math.PI / 6;
        const startAngle = baseAngle + Math.PI / 4; 

        // 3. 產生頂點 (Vertices Generation)
        for (let i = 0; i < 6; i++) {
            const angle = startAngle + i * Math.PI / 3;
            vertices.push({ 
                x: Math.cos(angle) * radius, 
                y: Math.sin(angle) * radius * scaleY 
            });
        }
        return vertices;
    },

    /**
     * 在 Context 上描繪標準路徑
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const verts = this.getVertices(radius, applyIso, layout);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * 向量旋轉繪製 - 物理正確版
     * 先在邏輯平面 (Top Down) 旋轉，再進行 ISO 投影。
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true, layout: HexLayout = 'FLAT') {
        const scaleY = applyIso ? Y_SCALE : 1.0;

        // Base vertices already have the 45 degree offset built in.
        // To apply EXTRA rotation (animation), we need to do it carefully.
        // Actually, getVertices returns projected points if applyIso=true.
        // We need raw points first.

        const verts = this.getVertices(radius, false, layout);

        const cosR = Math.cos(rotation);
        const sinR = Math.sin(rotation);

        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const vx = verts[i].x;
            const vy = verts[i].y;

            // Apply Additional Rotation
            const rx = vx * cosR - vy * sinR;
            const ry = vx * sinR + vy * cosR;

            // Apply ISO Projection
            const projectedX = rx;
            const projectedY = ry * scaleY;

            if (i === 0) ctx.moveTo(x + projectedX, y + projectedY);
            else ctx.lineTo(x + projectedX, y + projectedY);
        }
        ctx.closePath();
    }
};
